select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'breach_fields' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION private.breach_fields(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v jsonb := '{}'::jsonb; k text;
begin
  foreach k in array array['discovered_at', 'occurred_at', 'summary', 'data_involved', 'people_affected', 'risk', 'risk_reasoning', 'containment',
                           'oipc_notified_at', 'opc_notified_at', 'individuals_notified_at', 'status'] loop
    if p ? k then v := v || jsonb_build_object(k, case when jsonb_typeof(p -> k) = 'string' then nullif(btrim(p ->> k), '')::text end); end if;
  end loop;
  return v;
end $function$
;$bos$, $bos$drop function if exists private.breach_fields(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'bug_screenshot_upload_ok' and pg_get_function_identity_arguments(p.oid) = $bos$p_name text$bos$), $bos$CREATE OR REPLACE FUNCTION private.bug_screenshot_upload_ok(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id text; r public.bug_reports;
begin
  if p_name is null or p_name !~ '^reports/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png)$' then return false; end if;
  v_id := substring(p_name from 9 for 36);
  -- the bucket overall
  if (select count(*) from storage.objects o where o.bucket_id = 'bug-screenshots' and o.created_at > now() - interval '1 hour') >= 30
     or (select count(*) from storage.objects o where o.bucket_id = 'bug-screenshots' and o.created_at > now() - interval '1 day') >= 100 then
    return false;
  end if;
  select * into r from public.bug_reports b where b.id = v_id::uuid;
  if found then
    -- the signed path: a report sent in the last 15 minutes, with no screenshot yet, and no file already uploaded for it
    return r.created_at > now() - interval '15 minutes' and r.screenshot_path is null
       and not exists (select 1 from storage.objects o where o.bucket_id = 'bug-screenshots' and o.name like 'reports/' || v_id || '.%');
  end if;
  -- an older app: upload first, report after. Kept working, with a small allowance for everyone together.
  return (select count(*) from storage.objects o where o.bucket_id = 'bug-screenshots' and o.created_at > now() - interval '1 hour'
            and not exists (select 1 from public.bug_reports b where b.id::text = substring(o.name from 9 for 36))) < 5
     and (select count(*) from storage.objects o where o.bucket_id = 'bug-screenshots' and o.created_at > now() - interval '1 day'
            and not exists (select 1 from public.bug_reports b where b.id::text = substring(o.name from 9 for 36))) < 20;
end $function$
;$bos$, $bos$drop function if exists private.bug_screenshot_upload_ok(p_name text);$bos$);
