 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v text;
begin
  loop
    v := substr(translate(upper(encode(decode(replace(gen_random_uuid()::text, '-', ''), 'hex'), 'base64')), '+/=0O1IL', ''), 1, 10);
    exit when char_length(v) = 10 and not exists (select 1 from public.cards where verify_code = v);
  end loop;
  return v;
end $function$
;$bos$, $bos$drop function if exists private.card_new_code();$bos$);
