select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'card_profile_json' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid, p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.card_profile_json(p_fighter uuid, p_team uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with f as (select * from public.fighters where id = p_fighter and inactive_at is null),
  syn as (select private.is_synthetic('fighter', p_fighter) as s),
  minor as (select coalesce((select f.birth_year > extract(year from now())::int - 13 from f), false) as m),
  mem as (select tm.role, tm.mercenary from public.team_memberships tm
           where tm.fighter_id = p_fighter and tm.team_id = p_team and (tm.to_date is null or tm.to_date >= current_date)
           order by (tm.role = 'captain') desc limit 1),
  ent as (select en.id as entry_id, en.competition_id from public.entries en where en.fighter_id = p_fighter
          union
          select ef.entry_id, ef.competition_id from public.entry_fighters ef where ef.fighter_id = p_fighter),
  x as (select e.id, e.name, e.slug, e.starts_on, c.category, r.final_place
          from ent
          join public.competitions c on c.id = ent.competition_id
          join public.events e on e.id = c.event_id
          left join public.results r on r.entry_id = ent.entry_id
         where e.archived_at is null and e.starts_on <= current_date
           and private.is_synthetic('event', e.id) = (select s from syn)),
  ev as (select id, name, slug, starts_on, min(final_place) as best from x group by id, name, slug, starts_on),
  pod as (select final_place, category, name, starts_on from x where final_place between 1 and 3
           order by final_place, starts_on desc limit 8)
  select jsonb_build_object(
    'id', f.id, 'display_name', f.display_name,
    'role', (select role from mem), 'mercenary', coalesce((select mercenary from mem), false),
    'joined_year', f.joined_year, 'disciplines', to_jsonb(coalesce(f.disciplines, '{}'::text[])),
    'fighting_style', f.fighting_style, 'bio', f.bio,
    'highlights', coalesce((select jsonb_agg(h) from unnest(f.highlights) h
                            where h !~* '(record|rank|[0-9]+ *- *[0-9]+|\mwins?\M|\mloss(es)?\M|weigh|height)'), '[]'::jsonb),
    'city', f.city, 'region', f.region, 'country', f.country,
    'under_13', (select m from minor), 'practice', (select s from syn),
    'photos', case when (select m from minor) then '[]'::jsonb else coalesce((
        select jsonb_agg(p.j order by p.o) from (
          select jsonb_build_object('bucket', 'avatars', 'path', f.avatar_path) as j, -1 as o where f.avatar_path is not null
          union all
          select jsonb_build_object('bucket', 'fighter-gallery', 'path', g.storage_path), coalesce(g.sort_order, 0)
            from public.fighter_gallery g where g.fighter_id = f.id) p), '[]'::jsonb) end,
    'events', coalesce((select jsonb_agg(jsonb_build_object('name', ev.name, 'slug', ev.slug, 'year', extract(year from ev.starts_on)::int, 'best', ev.best)
                                         order by ev.starts_on desc) from ev), '[]'::jsonb),
    'podiums', coalesce((select jsonb_agg(jsonb_build_object('place', pod.final_place, 'category', pod.category, 'event', pod.name,
                                                             'year', extract(year from pod.starts_on)::int)
                                          order by pod.final_place, pod.starts_on desc) from pod), '[]'::jsonb),
    'categories', coalesce((select jsonb_agg(distinct x.category) from x where x.category is not null), '[]'::jsonb))
  from f
$function$
;$bos$, $bos$drop function if exists private.card_profile_json(p_fighter uuid, p_team uuid);$bos$);
