 SET search_path TO ''
AS $function$
begin
  return query
  with b as materialized (select private.caller_bypasses_rls() as bypass),
  who as not materialized (
    select e.id as entry_id, e.fighter_id, null::text as roster_role from public.entries e where p_fighter is not null and e.fighter_id = p_fighter
    union all
    select ef.entry_id, ef.fighter_id, ef.role from public.entry_fighters ef where p_fighter is not null and ef.fighter_id = p_fighter
    union all
    select e.id, e.fighter_id, null::text from public.entries e where p_team is not null and e.fighter_id is not null and e.represented_team_id = p_team
    union all
    select ef.entry_id, ef.fighter_id, ef.role from public.entry_fighters ef join public.entries e on e.id = ef.entry_id
      where p_team is not null and (e.team_id = p_team or (e.team_id is null and e.represented_team_id = p_team))
  ), sides as (
    select w.fighter_id, w.roster_role, m.id as match_id, m.competition_id, m.stage, m.round_label, m.finalized_at, m.result, m.winner_entry_id, m.detail,
           m.entry_a as me, m.entry_b as opp, m.score_a as sf, m.score_b as sa
    from who w join public.matches m on m.entry_a = w.entry_id where m.queue_state = 'final' and m.entry_b is not null
    union all
    select w.fighter_id, w.roster_role, m.id, m.competition_id, m.stage, m.round_label, m.finalized_at, m.result, m.winner_entry_id, m.detail,
           m.entry_b, m.entry_a, m.score_b, m.score_a
    from who w join public.matches m on m.entry_b = w.entry_id where m.queue_state = 'final' and m.entry_a is not null
  ), r as materialized (
    select s.fighter_id, s.match_id, s.competition_id, k.name as competition_name, k.category, coalesce(rc.name, k.category) as category_name, k.gender, k.tier, k.structure,
      s.stage, s.round_label, ev.id as event_id, ev.slug as event_slug, ev.name as event_name, ev.starts_on, ev.ends_on as event_ends_on, ev.season_id,
      coalesce(ev.organization_id, se.organization_id) as organization_id,
      e.id as entry_id, case when e.team_id is not null then 'team' else 'individual' end as kind, s.roster_role,
      coalesce(e.team_id, e.represented_team_id) as team_id,
      case when e.team_id is not null then coalesce(e.team_name_at_event, t.name) else coalesce(e.represented_team_name_at_event, rt.name) end as team_name,
      coalesce(t.slug, rt.slug) as team_slug,
      o.id as opponent_entry_id, o.fighter_id as opponent_fighter_id, o.team_id as opponent_team_id,
      coalesce(o.team_name_at_event, ot.name, ofi.display_name) as opponent_name, ot.slug as opponent_team_slug,
      case when s.result = 'draw' then 'draw' when s.winner_entry_id = e.id then 'win' else 'loss' end as outcome,
      s.sf as score_for, s.sa as score_against, coalesce((s.detail ->> 'walkover')::boolean, false) as walkover, s.finalized_at
    from sides s cross join b
    join public.entries e on e.id = s.me
    join public.entries o on o.id = s.opp
    join public.competitions k on k.id = s.competition_id
    join public.events ev on ev.id = k.event_id
    left join public.seasons se on se.id = ev.season_id
    left join public.ref_categories rc on rc.code = k.category
    left join public.teams t on t.id = e.team_id and (b.bypass or t.status = 'approved' or private.is_team_captain(t.id) or private.can_admin_team(t.id))
    left join public.teams rt on rt.id = e.represented_team_id and (b.bypass or rt.status = 'approved' or private.is_team_captain(rt.id) or private.can_admin_team(rt.id))
    left join public.teams ot on ot.id = o.team_id and (b.bypass or ot.status = 'approved' or private.is_team_captain(ot.id) or private.can_admin_team(ot.id))
    left join public.fighters ofi on ofi.id = o.fighter_id
  ), v as materialized (select * from private.record_events(array(select distinct r.event_id from r)))
  select r.fighter_id, r.match_id, r.competition_id, r.competition_name, r.category, r.category_name, r.gender, r.tier, r.structure, r.stage, r.round_label,
    r.event_id, r.event_slug, r.event_name, r.starts_on, r.event_ends_on, r.season_id, r.organization_id, r.entry_id, r.kind, r.roster_role, r.team_id, r.team_name,
    r.team_slug, r.opponent_entry_id, r.opponent_fighter_id, r.opponent_team_id, r.opponent_name, r.opponent_team_slug, r.outcome, r.score_for, r.score_against,
    r.walkover, r.finalized_at, v.synthetic, v.stats_excluded
  from r join v on v.event_id = r.event_id;
end
