select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'career_result_rows' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid, p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.career_result_rows(p_fighter uuid, p_team uuid DEFAULT NULL::uuid)
 RETURNS SETOF career_results_all
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  with b as materialized (select private.caller_bypasses_rls() as bypass),
  fp as not materialized (
    select e.fighter_id, e.id as entry_id from public.entries e where p_fighter is not null and e.fighter_id = p_fighter and e.status <> 'withdrawn'
    union all
    select ef.fighter_id, e.id from public.entry_fighters ef join public.entries e on e.id = ef.entry_id where p_fighter is not null and ef.fighter_id = p_fighter and e.status <> 'withdrawn'
    union all
    select e.fighter_id, e.id from public.entries e where p_team is not null and e.fighter_id is not null and e.represented_team_id = p_team and e.status <> 'withdrawn'
    union all
    select ef.fighter_id, e.id from public.entry_fighters ef join public.entries e on e.id = ef.entry_id
      where p_team is not null and (e.team_id = p_team or (e.team_id is null and e.represented_team_id = p_team)) and e.status <> 'withdrawn'
  ), r as materialized (
    select fp.fighter_id, x.competition_id, k.name as competition_name, k.category, coalesce(rc.name, k.category) as category_name, k.gender, k.tier, k.structure,
      x.entry_id, case when e.team_id is not null then 'team' else 'individual' end as kind, e.status as entry_status,
      coalesce(e.team_id, e.represented_team_id) as team_id,
      case when e.team_id is not null then coalesce(e.team_name_at_event, t.name) else coalesce(e.represented_team_name_at_event, rt.name) end as team_name,
      coalesce(t.slug, rt.slug) as team_slug,
      x.final_place, coalesce(x.points, 0) as points,
      ev.id as event_id, ev.slug as event_slug, ev.name as event_name, ev.event_type, ev.starts_on, ev.ends_on as event_ends_on, ev.season_id,
      coalesce(ev.organization_id, se.organization_id) as organization_id
    from fp cross join b
    join public.results x on x.entry_id = fp.entry_id and x.final_place is not null
    join public.entries e on e.id = x.entry_id
    join public.competitions k on k.id = x.competition_id
    join public.events ev on ev.id = k.event_id
    left join public.seasons se on se.id = ev.season_id
    left join public.ref_categories rc on rc.code = k.category
    left join public.teams t on t.id = e.team_id and (b.bypass or t.status = 'approved' or private.is_team_captain(t.id) or private.can_admin_team(t.id))
    left join public.teams rt on rt.id = e.represented_team_id and (b.bypass or rt.status = 'approved' or private.is_team_captain(rt.id) or private.can_admin_team(rt.id))
  ), v as materialized (select * from private.record_events(array(select distinct r.event_id from r)))
  select r.fighter_id, r.competition_id, r.competition_name, r.category, r.category_name, r.gender, r.tier, r.structure, r.entry_id, r.kind, r.entry_status,
    r.team_id, r.team_name, r.team_slug, r.final_place, r.points, r.event_id, r.event_slug, r.event_name, r.event_type, r.starts_on, r.event_ends_on,
    r.season_id, r.organization_id, v.synthetic, v.stats_excluded
  from r join v on v.event_id = r.event_id;
end
