select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'club_membership_admin_notify' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.club_membership_admin_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_team public.teams;
  v_webhook text;
  v_dispatch_secret text;
begin
  select * into v_team
  from public.teams
  where id = new.team_id;

  if not found or v_team.slug <> 'red-deer-reavers' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status is not distinct from new.status then
    return new;
  end if;

  select decrypted_secret
    into v_webhook
  from vault.decrypted_secrets
  where name = 'reavers_discord_membership_webhook'
  order by created_at desc
  limit 1;

  select value
    into v_dispatch_secret
  from private.push_config
  where key = 'dispatch_secret';

  if v_webhook is null or btrim(v_webhook) = '' or v_dispatch_secret is null then
    return new;
  end if;

  perform net.http_post(
    url := 'https://mvbxlebznlgroptwwdsm.supabase.co/functions/v1/reavers-membership-discord-sync',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-dispatch-secret',v_dispatch_secret
    ),
    body := jsonb_build_object(
      'membership_id', new.id,
      'full_name', coalesce(nullif(new.full_name,''),'Member'),
      'team_name', v_team.name,
      'status', new.status,
      'webhook_url', v_webhook
    )
  );

  return new;
exception
  when others then
    raise warning 'Reavers Discord membership status sync failed: %', sqlerrm;
    return new;
end
$function$
