 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with ms as (
    select m.*, private.field_key(m.field) as fk, coalesce(nullif(btrim(m.field), ''), 'Field 1') as fname, k.sort as ksort
    from public.matches m join public.competitions k on k.id = m.competition_id where k.event_id = p_event),
  keys as (select distinct on (fk) fk, fname from ms where queue_state in ('active', 'on_deck', 'in_the_hole') order by fk, fname),
  fields as (
    select ky.fk, jsonb_build_object(
      'field', ky.fname,
      'now', (select private.discord_fight(x.id) from ms x where x.fk = ky.fk and x.queue_state = 'active' order by x.queue_order nulls last, x.id limit 1),
      'next', (select private.discord_fight(x.id) from ms x where x.fk = ky.fk and x.queue_state = 'on_deck' order by x.queue_order nulls last, x.scheduled_at nulls last, x.id limit 1),
      'hole', (select private.discord_fight(x.id) from ms x where x.fk = ky.fk and x.queue_state = 'in_the_hole' order by x.queue_order nulls last, x.scheduled_at nulls last, x.id limit 1)) as f
    from keys ky),
  recent as (
    select jsonb_build_object('a', private.lyst_side_name(x.entry_a), 'b', private.lyst_side_name(x.entry_b), 'result', x.result,
                              'score_a', x.score_a, 'score_b', x.score_b, 'competition_name', k.name, 'field', x.fname) as r, x.finalized_at
    from ms x join public.competitions k on k.id = x.competition_id
    where x.queue_state = 'final' and x.result is not null and x.entry_a is not null and x.entry_b is not null
    order by x.finalized_at desc nulls last limit 5)
