                 where f.event_id = p_event and f.enabled and e.status = 'published') then return; end if;
  insert into public.discord_channels (event_id) values (p_event)
  on conflict (event_id) do update set state = 'wanted', attempts = 0, error = null, wanted_at = now(), claimed_at = null
