select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'discord_dm_enqueue' and pg_get_function_identity_arguments(p.oid) = $bos$p_user uuid, p_event uuid, p_kind text, p_dedupe text, p_payload jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION private.discord_dm_enqueue(p_user uuid, p_event uuid, p_kind text, p_dedupe text, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_l public.discord_links; v_f public.discord_feeds;
begin
  select * into v_l from public.discord_links l where l.user_id = p_user;
  if not found or not v_l.pings or coalesce((v_l.dms ->> p_kind)::boolean, true) = false then return false; end if;
  if p_event is not null then
    select * into v_f from public.discord_feeds where event_id = p_event;
    if found and not v_f.dm_fighters then return false; end if;
  end if;
  insert into public.discord_dms (user_id, discord_user_id, event_id, kind, dedupe_key, payload)
  values (p_user, v_l.discord_user_id, p_event, p_kind, p_dedupe, coalesce(p_payload, '{}'::jsonb) || coalesce(private.discord_event_base(p_event), '{}'::jsonb))
  on conflict (dedupe_key) do nothing;
  return found;
end $function$
