select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'discord_dm_from_notification' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.discord_dm_from_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event uuid; v_kind text; v_title text; v_text text; v_slug text;
begin
  begin
    v_slug := new.payload ->> 'event_slug';
    if v_slug is null then return null; end if;
    select id into v_event from public.events where slug = v_slug;
    if v_event is null then return null; end if;
    if new.kind = 'registration_decided' and coalesce(new.payload ->> 'decision', new.payload ->> 'status') = 'accepted' then
      v_kind := 'registration'; v_title := '✅ You are in'; v_text := 'Your registration for **' || coalesce(new.payload ->> 'event_name', 'the event') || '** is accepted.';
    elsif new.kind = 'inspection_passed' then
      v_kind := 'inspection'; v_title := '🛡️ Kit inspection passed'; v_text := 'Your kit passed inspection at **' || coalesce(new.payload ->> 'event_name', 'the event') || '**.';
    elsif new.kind = 'inspection_needs_correction' then
      v_kind := 'inspection'; v_title := '🛠️ Kit inspection: something to fix';
      v_text := 'Your kit needs a correction at **' || coalesce(new.payload ->> 'event_name', 'the event') || '**' ||
        coalesce(': ' || (select string_agg(x, ', ') from jsonb_array_elements_text(case when jsonb_typeof(new.payload -> 'issues') = 'array' then new.payload -> 'issues' else '[]'::jsonb end) x), '') ||
        coalesce('. ' || nullif(new.payload ->> 'note', ''), '') || '. See the inspector before your first fight.';
    else return null; end if;
    perform private.discord_dm_enqueue(new.user_id, v_event, v_kind, 'notif:' || new.id::text,
      jsonb_build_object('title', v_title, 'text', v_text, 'path', '/events/' || v_slug));
  exception when others then
    raise warning 'discord dm from notification % failed: %', new.id, sqlerrm;
  end;
  return null;
end $function$
;$bos$, $bos$drop function if exists private.discord_dm_from_notification();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'discord_enqueue' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid, p_kind text, p_match uuid, p_dedupe text, p_payload jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION private.discord_enqueue(p_event uuid, p_kind text, p_match uuid, p_dedupe text, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_feed public.discord_feeds; v_status text; v_n integer; v_ping boolean;
begin
  select status into v_status from public.events where id = p_event;
  if v_status is distinct from 'published' then return false; end if;
  select * into v_feed from public.discord_feeds where event_id = p_event;
  if p_kind not in ('test', 'feed_on') then
    if not found or not v_feed.enabled then return false; end if;
    if not v_feed.ping_fighters then p_payload := p_payload - 'mention_ids' - 'role_names'; end if;
    v_ping := v_feed.ping_fighters and (jsonb_array_length(coalesce(p_payload -> 'mention_ids', '[]'::jsonb)) > 0
                                        or (p_kind <> 'correction' and jsonb_array_length(coalesce(p_payload -> 'role_names', '[]'::jsonb)) > 0));
    if (p_kind = 'on_deck' and not v_feed.post_on_deck and not v_ping) or (p_kind = 'now' and not v_feed.post_now and not v_ping)
       or (p_kind in ('hole', 'moved', 'correction') and not v_ping)
       or (p_kind in ('result', 'round', 'milestone', 'podium') and not v_feed.post_results) or (p_kind = 'announcement' and not v_feed.post_announcements) then return false; end if;
    if (p_kind = 'on_deck' and not v_feed.post_on_deck) or (p_kind = 'now' and not v_feed.post_now) or p_kind in ('hole', 'moved') then
      p_payload := p_payload || jsonb_build_object('ping_only', true);
    end if;
    if p_kind = 'on_deck' and v_feed.post_on_deck and v_feed.pickem then p_payload := p_payload || jsonb_build_object('pickem', true); end if;
  end if;
  insert into public.discord_posts (event_id, match_id, kind, dedupe_key, payload)
  values (p_event, p_match, p_kind, p_dedupe, coalesce(p_payload, '{}'::jsonb))
  on conflict (dedupe_key) do nothing;
  get diagnostics v_n = row_count;
  return v_n > 0;
