declare e public.events; v_tz text; v_start timestamptz; v_end timestamptz; v_where text;
begin
  select * into e from public.events where id = p_event;
  if not found then return null; end if;
  v_tz := coalesce(nullif(btrim(e.timezone), ''), 'America/Edmonton');
  begin
    v_start := (e.starts_on + time '09:00') at time zone v_tz;
    v_end := (coalesce(e.ends_on, e.starts_on) + time '18:00') at time zone v_tz;
  exception when others then
    v_start := (e.starts_on + time '09:00') at time zone 'America/Edmonton';
    v_end := (coalesce(e.ends_on, e.starts_on) + time '18:00') at time zone 'America/Edmonton';
  end;
  v_where := nullif(concat_ws(', ', nullif(btrim(e.venue), ''), nullif(btrim(e.city), ''), nullif(btrim(e.region), '')), '');
  return jsonb_build_object(
    'name', left(e.name, 100),
    'description', left(concat_ws(E'\n\n', nullif(btrim(left(e.description, 700)), ''), coalesce(nullif(btrim(e.time_note), ''), 'Times on BuhurtOS.')), 950),
    'location', left(coalesce(v_where, 'See BuhurtOS'), 100),
    'start', v_start, 'end', v_end, 'slug', e.slug);
end $function$
