 SET search_path TO ''
AS $function$
declare v_event uuid; v_kick boolean;
begin
  select k.event_id into v_event from public.matches m join public.competitions k on k.id = m.competition_id where m.id = p_match;
  if v_event is null or not exists (select 1 from public.discord_feeds f where f.event_id = v_event and f.enabled) then return; end if;
  if not exists (select 1 from public.discord_posts p where p.match_id = p_match and p.kind = 'now' and p.state in ('pending', 'sending', 'retry', 'sent')) then return; end if;
  insert into public.discord_live_edits (match_id, event_id, dirty_at, done) values (p_match, v_event, clock_timestamp(), false)
  on conflict (match_id) do update set dirty_at = clock_timestamp(), done = false;
  update public.discord_live_edits set kicked_at = clock_timestamp()
  where match_id = p_match and (kicked_at is null or kicked_at < clock_timestamp() - interval '5 seconds') returning true into v_kick;
  if coalesce(v_kick, false) then perform private.discord_kick(); end if;
end $function$
;$bos$, $bos$drop function if exists private.discord_live_touch(p_match uuid);$bos$);
