 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.matches; v_event uuid; f record; v_fights integer; v_wins integer; v_streak integer;
begin
  select * into m from public.matches where id = p_match;
  select k.event_id into v_event from public.competitions k where k.id = m.competition_id;
  if v_event is null or private.is_synthetic('event', v_event) then return; end if;
  for f in select en.id as entry_id, en.fighter_id, fi.display_name from public.entries en join public.fighters fi on fi.id = en.fighter_id
           where en.id in (m.entry_a, m.entry_b) and en.fighter_id is not null and not private.is_synthetic('fighter', en.fighter_id) loop
    select count(*), count(*) filter (where mm.winner_entry_id = e2.id) into v_fights, v_wins
    from public.entries e2 join public.matches mm on (mm.entry_a = e2.id or mm.entry_b = e2.id) and mm.queue_state = 'final' and mm.result is not null
    join public.competitions k2 on k2.id = mm.competition_id
    where e2.fighter_id = f.fighter_id and not private.is_synthetic('event', k2.event_id);
    if v_wins = 1 and m.winner_entry_id = f.entry_id then
      perform private.discord_enqueue(v_event, 'milestone', p_match, 'milestone:' || f.fighter_id || ':firstwin',
        private.discord_event_base(v_event) || jsonb_build_object('fighter', f.display_name, 'fighter_id', f.fighter_id, 'what', 'first win', 'n', 1));
    end if;
    if v_fights in (10, 25, 50, 100, 150, 200) then
      perform private.discord_enqueue(v_event, 'milestone', p_match, 'milestone:' || f.fighter_id || ':fights:' || v_fights,
        private.discord_event_base(v_event) || jsonb_build_object('fighter', f.display_name, 'fighter_id', f.fighter_id, 'what', v_fights || ' fights', 'n', v_fights));
    end if;
    if m.winner_entry_id = f.entry_id then
      with h as (
        select (mm.winner_entry_id = e2.id) as won, row_number() over (order by coalesce(mm.finalized_at, mm.created_at) desc, mm.id desc) as rn
        from public.entries e2 join public.matches mm on (mm.entry_a = e2.id or mm.entry_b = e2.id) and mm.queue_state = 'final' and mm.result is not null
        join public.competitions k2 on k2.id = mm.competition_id
        where e2.fighter_id = f.fighter_id and not private.is_synthetic('event', k2.event_id))
      select coalesce(min(rn) filter (where not won) - 1, count(*)) into v_streak from h;
      if v_streak in (3, 5, 10) then
        perform private.discord_enqueue(v_event, 'milestone', p_match, 'milestone:' || f.fighter_id || ':streak:' || v_streak || ':' || p_match,
          private.discord_event_base(v_event) || jsonb_build_object('fighter', f.display_name, 'fighter_id', f.fighter_id, 'what', 'streak', 'n', v_streak));
      end if;
    end if;
  end loop;
end $function$
;$bos$, $bos$drop function if exists private.discord_milestones(p_match uuid);$bos$);
