 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cur public.matches; v_event uuid; v_tz text; v_delay integer; v_moved boolean; v_payload jsonb;
begin
  begin
    select * into v_cur from public.matches where id = new.id;
    if not found or v_cur.entry_a is null or v_cur.entry_b is null or v_cur.queue_state = 'final' then return null; end if;
    select k.event_id, coalesce(e.timezone, 'America/Edmonton') into v_event, v_tz from public.competitions k join public.events e on e.id = k.event_id where k.id = new.competition_id;
    if v_event is null or not exists (select 1 from public.discord_feeds f where f.event_id = v_event and f.enabled) then return null; end if;
    v_moved := private.field_key(old.field) is distinct from private.field_key(v_cur.field) and v_cur.queue_state in ('on_deck', 'in_the_hole', 'active');
    v_delay := case when old.scheduled_at is not null and v_cur.scheduled_at is not null
                    then floor(extract(epoch from (v_cur.scheduled_at - old.scheduled_at)) / 60)::integer end;
    if v_delay is not null and (v_delay < 15 or not (v_cur.queue_state in ('on_deck', 'in_the_hole')
         or (v_cur.queue_state = 'scheduled' and v_cur.scheduled_at < now() + interval '3 hours'))) then v_delay := null; end if;
    if not v_moved and v_delay is null then return null; end if;
    v_payload := private.discord_match_payload(new.id) || jsonb_build_object(
      'from_field', case when v_moved then coalesce(nullif(btrim(old.field), ''), 'Field 1') end,
      'delay_minutes', v_delay,
      'new_time', case when v_delay is not null then to_char(v_cur.scheduled_at at time zone v_tz, 'FMHH12:MI AM') end,
      'mention_ids', private.discord_mentions_for(new.id), 'role_names', private.discord_team_roles_for(new.id));
    perform private.discord_enqueue(v_event, 'moved', new.id,
      'moved:' || new.id::text || ':' || coalesce(private.field_key(v_cur.field), '') || ':' || coalesce(extract(epoch from v_cur.scheduled_at)::bigint::text, ''), v_payload);
  exception when others then
    raise warning 'discord moved post failed for match %: %', new.id, sqlerrm;
  end;
  return null;
end $function$
;$bos$, $bos$drop function if exists private.discord_moved_post();$bos$);
