    if not found or v_cur.status <> 'finished' then return null; end if;
    if not exists (select 1 from public.discord_feeds f where f.event_id = v_cur.event_id and f.enabled) then return null; end if;
    select coalesce(jsonb_agg(jsonb_build_object('place', x ->> 'place', 'name', x ->> 'name') order by (x ->> 'place')::integer, x ->> 'name'), '[]'::jsonb)
