    if jsonb_array_length(v_top) = 0 then return null; end if;
    perform private.discord_enqueue(v_cur.event_id, 'podium', null,
      'podium:' || new.id::text || ':' || coalesce(extract(epoch from v_cur.finalized_at)::bigint::text, extract(epoch from clock_timestamp())::bigint::text),
      private.discord_event_base(v_cur.event_id) || jsonb_build_object('competition_name', v_cur.name, 'competition_id', new.id, 'podium', v_top,
        'again', exists (select 1 from public.discord_posts p where p.kind = 'podium' and p.dedupe_key like 'podium:' || new.id::text || ':%')));
  exception when others then
    raise warning 'discord podium post failed for competition %: %', new.id, sqlerrm;
  end;
  return null;
end $function$
