 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cur public.matches; v_event uuid; v_kind text; v_payload jsonb; v_seq integer; v_comp public.competitions; v_h2h jsonb; v_feed public.discord_feeds;
begin
  begin
    select * into v_cur from public.matches where id = new.id;
    if not found or v_cur.queue_state is distinct from new.queue_state then return null; end if;
    select k.event_id into v_event from public.competitions k where k.id = new.competition_id;
    if v_event is null then return null; end if;
    select * into v_feed from public.discord_feeds f where f.event_id = v_event;
    if not found or not v_feed.enabled then return null; end if;

    if new.queue_state = 'final' and old.queue_state is distinct from 'final' then v_kind := 'result';
    elsif new.queue_state = 'active' and old.queue_state is distinct from 'active' and old.queue_state is distinct from 'final' then v_kind := 'now';
    elsif new.queue_state = 'on_deck' and old.queue_state in ('scheduled', 'in_the_hole') then v_kind := 'on_deck';
    elsif new.queue_state = 'in_the_hole' and old.queue_state = 'scheduled' then v_kind := 'hole';
    else return null; end if;
    if v_cur.entry_a is null or v_cur.entry_b is null then return null; end if;

    v_payload := private.discord_match_payload(new.id) || jsonb_build_object('competition_id', new.competition_id);
    if v_kind = 'result' then
      v_payload := v_payload || jsonb_build_object(
        'result', v_cur.result,
        'winner', case v_cur.result when 'a' then v_payload ->> 'side_a' when 'b' then v_payload ->> 'side_b' end,
        'score_a', v_cur.score_a, 'score_b', v_cur.score_b,
        'corrected', exists (select 1 from public.discord_posts p where p.match_id = new.id and p.kind = 'result'));
      perform private.discord_enqueue(v_event, 'result', new.id, 'result:' || new.id::text || ':' || v_cur.version, v_payload);
      if (v_payload ->> 'corrected')::boolean then
        perform private.discord_enqueue(v_event, 'correction', new.id, 'correction:' || new.id::text || ':' || v_cur.version,
          v_payload || jsonb_build_object('mention_ids', private.discord_mentions_for(new.id)));
      end if;
      perform private.discord_live_touch(new.id);
      select * into v_comp from public.competitions where id = new.competition_id;
      if nullif(btrim(v_cur.round_label), '') is not null and not exists (
           select 1 from public.matches x where x.competition_id = new.competition_id and x.round_label = v_cur.round_label and x.queue_state <> 'final') then
        perform private.discord_enqueue(v_event, 'round', null, 'round:' || new.competition_id::text || ':' || v_cur.round_label,
          private.discord_event_base(v_event) || jsonb_build_object('competition_name', v_comp.name, 'competition_id', new.competition_id, 'round_label', v_cur.round_label,
            'results', (select coalesce(jsonb_agg(jsonb_build_object('a', private.lyst_side_name(x.entry_a), 'b', private.lyst_side_name(x.entry_b),
                          'result', x.result, 'score_a', x.score_a, 'score_b', x.score_b) order by x.position), '[]'::jsonb)
                        from public.matches x where x.competition_id = new.competition_id and x.round_label = v_cur.round_label and x.entry_a is not null and x.entry_b is not null),
            'standings', private.discord_standings(new.competition_id)));
      end if;
      perform private.discord_milestones(new.id);
    else
      if exists (select 1 from public.discord_posts p where p.match_id = new.id and p.kind = v_kind and p.created_at > clock_timestamp() - interval '2 minutes') then
        return null; end if;
      v_payload := v_payload || jsonb_build_object('mention_ids', private.discord_mentions_for(new.id), 'role_names', private.discord_team_roles_for(new.id));
      if v_kind = 'now' then
        v_h2h := private.discord_h2h(new.id);
        if v_h2h is not null then v_payload := v_payload || jsonb_build_object('h2h', v_h2h); end if;
        if v_feed.going_live then
          perform private.discord_enqueue(v_event, 'going_live', null, 'going_live:' || v_event::text || ':' || current_date::text,
            private.discord_event_base(v_event) || jsonb_build_object('field', v_payload ->> 'field', 'side_a', v_payload ->> 'side_a', 'side_b', v_payload ->> 'side_b',
              'competition_name', v_payload ->> 'competition_name',
              'fields', (select count(distinct coalesce(nullif(btrim(x.field), ''), 'Field 1')) from public.matches x join public.competitions kk on kk.id = x.competition_id where kk.event_id = v_event and x.queue_state <> 'final'),
              'fights_today', (select count(*) from public.matches x join public.competitions kk on kk.id = x.competition_id where kk.event_id = v_event and x.queue_state <> 'final' and x.entry_a is not null and x.entry_b is not null)));
        end if;
      end if;
      select count(*) into v_seq from public.discord_posts p where p.match_id = new.id and p.kind = v_kind;
      perform private.discord_enqueue(v_event, v_kind, new.id, v_kind || ':' || new.id::text || ':' || v_seq, v_payload);
    end if;
  exception when others then
    raise warning 'discord post failed for match %: %', new.id, sqlerrm;
  end;
  return null;
end $function$
;$bos$, $bos$drop function if exists private.discord_queue_post();$bos$);
