    when 'now' then 'Now fighting on ' || coalesce(p ->> 'field', 'the field') || ': ' || coalesce(p ->> 'side_a', '?') || ' vs ' || coalesce(p ->> 'side_b', '?')
    when 'on_deck' then 'On deck on ' || coalesce(p ->> 'field', 'the field') || ': ' || coalesce(p ->> 'side_a', '?') || ' vs ' || coalesce(p ->> 'side_b', '?')
    when 'hole' then 'Two away on ' || coalesce(p ->> 'field', 'the field') || ': ' || coalesce(p ->> 'side_a', '?') || ' vs ' || coalesce(p ->> 'side_b', '?')
    when 'result' then case when p ->> 'result' = 'draw' then 'Draw: ' || coalesce(p ->> 'side_a', '?') || ' and ' || coalesce(p ->> 'side_b', '?')
                            else coalesce(p ->> 'winner', '?') || ' won' end
                       || coalesce(' ' || (p ->> 'score_a') || '-' || (p ->> 'score_b'), '') || case when (p ->> 'corrected')::boolean then ' (corrected)' else '' end
    when 'round' then 'Round done: ' || coalesce(p ->> 'competition_name', '') || ' ' || coalesce(p ->> 'round_label', '')
    when 'milestone' then 'Milestone: ' || coalesce(p ->> 'fighter', '?') || ' ' || coalesce(p ->> 'what', '')
    when 'moved' then 'Change: ' || coalesce(p ->> 'side_a', '?') || ' vs ' || coalesce(p ->> 'side_b', '?') || ' now on ' || coalesce(p ->> 'field', 'the field')
                      || coalesce(', ' || (p ->> 'delay_minutes') || ' min later', '')
    when 'podium' then 'Podium: ' || coalesce(p ->> 'competition_name', '')
    when 'correction' then 'Corrected result sent privately to the fighters'
    when 'announcement' then 'Announcement: ' || coalesce(p ->> 'message', '')
    when 'test' then 'Test message'
    when 'feed_on' then 'Feed turned on'
    when 'staff_alert' then 'Staff alert (' || coalesce(p ->> 'alert', '?') || ')' || coalesce(' on ' || nullif(p ->> 'field', ''), '') || coalesce(': ' || nullif(p ->> 'note', ''), '')
    when 'going_live' then 'Going live: first fight of the day'
    else p_kind end
