 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(array_agg(x.office order by array_position(array['president','vice_president','secretary','treasurer','director'], x.office)), '{}')
  from (
    select o.office
    from public.team_officers o
    where auth.uid() is not null
      and o.team_id = p_team
      and o.user_id = auth.uid()
      and o.ended_on is null
      and o.started_on <= current_date
    union
    select d.delegated_office as office
    from public.team_officer_delegations d
    where auth.uid() is not null
      and d.team_id = p_team
      and d.user_id = auth.uid()
      and d.ended_on is null
      and d.started_on <= current_date
  ) x
$function$
;$bos$, $bos$drop function if exists private.my_team_offices(p_team uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'new_payment_ref' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.new_payment_ref(p_event uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c constant text := 'ACDEFGHJKMNPQRTUVWXY3479'; v text;
begin
  for i in 1 .. 100 loop
    v := '';
    for j in 1 .. 6 loop v := v || substr(c, 1 + floor(random() * length(c))::int, 1); end loop;
    if not exists (select 1 from public.registrations r where r.event_id = p_event and r.payment_ref = v) then return v; end if;
  end loop;
  raise exception 'could not make a payment reference; try again' using errcode = 'P0001';
end $function$
;$bos$, $bos$drop function if exists private.new_payment_ref(p_event uuid);$bos$);
