select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'open_privacy_request' and pg_get_function_identity_arguments(p.oid) = $bos$p_user uuid, p_type text, p_details text, p_contact text, p_source text, p_bug uuid, p_session uuid, p_at timestamp with time zone$bos$), $bos$CREATE OR REPLACE FUNCTION private.open_privacy_request(p_user uuid, p_type text, p_details text, p_contact text, p_source text, p_bug uuid, p_session uuid, p_at timestamp with time zone)
 RETURNS privacy_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.privacy_requests;
begin
  insert into public.privacy_requests (received_at, user_id, request_type, details, contact, due_at, source, bug_report_id, session_id)
  values (p_at, p_user, p_type, p_details, p_contact, p_at + interval '30 days', p_source, p_bug, p_session)
  returning * into r;
  insert into public.privacy_request_events (request_id, at, actor, from_status, to_status, note)
  values (r.id, p_at, p_user, null, 'received', case when p_source = 'bug_report' then 'Sent with the bug button' end);
  perform private.audit(null, 'privacy.request_received', r.id::text, jsonb_build_object('type', p_type, 'source', p_source));
  insert into public.notifications (user_id, kind, payload)
  select pr.user_id, 'privacy_request', jsonb_build_object('request_id', r.id, 'request_type', p_type, 'stage', 'new', 'due_on', to_char(r.due_at at time zone 'America/Edmonton', 'Mon DD'))
  from public.platform_roles pr where pr.role = 'owner';
  return r;
end $function$
;$bos$, $bos$drop function if exists private.open_privacy_request(p_user uuid, p_type text, p_details text, p_contact text, p_source text, p_bug uuid, p_session uuid, p_at timestamp with time zone);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'operator_log_guard' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.operator_log_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'the operator log is append-only' using errcode = '42501'; end if;
  if (new.id, new.session_id, new.event_id, new.operator_name, new.field_key, new.side, new.started_at, new.match_id) is distinct from (old.id, old.session_id, old.event_id, old.operator_name, old.field_key, old.side, old.started_at, old.match_id)
     or (old.ended_at is not null and new.ended_at is distinct from old.ended_at) then
    raise exception 'the operator log is append-only' using errcode = '42501'; end if;
  return new;
end $function$
;$bos$, $bos$drop function if exists private.operator_log_guard();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'owner_mfa_ok' and pg_get_function_identity_arguments(p.oid) = $bos$p_user uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.owner_mfa_ok(p_user uuid)
