select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'readiness_rows' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid, p_detail boolean$bos$), $bos$CREATE OR REPLACE FUNCTION private.readiness_rows(p_event uuid, p_detail boolean)
 RETURNS TABLE(registration_id uuid, fighter_id uuid, full_name text, team_id uuid, team_name text, competitions text[], is_volunteer boolean, status text, attendance text, inspection text, issues text[], inspection_note text, inspected_at timestamp with time zone, inspected_by_name text, reinspected boolean, insurance_ok boolean, fee_ok boolean, override_active boolean, override_reason text, profight boolean, declared_weight text, weight_kg numeric, ready boolean, reasons text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with r as (
    select g.*, t.name as tname,
      coalesce((select bool_or(c.passed) from public.registration_checks c where c.registration_id = g.id and c.check_name = 'arrived'), false) as arrived,
      coalesce((select bool_or(c.passed) from public.registration_checks c where c.registration_id = g.id and c.check_name = 'checked_in'), false) as checked_in,
      coalesce((select bool_or(c.passed) from public.registration_checks c where c.registration_id = g.id and c.check_name = 'kit'), false) as kit
    from public.registrations g left join public.teams t on t.id = g.team_id
    where g.event_id = p_event and g.status in ('accepted', 'pending', 'withdrawn')),
  x as (
    select r.*, li.result as last_result, li.issues as last_issues, li.note as last_note, li.inspected_at as last_at, li.inspected_by as last_by,
      exists (select 1 from public.registration_inspections q where q.registration_id = r.id and q.result in ('conditional', 'failed')) as had_problem,
      o.reason as o_reason,
      (select array_agg(k.name order by k.sort, k.name) from public.registration_competitions rc join public.competitions k on k.id = rc.competition_id where rc.registration_id = r.id) as comps,
      exists (select 1 from public.registration_competitions rc join public.competitions k on k.id = rc.competition_id join public.ref_categories c on c.code = k.category
              where rc.registration_id = r.id and c.league = 'outrance') as is_pro,
      (select rc.details ->> 'weight' from public.registration_competitions rc where rc.registration_id = r.id and rc.details ? 'weight' limit 1) as declared,
      (select w.weight_kg from public.registration_weighins w where w.registration_id = r.id order by w.recorded_at desc limit 1) as measured
    from r
    left join lateral (select q.* from public.registration_inspections q where q.registration_id = r.id order by q.inspected_at desc, q.id desc limit 1) li on true
    left join public.registration_overrides o on o.registration_id = r.id and o.revoked_at is null),
  y as (
    select x.*,
      case when x.status = 'withdrawn' then 'withdrawn' when x.checked_in then 'checked_in' when x.arrived then 'arrived' else 'expected' end as att,
      case when x.is_volunteer then 'not_needed'
           when x.last_result in ('passed', 'conditional', 'failed') then x.last_result
           when x.last_result is null and x.kit then 'passed'
           else 'not_inspected' end as insp,
      x.insurance in ('hacsa_member', 'mcc_member', 'proof_received') as ins_ok,
      not (x.fee_due_cents > 0 and not x.fee_paid) as f_ok
    from x),
  z as (
    select y.*, array_remove(array[
      case when y.status = 'withdrawn' then 'Withdrawn' when y.status <> 'accepted' then 'Registration not accepted' end,
      case when y.status = 'accepted' and y.att = 'expected' then 'Not checked in' when y.status = 'accepted' and y.att = 'arrived' then 'Arrived, not checked in' end,
      case when y.status = 'accepted' then case y.insp when 'not_inspected' then 'Armour inspection required' when 'conditional' then 'Armour needs correction' when 'failed' then 'Armour failed inspection' end end,
      case when y.status = 'accepted' and not y.ins_ok then 'Insurance not in order' end,
      case when y.status = 'accepted' and not y.f_ok then 'Fee not paid' end,
      case when y.status = 'accepted' and not y.is_volunteer then private.discipline_block_reason(y.fighter_id, y.event_id, y.team_id) end
    ], null) as why,
    case when y.status = 'accepted' and not y.is_volunteer then private.discipline_block_reason(y.fighter_id, y.event_id, y.team_id) end as blocked_why
    from y)
  select z.id, z.fighter_id, z.full_name, z.team_id, z.tname, coalesce(z.comps, '{}'), z.is_volunteer, z.status,
    z.att, z.insp, coalesce(case when z.insp in ('conditional', 'failed') then z.last_issues end, '{}'),
    case when p_detail then z.last_note end, z.last_at, case when p_detail and z.last_by is not null then coalesce(private.person_name(z.last_by), 'A staff member') end,
    z.had_problem and z.insp = 'passed',
    z.ins_ok, z.f_ok, z.o_reason is not null, case when p_detail then z.o_reason end, z.is_pro,
    case when p_detail then z.declared end, case when p_detail then z.measured end,
    z.status = 'accepted' and (cardinality(z.why) = 0 or (z.o_reason is not null and z.blocked_why is null)),
    z.why
  from z
  order by lower(z.full_name), z.id
$function$
;$bos$, $bos$drop function if exists private.readiness_rows(p_event uuid, p_detail boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'reavers_discord_board_payload' and pg_get_function_identity_arguments(p.oid) = $bos$p_meeting uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.reavers_discord_board_payload(p_meeting uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  body_text text := '';
  section_text text;
  rec record;
  s text;
  labels text[] := array['submitted','on_agenda','addressed','withdrawn'];
  headings text[] := array['🟡 Submitted','🔵 On Agenda','🟢 Addressed','⚪ Withdrawn'];
  i int;
begin
  for i in 1..array_length(labels,1) loop
    section_text := '';
    for rec in
      select t.subject, cm.full_name
      from public.club_meeting_topics t
      left join public.club_memberships cm on cm.id=t.membership_id
      where t.meeting_id=p_meeting and t.status=labels[i]
      order by t.created_at
    loop
      section_text := section_text || E'\n• **' || coalesce(rec.subject,'Untitled') || '**' ||
        E'\n  Submitted by: ' || coalesce(rec.full_name,'Member');
    end loop;

    if section_text <> '' then
      body_text := body_text || case when body_text='' then '' else E'\n\n' end ||
        headings[i] || section_text;
    end if;
  end loop;

  if body_text='' then body_text := 'No AGM topics have been submitted yet.'; end if;

  return jsonb_build_object(
    'username','Red Deer Reavers AGM Topics Bot',
    'content','📋 **2026 AGM Topics & Concerns**',
    'embeds',jsonb_build_array(
      jsonb_build_object(
        'description',left(body_text,4000),
        'footer',jsonb_build_object('text','Automatically updated from the Red Deer Reavers AGM system'),
        'url','https://reddeerreavers.com/members.html?view=agm-admin'
      )
    )
  );
end
$function$
;$bos$, $bos$drop function if exists private.reavers_discord_board_payload(p_meeting uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'reavers_discord_http' and pg_get_function_identity_arguments(p.oid) = $bos$p_method text, p_url text, p_body jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION private.reavers_discord_http(p_method text, p_url text, p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r extensions.http_response;
begin
  select *
  into r
  from extensions.http((
    upper(p_method),
    p_url,
    array[extensions.http_header('Content-Type','application/json')],
    'application/json',
    p_body::text
  )::extensions.http_request);

  if r.status < 200 or r.status >= 300 then
    raise exception 'Discord HTTP %: %', r.status, left(coalesce(r.content,''),500);
  end if;

  if coalesce(r.content,'') = '' then
    return '{}'::jsonb;
  end if;
  return r.content::jsonb;
end
$function$
;$bos$, $bos$drop function if exists private.reavers_discord_http(p_method text, p_url text, p_body jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'reavers_discord_membership_alert' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.reavers_discord_membership_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_webhook text;
  v_name text := left(coalesce(nullif(new.payload ->> 'person_name', ''), 'New member'), 120);
  v_team text := left(coalesce(nullif(new.payload ->> 'team_name', ''), 'Red Deer Reavers'), 120);
  v_body jsonb;
begin
  if new.kind <> 'club_membership_submitted' then
    return new;
  end if;

  select decrypted_secret
    into v_webhook
  from vault.decrypted_secrets
  where name = 'reavers_discord_membership_webhook'
  order by created_at desc
  limit 1;

  if v_webhook is null or btrim(v_webhook) = '' then
    return new;
  end if;

  v_body := jsonb_build_object(
    'username', 'Red Deer Reavers',
    'content', '🔔 **New Reavers Member Waiting for Approval**',
    'embeds', jsonb_build_array(
      jsonb_build_object(
        'title', v_name,
        'description', 'A new membership application is waiting for approval.',
        'fields', jsonb_build_array(
          jsonb_build_object('name', 'Team', 'value', v_team, 'inline', true),
          jsonb_build_object('name', 'Status', 'value', 'Pending approval', 'inline', true)
        ),
        'url', 'https://reddeerreavers.com/members.html?view=members'
      )
    )
  );

  perform net.http_post(
    url := v_webhook,
    headers := '{"Content-Type":"application/json"}'::jsonb,
    body := v_body
  );

  return new;
exception
  when others then
    raise warning 'Reavers Discord membership alert failed: %', sqlerrm;
    return new;
end
$function$
;$bos$, $bos$drop function if exists private.reavers_discord_membership_alert();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'reavers_discord_nomination_alert' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.reavers_discord_nomination_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_webhook text;
  v_nom public.club_meeting_nominations;
  v_meeting public.club_meetings;
  v_team public.teams;
  v_nominee text;
  v_nominator text;
  v_body jsonb;
begin
  select * into v_nom
  from public.club_meeting_nominations
  where id = new.nomination_id;

  if not found then return new; end if;

  select * into v_meeting
  from public.club_meetings
  where id = v_nom.meeting_id;

  if not found then return new; end if;

  select * into v_team
  from public.teams
  where id = v_meeting.team_id;

  if not found or v_team.slug <> 'red-deer-reavers' then return new; end if;

  select full_name into v_nominee
  from public.club_memberships
  where id = v_nom.nominee_membership_id;

  select full_name into v_nominator
  from public.club_memberships
  where id = new.nominator_membership_id;

  select decrypted_secret into v_webhook
  from vault.decrypted_secrets
  where name = 'reavers_discord_nominations_webhook'
  order by created_at desc
  limit 1;

  if v_webhook is null or btrim(v_webhook) = '' then return new; end if;

  v_body := jsonb_build_object(
    'username', 'Red Deer Reavers Nominations Bot',
    'content', '🗳️ **New Executive Nomination**',
    'embeds', jsonb_build_array(
      jsonb_build_object(
        'title', coalesce(v_nominee, 'Member'),
        'fields', jsonb_build_array(
          jsonb_build_object('name', 'Office', 'value', initcap(replace(v_nom.office, '_', ' ')), 'inline', true),
          jsonb_build_object('name', 'Nominated by', 'value', coalesce(v_nominator, 'Member'), 'inline', true),
          jsonb_build_object('name', 'Status', 'value', replace(initcap(v_nom.status), '_', ' '), 'inline', true)
        ),
        'url', 'https://reddeerreavers.com/members.html?view=agm-admin'
      )
    )
  );

  perform net.http_post(
    url := v_webhook,
    headers := '{"Content-Type":"application/json"}'::jsonb,
    body := v_body
  );

  return new;
exception when others then
  raise warning 'Reavers Discord nomination alert failed: %', sqlerrm;
  return new;
end
$function$
;$bos$, $bos$drop function if exists private.reavers_discord_nomination_alert();$bos$);
