select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'reavers_discord_sync_board' and pg_get_function_identity_arguments(p.oid) = $bos$p_meeting uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.reavers_discord_sync_board(p_meeting uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  webhook text;
  mid text;
  result jsonb;
  payload jsonb;
begin
  webhook := private.reavers_discord_webhook();
  if webhook is null or btrim(webhook)='' then return; end if;

  payload := private.reavers_discord_board_payload(p_meeting);
  select message_id into mid from private.reavers_discord_topic_boards where meeting_id=p_meeting;

  if mid is null then
    result := private.reavers_discord_http('POST', webhook || case when position('?' in webhook)>0 then '&wait=true' else '?wait=true' end, payload);
    mid := result->>'id';
    if mid is not null then
      insert into private.reavers_discord_topic_boards(meeting_id,message_id,synced_at)
      values(p_meeting,mid,now())
      on conflict(meeting_id) do update set message_id=excluded.message_id,synced_at=excluded.synced_at;
    end if;
  else
    perform private.reavers_discord_http('PATCH', webhook || '/messages/' || mid, payload);
    update private.reavers_discord_topic_boards set synced_at=now() where meeting_id=p_meeting;
  end if;
end
