 SET search_path TO ''
AS $function$
declare
  v_team_slug text;
  v_url text;
  v_secret text;
begin
  if tg_op <> 'UPDATE'
     or old.status is not distinct from 'active'
     or new.status is distinct from 'active'
     or new.user_id is null then
    return new;
  end if;

  select slug into v_team_slug
  from public.teams
  where id = new.team_id;

  if v_team_slug <> 'red-deer-reavers' then
    return new;
  end if;

  select value into v_url from private.push_config where key = 'function_url';
  select value into v_secret from private.push_config where key = 'dispatch_secret';

  if v_url is null or v_secret is null then
    return new;
  end if;

  perform net.http_post(
    url := v_url,
    body := jsonb_build_object(
      'mode', 'reavers-direct',
      'user_id', new.user_id,
      'title', 'Red Deer Reavers Membership Approved',
      'body', 'Your membership has been approved. Welcome to the Red Deer Reavers!',
      'route', 'https://reddeerreavers.com/members.html?view=mine',
      'tag', 'reavers-membership-approved'
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-dispatch-secret', v_secret
    )
  );

  return new;
exception when others then
  raise warning 'Reavers approval push failed: %', sqlerrm;
  return new;
end
$function$
;$bos$, $bos$drop function if exists private.reavers_membership_approval_push();$bos$);
