 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_webhook text;
  v_message_id text;
  v_dispatch_secret text;
  v_names text;
  v_count integer;
  v_content text;
begin
  select decrypted_secret into v_webhook
  from vault.decrypted_secrets
  where name = 'reavers_discord_public_rsvp_webhook'
  order by created_at desc
  limit 1;

  select decrypted_secret into v_message_id
  from vault.decrypted_secrets
  where name = 'reavers_discord_public_rsvp_message_id'
  order by created_at desc
  limit 1;

  select value into v_dispatch_secret
  from private.push_config
  where key = 'dispatch_secret';

  if v_webhook is null or v_message_id is null or v_dispatch_secret is null then
    return;
  end if;

  with mt as (
    select cm.id, cm.team_id, cm.membership_year
    from public.club_meetings cm
    join public.teams t on t.id = cm.team_id
    where t.slug = 'red-deer-reavers'
    order by cm.starts_at desc
    limit 1
  ),
  eligible_rows as (
    select m.full_name
    from mt
    join public.club_memberships m
      on m.team_id = mt.team_id
     and m.membership_year = mt.membership_year
    cross join lateral private.club_vote_check(m.id, private.club_meeting_day(mt.id)) c
    where m.status = 'active'
      and c.eligible
    order by lower(m.full_name), m.id
  )
  select
    coalesce(string_agg('• ' || full_name, E'
'), '• None currently'),
    count(*)
  into v_names, v_count
  from eligible_rows;

  v_content :=
    '@everyone' || E'

' ||
    '🗳️ **Red Deer Reavers 2026 AGM — Approved Voting Members**' || E'

' ||
    v_names || E'

' ||
    '**Total approved to vote: ' || v_count || '**' || E'

' ||
    '_This list updates automatically when voting eligibility changes._';

  perform net.http_post(
    url := 'https://mvbxlebznlgroptwwdsm.supabase.co/functions/v1/reavers-discord-edit',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-dispatch-secret', v_dispatch_secret
    ),
    body := jsonb_build_object(
      'url', v_webhook || '/messages/' || v_message_id,
      'content', v_content
    )
  );
exception when others then
  raise warning 'Reavers public voting board update failed: %', sqlerrm;
end
$function$
;$bos$, $bos$drop function if exists private.reavers_public_voting_board_update();$bos$);
