begin
  if p_table not in ('ranking_fighter_rows', 'ranking_team_rows', 'team_discipline_contribution_rows', 'ranking_team_discipline_rows') then
    raise exception 'not a precomputed record table: %', p_table using errcode = '22023';
  end if;
  execute format('delete from private.%I t where not exists (select 1 from pg_temp.%I n where (n.*)::text = (t.*)::text)', p_table, 'records_new_' || p_table);
  execute format('insert into private.%I select n.* from pg_temp.%I n where not exists (select 1 from private.%I t where (t.*)::text = (n.*)::text)', p_table, 'records_new_' || p_table, p_table);
  execute format('drop table pg_temp.%I', 'records_new_' || p_table);
end $function$
