 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(hashtext('bos.records_refresh'));
  if to_regclass('pg_temp.records_placings') is not null then drop table pg_temp.records_placings; end if;
  if to_regclass('pg_temp.records_fighter_placings') is not null then drop table pg_temp.records_fighter_placings; end if;
  create temporary table records_placings on commit drop as
  with ev as materialized (
    select e.id as event_id, coalesce(e.organization_id, s.organization_id) as organization_id, e.season_id,
      private.is_synthetic('event', e.id) as synthetic, e.stats_excluded_at is not null as stats_excluded
    from public.events e left join public.seasons s on s.id = e.season_id
    where exists (select 1 from public.competitions k join public.results r on r.competition_id = k.id where k.event_id = e.id and r.final_place is not null)
      and private.is_event_public(e.id)
  ), org as materialized (
    select o.id, private.is_synthetic('organization', o.id) as synthetic from public.organizations o
  )
  select r.entry_id, r.competition_id, ev.event_id, k.category, k.gender, k.weight_class, r.final_place, coalesce(r.points, 0) as points,
    ev.organization_id, ev.season_id, ev.synthetic, ev.stats_excluded, coalesce(org.synthetic, false) as org_synthetic,
    en.team_id, en.fighter_id as entry_fighter_id, en.represented_team_id
  from public.results r
  join public.competitions k on k.id = r.competition_id
  join ev on ev.event_id = k.event_id
  join public.entries en on en.id = r.entry_id
  left join org on org.id = ev.organization_id
  where r.final_place is not null;

  create temporary table records_fighter_placings on commit drop as
  select p.fighter_id, x.*
  from pg_temp.records_placings x
  join (select e.id as entry_id, e.fighter_id from public.entries e where e.fighter_id is not null and e.status <> 'withdrawn'
        union all
        select ef.entry_id, ef.fighter_id from public.entry_fighters ef join public.entries e on e.id = ef.entry_id where e.status <> 'withdrawn') p
    on p.entry_id = x.entry_id;

  if to_regclass('pg_temp.records_new_ranking_fighter_rows') is not null then drop table pg_temp.records_new_ranking_fighter_rows; end if;
  create temporary table records_new_ranking_fighter_rows (like private.ranking_fighter_rows) on commit drop;
  insert into pg_temp.records_new_ranking_fighter_rows (scope, organization_id, season_id, category, gender, weight_class, fighter_id, competitions, golds, silvers, bronzes, points, rank)
  with org_rows as (select * from pg_temp.records_fighter_placings where not stats_excluded and (not synthetic or org_synthetic)),
  agg as (
    select 'season'::text as scope, organization_id, season_id, category, gender, weight_class, fighter_id, count(*) as c,
      count(*) filter (where final_place = 1) as g, count(*) filter (where final_place = 2) as s, count(*) filter (where final_place = 3) as b, coalesce(sum(points), 0) as p
    from org_rows where season_id is not null group by organization_id, season_id, category, gender, weight_class, fighter_id
    union all
    select 'org_career', organization_id, null::uuid, category, gender, weight_class, fighter_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from org_rows where organization_id is not null group by organization_id, category, gender, weight_class, fighter_id
    union all
    select 'org_all', organization_id, null::uuid, null::text, null::text, null::text, fighter_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from org_rows where organization_id is not null group by organization_id, fighter_id
    union all
    select 'career', null::uuid, null::uuid, null::text, null::text, null::text, fighter_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from pg_temp.records_fighter_placings where not synthetic and not stats_excluded group by fighter_id
  )
  select scope, organization_id, season_id, category, gender, weight_class, fighter_id, c, g, s, b, p,
    rank() over (partition by scope, organization_id, season_id, category, gender, weight_class order by p desc)
  from agg;

  perform private.records_apply('ranking_fighter_rows');

  if to_regclass('pg_temp.records_new_ranking_team_rows') is not null then drop table pg_temp.records_new_ranking_team_rows; end if;
  create temporary table records_new_ranking_team_rows (like private.ranking_team_rows) on commit drop;
  insert into pg_temp.records_new_ranking_team_rows (scope, organization_id, season_id, category, gender, team_id, competitions, golds, silvers, bronzes, points, rank)
  with tr as (select x.* from pg_temp.records_placings x join public.teams t on t.id = x.team_id and t.status = 'approved'),
  org_rows as (select * from tr where not stats_excluded and (not synthetic or org_synthetic)),
  agg as (
    select 'season'::text as scope, organization_id, season_id, category, gender, team_id, count(*) as c,
      count(*) filter (where final_place = 1) as g, count(*) filter (where final_place = 2) as s, count(*) filter (where final_place = 3) as b, coalesce(sum(points), 0) as p
    from org_rows where season_id is not null group by organization_id, season_id, category, gender, team_id
    union all
    select 'org_career', organization_id, null::uuid, category, gender, team_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from org_rows where organization_id is not null group by organization_id, category, gender, team_id
    union all
    select 'org_all', organization_id, null::uuid, null::text, null::text, team_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from org_rows where organization_id is not null group by organization_id, team_id
    union all
    select 'career', null::uuid, null::uuid, null::text, null::text, team_id, count(*), count(*) filter (where final_place = 1),
      count(*) filter (where final_place = 2), count(*) filter (where final_place = 3), coalesce(sum(points), 0)
    from tr where not synthetic and not stats_excluded group by team_id
  )
  select scope, organization_id, season_id, category, gender, team_id, c, g, s, b, p,
    rank() over (partition by scope, organization_id, season_id, category, gender order by p desc)
  from agg;

  perform private.records_apply('ranking_team_rows');

  if to_regclass('pg_temp.records_new_team_discipline_contribution_rows') is not null then drop table pg_temp.records_new_team_discipline_contribution_rows; end if;
  create temporary table records_new_team_discipline_contribution_rows (like private.team_discipline_contribution_rows) on commit drop;
  insert into pg_temp.records_new_team_discipline_contribution_rows (scope, organization_id, season_id, category, gender, team_id, fighter_id, results, points)
  with base as (
    select organization_id, season_id, category, gender, fighter_id, represented_team_id as team_id, points, synthetic, org_synthetic
    from pg_temp.records_fighter_placings where entry_fighter_id is not null and not stats_excluded
  ), scoped as (
    select 'season'::text as scope, organization_id, season_id, category, gender, team_id, fighter_id, points from base
    where season_id is not null and (not synthetic or org_synthetic)
    union all
    select 'org_career', organization_id, null::uuid, category, gender, team_id, fighter_id, points from base where organization_id is not null and (not synthetic or org_synthetic)
    union all
    select 'career', null::uuid, null::uuid, category, gender, team_id, fighter_id, points from base where not synthetic
  )
  select scope, organization_id, season_id, category, gender, team_id, fighter_id, count(*), coalesce(sum(points), 0)
  from scoped
  group by grouping sets ((scope, organization_id, season_id, category, gender, team_id, fighter_id), (scope, organization_id, season_id, category, team_id, fighter_id));

  perform private.records_apply('team_discipline_contribution_rows');

  if to_regclass('pg_temp.records_new_ranking_team_discipline_rows') is not null then drop table pg_temp.records_new_ranking_team_discipline_rows; end if;
  create temporary table records_new_ranking_team_discipline_rows (like private.ranking_team_discipline_rows) on commit drop;
  insert into pg_temp.records_new_ranking_team_discipline_rows (scope, organization_id, season_id, category, gender, team_id, fighters, results, points, rank)
  select c.scope, c.organization_id, c.season_id, c.category, c.gender, c.team_id, count(*), sum(c.results), sum(c.points),
    rank() over (partition by c.scope, c.organization_id, c.season_id, c.category, c.gender order by sum(c.points) desc)
  from private.team_discipline_contribution_rows c join public.teams t on t.id = c.team_id and t.status = 'approved'
  group by c.scope, c.organization_id, c.season_id, c.category, c.gender, c.team_id;

  perform private.records_apply('ranking_team_discipline_rows');

  drop table pg_temp.records_placings;
  drop table pg_temp.records_fighter_placings;
end $function$
;$bos$, $bos$drop function if exists private.records_refresh();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'records_refresh_at_commit' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.records_refresh_at_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (select 1 from private.records_refresh_queue where xid = new.xid) then
    perform private.records_refresh();
    delete from private.records_refresh_queue where xid = new.xid;
  end if;
  return null;
end $function$
;$bos$, $bos$drop function if exists private.records_refresh_at_commit();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'region_on_write' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.region_on_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
