begin
  new.region := private.normalize_region(new.region);
  return new;
end $function$
;$bos$, $bos$drop function if exists private.region_on_write();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'registration_payment_ref' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION private.registration_payment_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.payment_ref is null then new.payment_ref := private.new_payment_ref(new.event_id); end if;
  return new;
end $function$
;$bos$, $bos$drop function if exists private.registration_payment_ref();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'retention_note' and pg_get_function_identity_arguments(p.oid) = $bos$p_trigger text, p_rule text, p_subjects text[], p_detail jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION private.retention_note(p_trigger text, p_rule text, p_subjects text[], p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n int := coalesce(cardinality(p_subjects), 0);
begin
  if n > 0 then
    insert into public.retention_log (trigger, rule, purged, subjects, detail) values (p_trigger, p_rule, n, p_subjects, coalesce(p_detail, '{}'::jsonb));
  end if;
  return n;
end $function$
;$bos$, $bos$drop function if exists private.retention_note(p_trigger text, p_rule text, p_subjects text[], p_detail jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'run_retention' and pg_get_function_identity_arguments(p.oid) = $bos$p_trigger text$bos$), $bos$CREATE OR REPLACE FUNCTION private.run_retention(p_trigger text DEFAULT 'schedule'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ids text[]; v_out jsonb := '{}'::jsonb; n int; v_owner record;
begin
  if p_trigger not in ('schedule', 'migration', 'owner') then p_trigger := 'schedule'; end if;

  -- 1. emergency contacts: 30 days after the event ends
  with done as (
    update public.registration_private p set emergency_name = '', emergency_relationship = '', emergency_phone = '', emergency_purged_at = now()
    from public.registrations r join public.events e on e.id = r.event_id
    where p.registration_id = r.id and p.emergency_purged_at is null and e.ends_on + 30 < current_date
      and (p.emergency_name <> '' or p.emergency_relationship <> '' or p.emergency_phone <> '')
    returning p.registration_id)
  select array_agg(registration_id::text) into v_ids from done;
  v_out := v_out || jsonb_build_object('emergency_contacts', private.retention_note(p_trigger, 'emergency_contacts_30_days_after_event', v_ids));

  -- 2. medical notes: the existing rule (30 days after the event), logged here as a count
  n := private.purge_medical_notes();
  if n > 0 then insert into public.retention_log (trigger, rule, purged) values (p_trigger, 'medical_notes_30_days_after_event', n); end if;
  v_out := v_out || jsonb_build_object('medical_notes', n);

  -- 3. private team-request data: 12 months after the decision (approval)
  with decided as (
    select p.team_id, coalesce((select min(a.at) from public.audit_log a where a.action = 'team.approved' and a.subject = p.team_id::text), p.created_at) as decided_at
    from public.team_request_private p join public.teams t on t.id = p.team_id and t.status = 'approved'),
  done as (
    delete from public.team_request_private p using decided d where d.team_id = p.team_id and d.decided_at < now() - interval '12 months' returning p.team_id)
  select array_agg(team_id::text) into v_ids from done;
  v_out := v_out || jsonb_build_object('team_request_private', private.retention_note(p_trigger, 'team_request_private_12_months_after_decision', v_ids));

  -- 4. bug-report screenshots: 90 days (the file is queued for the owner's page to delete through the Storage API)
  with old as (
    select b.id, b.screenshot_path from public.bug_reports b where b.screenshot_path is not null and b.created_at < now() - interval '90 days'),
  queued as (
    insert into public.bug_screenshot_removals (path, report_id, reason) select o.screenshot_path, o.id, 'expired' from old o on conflict (path) do nothing),
  done as (
    update public.bug_reports b set screenshot_path = null, screenshot_purged_at = now() from old o where o.id = b.id returning b.id)
  select array_agg(id::text) into v_ids from done;
  v_out := v_out || jsonb_build_object('bug_screenshots', private.retention_note(p_trigger, 'bug_screenshots_90_days', v_ids));
  -- files an older app uploaded but never attached to a report
  with orphan as (
    insert into public.bug_screenshot_removals (path, reason)
    select o.name, 'never_attached' from storage.objects o
    where o.bucket_id = 'bug-screenshots' and o.created_at < now() - interval '1 day' and o.name ~ '^reports/[0-9a-f-]{36}\.(jpg|png)$'
      and not exists (select 1 from public.bug_reports b where b.screenshot_path = o.name)
      and not exists (select 1 from public.bug_screenshot_removals q where q.path = o.name)
    on conflict (path) do nothing returning path)
  select array_agg(path) into v_ids from orphan;
  v_out := v_out || jsonb_build_object('bug_screenshots_never_attached', private.retention_note(p_trigger, 'bug_screenshots_never_attached_1_day', v_ids));

  -- 5. bug-report text: 24 months (the whole report; a screenshot still linked is queued first)
  insert into public.bug_screenshot_removals (path, report_id, reason)
  select b.screenshot_path, b.id, 'report_purged' from public.bug_reports b where b.screenshot_path is not null and b.created_at < now() - interval '24 months'
  on conflict (path) do nothing;
  with done as (delete from public.bug_reports b where b.created_at < now() - interval '24 months' returning b.id)
  select array_agg(id::text) into v_ids from done;
  v_out := v_out || jsonb_build_object('bug_reports', private.retention_note(p_trigger, 'bug_reports_24_months', v_ids));

  -- 6. error diagnostics: 90 days; the per-minute counters: 2 days
  with done as (delete from public.client_errors e where e.at < now() - interval '90 days' returning e.id)
  select count(*)::int into n from done;
  if n > 0 then insert into public.retention_log (trigger, rule, purged) values (p_trigger, 'error_samples_90_days', n); end if;
  v_out := v_out || jsonb_build_object('error_samples', n);
  with done as (delete from public.client_error_groups g where g.last_seen < now() - interval '90 days' returning g.group_key)
  select array_agg(group_key) into v_ids from done;
  v_out := v_out || jsonb_build_object('error_groups', private.retention_note(p_trigger, 'error_groups_90_days', v_ids));
  delete from public.client_error_minutes m where m.minute < now() - interval '2 days';

  -- 7. closed privacy requests: 24 months after closing
  with done as (delete from public.privacy_requests q where q.closed_at < now() - interval '24 months' returning q.id)
  select array_agg(id::text) into v_ids from done;
  v_out := v_out || jsonb_build_object('privacy_requests', private.retention_note(p_trigger, 'privacy_requests_24_months_after_closing', v_ids));

  -- 8. this log: 24 months
  delete from public.retention_log l where l.ran_at < now() - interval '24 months';

  -- reminders (not purges): privacy requests due within 7 days or overdue, once a day each; screenshots waiting for deletion
  if p_trigger <> 'migration' then
    insert into public.notifications (user_id, kind, payload, dedupe_key)
    select pr.user_id, 'privacy_request',
           jsonb_build_object('request_id', q.id, 'request_type', q.request_type, 'stage', case when q.due_at < now() then 'overdue' else 'due_soon' end,
                              'due_on', to_char(q.due_at at time zone 'America/Edmonton', 'Mon DD')),
           'privacy-due-' || q.id::text || '-' || pr.user_id::text || '-' || to_char(now() at time zone 'America/Edmonton', 'YYYYMMDD')
    from public.privacy_requests q cross join public.platform_roles pr
    where pr.role = 'owner' and q.closed_at is null and q.due_at < now() + interval '7 days'
    on conflict (dedupe_key) where dedupe_key is not null do nothing;
    select count(*)::int into n from public.bug_screenshot_removals q where q.removed_at is null;
    if n > 0 then
      insert into public.notifications (user_id, kind, payload, dedupe_key)
      select pr.user_id, 'retention_due', jsonb_build_object('count', n), 'retention-due-' || pr.user_id::text || '-' || to_char(now() at time zone 'America/Edmonton', 'YYYYMMDD')
      from public.platform_roles pr where pr.role = 'owner'
      on conflict (dedupe_key) where dedupe_key is not null do nothing;
    end if;
  end if;
  insert into public.retention_log (trigger, rule, purged, detail) values (p_trigger, 'run', 0, v_out);
  return v_out;
end $function$
;$bos$, $bos$drop function if exists private.run_retention(p_trigger text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'scrub_diag' and pg_get_function_identity_arguments(p.oid) = $bos$p text, p_max integer$bos$), $bos$CREATE OR REPLACE FUNCTION private.scrub_diag(p text, p_max integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(left(btrim(
    regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(coalesce(p, ''),
      'https?://[^/\s)"'']+', '', 'g'),                                         -- the site part of any URL
      '(/[^\s?#)"'']*)[?#][^\s:)"'']*', '\1', 'g'),                              -- query string or fragment after a path
      'eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+(\.[A-Za-z0-9_-]*)?', '[token]', 'g'),  -- JWT-like
      '[^\s@"''<>()/]+@[^\s@"''<>()/:]+\.[A-Za-z]{2,}', '[email]', 'g'),       -- email address (not a Safari stack frame "fn@/assets/x.js")
      '[A-Za-z0-9_+=-]{32,}', '[token]', 'g'),                                  -- long opaque strings
      '\d{6,}', '[number]', 'g')), p_max), '')
$function$
;$bos$, $bos$drop function if exists private.scrub_diag(p text, p_max integer);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'scrub_route' and pg_get_function_identity_arguments(p.oid) = $bos$p text$bos$), $bos$CREATE OR REPLACE FUNCTION private.scrub_route(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(left(
    regexp_replace(regexp_replace(regexp_replace(split_part(split_part(coalesce(p, ''), '?', 1), '#', 1),
      '^(/lyst/(join|train))/[^/]+', '\1/:code'),
      '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', ':id', 'g'),
      '[A-Za-z0-9_-]{32,}', ':token', 'g'), 200), '')
$function$
;$bos$, $bos$drop function if exists private.scrub_route(p text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'set_fighter_private' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid, p_field text, p_value text$bos$), $bos$CREATE OR REPLACE FUNCTION private.set_fighter_private(p_fighter uuid, p_field text, p_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_field = 'birth_year' then
    insert into private.fighter_private as fp (fighter_id, birth_year) values (p_fighter, p_value::int)
    on conflict (fighter_id) do update set birth_year = excluded.birth_year, updated_at = now();
  elsif p_field = 'inactive_reason' then
    insert into private.fighter_private as fp (fighter_id, inactive_reason) values (p_fighter, p_value)
    on conflict (fighter_id) do update set inactive_reason = excluded.inactive_reason, updated_at = now();
  else
    raise exception 'unknown private fighter field %', p_field using errcode = '22023';
  end if;
end $function$
;$bos$, $bos$drop function if exists private.set_fighter_private(p_fighter uuid, p_field text, p_value text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname = 'team_fight_rows' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION private.team_fight_rows(p_team uuid)
 RETURNS SETOF team_fights_all
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  with b as materialized (select private.caller_bypasses_rls() as bypass),
  mine as not materialized (select e.id from public.entries e where e.team_id = p_team),
  sides as (
    select m.id as match_id, m.competition_id, m.stage, m.round_label, m.finalized_at, m.result, m.winner_entry_id, m.detail,
           m.entry_a as me, m.entry_b as opp, m.score_a as sf, m.score_b as sa
    from mine w join public.matches m on m.entry_a = w.id where m.queue_state = 'final' and m.entry_b is not null
    union all
    select m.id, m.competition_id, m.stage, m.round_label, m.finalized_at, m.result, m.winner_entry_id, m.detail, m.entry_b, m.entry_a, m.score_b, m.score_a
    from mine w join public.matches m on m.entry_b = w.id where m.queue_state = 'final' and m.entry_a is not null
  ), r as materialized (
    select e.team_id, s.match_id, s.competition_id, k.name as competition_name, k.category, coalesce(rc.name, k.category) as category_name, k.gender, k.tier, k.structure,
      s.stage, s.round_label, ev.id as event_id, ev.slug as event_slug, ev.name as event_name, ev.starts_on, ev.ends_on as event_ends_on, ev.season_id,
      coalesce(ev.organization_id, se.organization_id) as organization_id,
      e.id as entry_id, coalesce(e.team_name_at_event, t.name) as team_name_at_event,
      o.id as opponent_entry_id, o.team_id as opponent_team_id, coalesce(o.team_name_at_event, ot.name) as opponent_name, ot.slug as opponent_team_slug,
      case when s.result = 'draw' then 'draw' when s.winner_entry_id = e.id then 'win' else 'loss' end as outcome,
      s.sf as score_for, s.sa as score_against, coalesce((s.detail ->> 'walkover')::boolean, false) as walkover,
      s.finalized_at, x.final_place, coalesce(x.points, 0) as points
    from sides s cross join b
    join public.entries e on e.id = s.me and e.team_id is not null
    join public.entries o on o.id = s.opp
    join public.competitions k on k.id = s.competition_id
    join public.events ev on ev.id = k.event_id
    left join public.seasons se on se.id = ev.season_id
    left join public.ref_categories rc on rc.code = k.category
    left join public.teams t on t.id = e.team_id and (b.bypass or t.status = 'approved' or private.is_team_captain(t.id) or private.can_admin_team(t.id))
    left join public.teams ot on ot.id = o.team_id and (b.bypass or ot.status = 'approved' or private.is_team_captain(ot.id) or private.can_admin_team(ot.id))
    left join public.results x on x.competition_id = e.competition_id and x.entry_id = e.id and x.final_place is not null
  ), v as materialized (select * from private.record_events(array(select distinct r.event_id from r)))
  select r.team_id, r.match_id, r.competition_id, r.competition_name, r.category, r.category_name, r.gender, r.tier, r.structure, r.stage, r.round_label,
    r.event_id, r.event_slug, r.event_name, r.starts_on, r.event_ends_on, r.season_id, r.organization_id, r.entry_id, r.team_name_at_event,
    r.opponent_entry_id, r.opponent_team_id, r.opponent_name, r.opponent_team_slug, r.outcome, r.score_for, r.score_against, r.walkover, r.finalized_at,
    r.final_place, r.points, v.synthetic, v.stats_excluded
  from r join v on v.event_id = r.event_id;
end
