 RETURNS SETOF team_results_all
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  with b as materialized (select private.caller_bypasses_rls() as bypass),
  r as materialized (
    select x.competition_id, x.entry_id, x.final_place, coalesce(x.points, 0) as points, k.name as competition_name, k.category, k.gender, k.tier, k.structure,
      ev.id as event_id, ev.slug as event_slug, ev.name as event_name, ev.event_type, ev.starts_on, ev.ends_on as event_ends_on, ev.season_id,
      coalesce(ev.organization_id, se.organization_id) as organization_id, e.team_id, e.fighter_id as entry_fighter_id,
      coalesce(e.team_name_at_event, t.name) as team_name_at_event, t.name as team_current_name, t.slug as team_current_slug
    from public.entries e cross join b
    join public.results x on x.entry_id = e.id and x.final_place is not null
    join public.competitions k on k.id = x.competition_id
    join public.events ev on ev.id = k.event_id
    left join public.seasons se on se.id = ev.season_id
    left join public.teams t on t.id = e.team_id and (b.bypass or t.status = 'approved' or private.is_team_captain(t.id) or private.can_admin_team(t.id))
    where e.team_id = p_team
  ), v as materialized (select * from private.record_events(array(select distinct r.event_id from r)))
  select r.competition_id, r.entry_id, r.final_place, r.points, r.competition_name, r.category, r.gender, r.tier, r.structure, r.event_id, r.event_slug,
    r.event_name, r.event_type, r.starts_on, r.event_ends_on, r.season_id, r.organization_id, r.team_id, r.entry_fighter_id, v.synthetic,
    r.team_name_at_event, r.team_current_name, r.team_current_slug, v.stats_excluded
  from r join v on v.event_id = r.event_id;
end
$function$
