 RETURNS TABLE(group_key text, kind text, message text, source_file text, first_seen timestamp with time zone, last_seen timestamp with time zone, occurrences bigint, in_range bigint, status text, is_new boolean, came_back boolean, releases text[], routes text[], people bigint, devices bigint, browsers text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_from timestamptz := now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 90)));
begin
  if not private.is_owner() then raise exception 'only the platform owner can read errors' using errcode = '42501'; end if;
  return query
  select g.group_key, g.kind, g.message, g.source_file, g.first_seen, g.last_seen, g.occurrences,
    (select count(*) from public.client_errors e where e.group_key = g.group_key and e.at >= v_from),
    g.status, g.first_seen >= v_from, coalesce(g.reopened_at >= v_from, false),
    array(select x.release from (select e.release, max(e.at) as at from public.client_errors e where e.group_key = g.group_key and e.release is not null group by e.release order by max(e.at) desc limit 3) x),
    array(select x.route from (select e.route, count(*) as n from public.client_errors e where e.group_key = g.group_key and e.at >= v_from and e.route is not null group by e.route order by count(*) desc limit 3) x),
    (select count(*) from public.client_errors e where e.group_key = g.group_key and e.at >= v_from and e.device_mode = 'person'),
    (select count(*) from public.client_errors e where e.group_key = g.group_key and e.at >= v_from and e.device_mode = 'device'),
    array(select x.b from (select coalesce(e.browser, '?') || ' on ' || coalesce(e.os, '?') as b, count(*) as n from public.client_errors e where e.group_key = g.group_key and e.at >= v_from group by 1 order by count(*) desc limit 3) x)
  from public.client_error_groups g
  where g.last_seen >= v_from
  order by (g.status = 'open') desc, g.last_seen desc
  limit 200;
end $function$
;$bos$, $bos$drop function if exists public.admin_client_errors(p_days integer);$bos$);
