      'keep_until', (b.recorded_at + interval '24 months')::date,
      'history', coalesce((select jsonb_agg(jsonb_build_object('at', h.at, 'by', coalesce(private.person_name(h.actor), 'Owner'), 'change', h.change, 'note', h.note) order by h.at, h.id)
                           from public.privacy_breach_history h where h.breach_id = b.id), '[]'::jsonb))
      order by (b.status = 'open') desc, b.discovered_at desc)
    from public.privacy_breaches b), '[]'::jsonb);
end $function$
