 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.bug_reports;
begin
  if p_path is null or p_path not in ('reports/' || p_report::text || '.jpg', 'reports/' || p_report::text || '.png') then
    raise exception 'that screenshot does not belong to this report' using errcode = '22023'; end if;
  select * into r from public.bug_reports where id = p_report for update;
  if not found or r.created_at < now() - interval '30 minutes' then raise exception 'that report cannot take a screenshot any more' using errcode = '22023'; end if;
  if r.screenshot_path is not null then
    if r.screenshot_path = p_path then return; end if;   -- sent twice: already done
    raise exception 'that report already has a screenshot' using errcode = '22023';
  end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'bug-screenshots' and o.name = p_path) then
    raise exception 'the screenshot was not uploaded' using errcode = '22023'; end if;
  update public.bug_reports set screenshot_path = p_path, screenshot_attached_at = now() where id = p_report;
end $function$
;$bos$, $bos$drop function if exists public.attach_bug_screenshot(p_report uuid, p_path text);$bos$);
