 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_make_cards(p_team) then raise exception 'you cannot make cards for this team' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(x order by x ->> 'sort', x ->> 'display_name')
    from (
      select jsonb_build_object(
        'id', f.id, 'display_name', f.display_name,
        'sort', case when coalesce(m.role, '') = 'captain' then '0' else '1' end,
        'membership_role', m.role,
        'joined_year', f.joined_year, 'disciplines', f.disciplines, 'fighting_style', f.fighting_style, 'bio', f.bio,
        'highlights', coalesce((select jsonb_agg(h) from unnest(f.highlights) h
                                where h !~* '(record|rank|[0-9]+ *- *[0-9]+|\mwins?\M|\mloss(es)?\M|weigh|height)'), '[]'::jsonb),
        'avatar_path', f.avatar_path, 'city', f.city, 'region', f.region, 'country', f.country,
        'has_account', exists (select 1 from public.fighter_accounts fa where fa.fighter_id = f.id),
        'under_13', private.card_minor(f.id),
        'events', coalesce((
          select jsonb_agg(jsonb_build_object('id', e.id, 'name', e.name, 'slug', e.slug, 'year', extract(year from e.starts_on)::int) order by e.starts_on desc)
          from public.events e
          where not private.is_synthetic('event', e.id)
            and e.id in (select c.event_id from public.competitions c
                         where c.id in (select ef.competition_id from public.entry_fighters ef where ef.fighter_id = f.id)
                            or c.id in (select en.competition_id from public.entries en where en.fighter_id = f.id))), '[]'::jsonb),
        'cards', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'status', c.status, 'parallel', c.parallel, 'set_id', c.set_id))
                           from public.cards c where c.fighter_id = f.id and c.team_id = p_team and c.discarded_at is null), '[]'::jsonb)) as x
      from public.fighters f
      left join lateral (select tm.role from public.team_memberships tm
                         where tm.fighter_id = f.id and tm.team_id = p_team and (tm.to_date is null or tm.to_date >= current_date)
                         order by (tm.role = 'captain') desc limit 1) m on true
      where f.inactive_at is null
        and (f.team_id = p_team or m.role is not null)
    ) s), '[]'::jsonb);
end $function$
;$bos$, $bos$drop function if exists public.card_team_roster(p_team uuid);$bos$);
