 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare mt public.club_meetings;
begin
  select * into mt from public.club_meetings where id = p_meeting;
  if not found then raise exception 'meeting not found' using errcode = 'P0002'; end if;
  if auth.uid() is null or not private.is_club_secretary(mt.team_id) then
    raise exception 'only this club''s secretary can see nominations before the meeting' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'offices',
    (
      select jsonb_agg(
        jsonb_build_object(
          'office', o.office,
          'label', private.club_office_label(o.office),
          'current_officer', private.club_current_officer_name(mt.team_id, mt.membership_year, o.office),
          'nominations',
          coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'id', n.id,
                  'nominee', c.full_name,
                  'status', n.status,
                  'created_at', n.created_at,
                  'responded_at', n.responded_at,
                  'self_nominated', exists (
                    select 1
                    from public.club_meeting_nominators nr
                    where nr.nomination_id = n.id
                      and nr.nominator_membership_id = n.nominee_membership_id
                  ),
                  'nominated_by', (
                    select coalesce(jsonb_agg(g.full_name order by nr.nominated_at, g.full_name), '[]'::jsonb)
                    from public.club_meeting_nominators nr
                    join public.club_memberships g on g.id = nr.nominator_membership_id
                    where nr.nomination_id = n.id
                      and nr.nominator_membership_id <> n.nominee_membership_id
                  )
                )
                order by (n.status = 'accepted') desc,
                         (n.status = 'awaiting_acceptance') desc,
                         lower(c.full_name),
                         n.created_at
              )
              from public.club_meeting_nominations n
              join public.club_memberships c on c.id = n.nominee_membership_id
              where n.meeting_id = p_meeting
                and n.office = o.office
            ),
            '[]'::jsonb
          )
        )
        order by o.sort
      )
      from (values ('president', 1), ('secretary', 2), ('treasurer', 3)) as o(office, sort)
    )
  );
end
$function$
;$bos$, $bos$drop function if exists public.club_agm_nominations_admin(p_meeting uuid);$bos$);
