        'mine', (select r.going from public.club_event_rsvps r where r.team_id = p_team and r.event_id = e.id and r.membership_id = v_me.id),
        'my_note', (select r.note from public.club_event_rsvps r where r.team_id = p_team and r.event_id = e.id and r.membership_id = v_me.id)) order by e.starts_on, e.name)
      from (select * from public.events x where x.status = 'published' and x.ends_on >= current_date and x.archived_at is null
              and not exists (select 1 from public.synthetic_records s where s.entity_type = 'event' and s.entity_id = x.id)
