select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'complete_my_profile' and pg_get_function_identity_arguments(p.oid) = $bos$p_name text, p_interests text[], p_city text, p_region text, p_country text, p_adult boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.complete_my_profile(p_name text, p_interests text[], p_city text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_adult boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_name text := btrim(coalesce(p_name, ''));
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  -- p_adult: true = "I am 18 or older"; false = refused (no under-18 accounts until a guardian path exists); null = an older app that did not ask (unchanged).
  if p_adult is false then raise exception 'BuhurtOS is for people 18 or older for now. If you are under 18, you can still follow events and results without an account' using errcode = '22023'; end if;
  if char_length(v_name) not between 2 and 80 then raise exception 'your name must be 2 to 80 characters' using errcode = '22023'; end if;
  if p_interests is null or cardinality(p_interests) = 0 then raise exception 'choose at least one way you take part' using errcode = '22023'; end if;
  if not (p_interests <@ array['fighter','captain','organizer','volunteer','fan']::text[]) then raise exception 'unknown choice' using errcode = '22023'; end if;
  if char_length(coalesce(p_city, '')) > 80 or char_length(coalesce(p_region, '')) > 80 or char_length(coalesce(p_country, '')) > 80 then
    raise exception 'city, province and country are at most 80 characters' using errcode = '22023'; end if;
  insert into public.profiles (id, display_name, interests, city, region, country, onboarded_at, adult_confirmed_at)
  values (auth.uid(), v_name, (select array_agg(distinct x) from unnest(p_interests) x), nullif(btrim(p_city), ''), nullif(btrim(p_region), ''), nullif(btrim(p_country), ''), now(),
          case when p_adult then now() end)
  on conflict (id) do update set display_name = excluded.display_name, interests = excluded.interests, city = excluded.city, region = excluded.region,
    country = excluded.country, onboarded_at = coalesce(public.profiles.onboarded_at, now()),
    adult_confirmed_at = case when p_adult then coalesce(public.profiles.adult_confirmed_at, now()) else public.profiles.adult_confirmed_at end;
end $function$
;$bos$, $bos$drop function if exists public.complete_my_profile(p_name text, p_interests text[], p_city text, p_region text, p_country text, p_adult boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'confirm_registration_age' and pg_get_function_identity_arguments(p.oid) = $bos$p_reg uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.confirm_registration_age(p_reg uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r public.registrations;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  select * into v_r from public.registrations where id = p_reg;
  if not found or v_r.user_id is distinct from auth.uid() then raise exception 'registration not found' using errcode = 'P0002'; end if;
  if v_r.status not in ('pending', 'accepted') then raise exception 'this registration is no longer active' using errcode = '22023'; end if;
  if exists (select 1 from public.events e where e.id = v_r.event_id and e.closed_at is not null) then raise exception 'this event is closed' using errcode = '22023'; end if;
  if v_r.age_status = 'confirmed' then return jsonb_build_object('age_status', 'confirmed', 'changed', false); end if;
  update public.registrations set age_status = 'confirmed', age_confirmed_at = now() where id = p_reg;
  perform private.audit(v_r.event_id, 'registration.age_confirmed', p_reg::text, jsonb_build_object('by', 'registrant'));
  return jsonb_build_object('age_status', 'confirmed', 'changed', true);
end $function$
;$bos$, $bos$drop function if exists public.confirm_registration_age(p_reg uuid);$bos$);
