AS $function$
declare v_ids text[];
begin
  if not private.is_owner() then raise exception 'only the platform owner can delete screenshots' using errcode = '42501'; end if;
  with done as (
    update public.bug_screenshot_removals q set removed_at = now()
    where q.removed_at is null and q.path = any (coalesce(p_paths, '{}'))
      and not exists (select 1 from storage.objects o where o.bucket_id = 'bug-screenshots' and o.name = q.path)
    returning q.path)
  select array_agg(path) into v_ids from done;
  return private.retention_note('owner', 'bug_screenshot_files_deleted', v_ids);
