  return jsonb_build_object('code', v_c.pool_code, 'credential_id', v_c.id, 'label', v_c.label, 'training', v_training, 'expires_at', private.device_credential_expiry(v_c.id),
    'open_sessions', (select count(*) from public.event_sessions s where s.credential_id = v_c.id and s.ended_at is null), 'can_create', private.can_command(p_event));
end $function$
;$bos$, $bos$drop function if exists public.counter_pool_code(p_event uuid, p_training boolean);$bos$);
