 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_s public.lyst_counter_seats; v_old public.lyst_counts; v_target uuid; v_n integer;
begin
  perform private.assert_session_alive();   -- a dead device session has no authority here either (Pack 18.1)
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_id is null then raise exception 'an undo id is required' using errcode = '22023'; end if;
  -- counter follow-up 20261023000600: same per-action lock as counter_deliver_action, before any seat, match or field lock
  perform pg_advisory_xact_lock(hashtextextended('bos:counter-action:' || p_id::text, 0));
  if exists (select 1 from private.counter_legacy_evidence where id = p_id) or exists (select 1 from private.counter_recovery where id = p_id) then
    raise exception 'count ID is already kept as evidence for review' using errcode = '42501'; end if;
  select * into v_old from public.lyst_counts where id = p_id;
  if found then
    if v_old.seat_id <> p_seat or (select user_id from public.lyst_counter_seats where id = p_seat) is distinct from auth.uid() then raise exception 'that id belongs to someone else' using errcode = '42501'; end if;
    return jsonb_build_object('status', 'duplicate', 'total', private.lyst_seat_total(p_seat, v_old.round_no));
  end if;
  v_s := private.lyst_seat_for_counting(p_seat, p_round, true);
  select c.id into v_target from public.lyst_counts c
    where c.seat_id = p_seat and c.match_id = v_s.match_id and c.round_no = p_round and c.undo_of is null and not exists (select 1 from public.lyst_counts u where u.undo_of = c.id)
    order by c.created_at desc, c.id desc limit 1;
  if v_target is null then return jsonb_build_object('status', 'nothing', 'total', 0); end if;
  insert into public.lyst_counts (id, seat_id, match_id, round_no, weight, undo_of, operator_name) values (p_id, p_seat, v_s.match_id, p_round, 0, v_target, v_s.display_name) on conflict do nothing;
  get diagnostics v_n = row_count;
  return jsonb_build_object('status', case when v_n = 1 then 'ok' else 'nothing' end, 'total', private.lyst_seat_total(p_seat, p_round));
end $function$
;$bos$, $bos$drop function if exists public.counter_undo(p_id uuid, p_seat uuid, p_round integer);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'create_event_credential' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid, p_kind text, p_label text, p_role text, p_code_hash bytea, p_expires_at timestamp with time zone, p_pool_code text, p_training boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.create_event_credential(p_event uuid, p_kind text, p_label text, p_role text, p_code_hash bytea, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_pool_code text DEFAULT NULL::text, p_training boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_label text := btrim(coalesce(p_label, '')); v_id uuid; v_training boolean := coalesce(p_training, false);
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_event is null or not private.can_command(p_event) then raise exception 'only this event''s organizers, head marshal or secretary can create device codes' using errcode = '42501'; end if;
  if not private.is_organizer(p_event) and (p_kind = 'controller' or p_role = 'temporary_organizer') then raise exception 'only an organizer can make an Event Admin or stream controller code' using errcode = '42501'; end if;
  if p_kind is null or p_kind not in ('device', 'controller', 'counter_pool') then raise exception 'unknown credential kind' using errcode = '22023'; end if;
  if p_kind = 'device' and (p_role is null or p_role not in ('counter', 'scorekeeper', 'marshal', 'announcer', 'temporary_organizer')) then raise exception 'unknown device role' using errcode = '22023'; end if;
  if p_kind = 'controller' and p_role is distinct from 'broadcast_controller' then raise exception 'unknown controller role' using errcode = '22023'; end if;
  if p_kind = 'counter_pool' and p_role is distinct from 'counter' then raise exception 'the counter pool is for counters' using errcode = '22023'; end if;
  if p_kind = 'counter_pool' and (p_pool_code is null or p_pool_code !~ '^[0-9A-HJKMNP-TV-Z]{12}$') then raise exception 'the counter pool needs its code' using errcode = '22023'; end if;
  if p_kind <> 'counter_pool' and p_pool_code is not null then raise exception 'only the counter pool keeps its code' using errcode = '22023'; end if;
  if v_training and p_kind <> 'counter_pool' then raise exception 'only a counter pool can be a training one' using errcode = '22023'; end if;
  if p_kind = 'counter_pool' and v_label = '' then v_label := case when v_training then 'Training Counter QR' else 'Counter QR' end; end if;
  if char_length(v_label) < 1 or char_length(v_label) > 40 then raise exception 'a device name is 1 to 40 characters' using errcode = '22023'; end if;
  if p_code_hash is null or octet_length(p_code_hash) <> 32 then raise exception 'bad code verifier' using errcode = '22023'; end if;
  if p_expires_at is not null and p_expires_at <= clock_timestamp() then raise exception 'the expiry must be in the future' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('bos:cred:' || p_event::text, 0));
  if p_kind = 'device' and (select count(*) from public.event_credentials where event_id = p_event and kind = 'device' and revoked_at is null) >= 40 then
    raise exception 'an event can have 40 device codes at a time' using errcode = '22023'; end if;
  if p_kind = 'controller' and exists (select 1 from public.event_credentials where event_id = p_event and kind = 'controller' and revoked_at is null) then
    raise exception 'this event already has a stream controller code: replace or revoke it' using errcode = '22023'; end if;
  if p_kind = 'counter_pool' and exists (select 1 from public.event_credentials where event_id = p_event and kind = 'counter_pool' and training = v_training and revoked_at is null) then
    raise exception '%', case when v_training then 'this event already has a Training Counter QR: show it, or revoke it first' else 'this event already has a Counter QR: show it, or revoke it first' end using errcode = '22023'; end if;
  if exists (select 1 from public.event_credentials where event_id = p_event and lower(label) = lower(v_label) and revoked_at is null) then
    raise exception 'a device with that name already exists for this event' using errcode = '23505'; end if;
  insert into public.event_credentials (event_id, kind, label, role, code_hash, expires_at, created_by, pool_code, training)
  values (p_event, p_kind, v_label, p_role, p_code_hash, p_expires_at, auth.uid(), case when p_kind = 'counter_pool' then p_pool_code end, v_training) returning id into v_id;
  perform private.audit(p_event, case p_kind when 'controller' then 'controller.created' when 'counter_pool' then (case when v_training then 'training_pool.created' else 'counter_pool.created' end) else 'device.created' end, v_label, jsonb_build_object('credential_id', v_id, 'role', p_role, 'training', v_training));
  return jsonb_build_object('id', v_id, 'kind', p_kind, 'label', v_label, 'role', p_role, 'training', v_training, 'expires_at', private.device_credential_expiry(v_id));
end $function$
;$bos$, $bos$drop function if exists public.create_event_credential(p_event uuid, p_kind text, p_label text, p_role text, p_code_hash bytea, p_expires_at timestamp with time zone, p_pool_code text, p_training boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'decide_card' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_decision text, p_game_use boolean, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.decide_card(p_id uuid, p_decision text, p_game_use boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards; v_fname text;
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not private.is_my_fighter(v_row.fighter_id) then raise exception 'only the fighter on the card can answer' using errcode = '42501'; end if;
  if v_row.status <> 'awaiting_approval' then raise exception 'this card is not waiting for your answer' using errcode = '55000'; end if;
  if p_decision not in ('approved', 'declined') then raise exception 'answer approved or declined' using errcode = '22023'; end if;
  if p_decision = 'approved' and private.card_minor(v_row.fighter_id) then
    raise exception 'a parent or guardian has to approve this card in person with a team admin' using errcode = '42501'; end if;
  update public.cards set status = p_decision, game_use = (p_decision = 'approved' and coalesce(p_game_use, false)), updated_at = now() where id = p_id;
  insert into public.card_consents (card_id, fighter_id, decided_by, decision, game_use, note)
  values (p_id, v_row.fighter_id, auth.uid(), p_decision, p_decision = 'approved' and coalesce(p_game_use, false), left(nullif(btrim(coalesce(p_note, '')), ''), 300));
  select display_name into v_fname from public.fighters where id = v_row.fighter_id;
  if private.card_notifications_ready() then
  insert into public.notifications (user_id, kind, payload, dedupe_key)
  select distinct u, 'card_decided', jsonb_build_object('card_id', p_id, 'decision', p_decision, 'fighter_name', v_fname),
         'card_decided:' || p_id::text || ':' || extract(epoch from now())::bigint
  from unnest(array[v_row.created_by, v_row.updated_by]) u where u is not null and u <> auth.uid();
  end if;
  perform private.audit(null, 'card.decided', v_row.team_id::text, jsonb_build_object('card', p_id, 'decision', p_decision, 'game_use', coalesce(p_game_use, false)));
  return jsonb_build_object('status', p_decision);
end $function$
;$bos$, $bos$drop function if exists public.decide_card(p_id uuid, p_decision text, p_game_use boolean, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'decide_team_join' and pg_get_function_identity_arguments(p.oid) = $bos$p_request uuid, p_decision text$bos$), $bos$CREATE OR REPLACE FUNCTION public.decide_team_join(p_request uuid, p_decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_req public.team_join_requests; v_team public.teams; v_name text; v_fighter uuid;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_decision not in ('approved', 'declined') then raise exception 'decision must be approved or declined' using errcode = '22023'; end if;
  select * into v_req from public.team_join_requests where id = p_request for update;
  if not found or not private.can_manage_team(v_req.team_id) then raise exception 'you cannot decide this request' using errcode = '42501'; end if;
  if v_req.requester_id = auth.uid() then raise exception 'you cannot decide your own request' using errcode = '42501'; end if;
  if v_req.status <> 'pending' then raise exception 'this request has already been answered' using errcode = '22023'; end if;
  select * into v_team from public.teams where id = v_req.team_id;

  if p_decision = 'approved' then
    v_name := private.person_name(v_req.requester_id);
    if v_name is null then raise exception 'this person has no name on their profile yet' using errcode = '22023'; end if;
    select fighter_id into v_fighter from public.fighter_accounts where user_id = v_req.requester_id;
    if v_fighter is null then
      v_fighter := private.ensure_fighter_for_account(v_req.requester_id, v_name, v_req.team_id, 'team_join');
    else
      update public.fighters set team_id = v_req.team_id where id = v_fighter and team_id is null;
    end if;
    if not exists (select 1 from public.team_memberships where fighter_id = v_fighter and team_id = v_req.team_id and (to_date is null or to_date >= current_date)) then
      insert into public.team_memberships (fighter_id, team_id, role, from_date) values (v_fighter, v_req.team_id, 'fighter', current_date);
    end if;
  end if;

  update public.team_join_requests set status = p_decision, decided_by = auth.uid(), decided_at = now() where id = p_request;
  insert into public.notifications (user_id, kind, payload)
  values (v_req.requester_id, 'team_join_decided', jsonb_build_object('request_id', p_request, 'team_id', v_team.id, 'team_name', v_team.name, 'team_slug', v_team.slug, 'decision', p_decision));
  update public.notifications set read_at = coalesce(read_at, now()) where kind = 'team_join_requested' and payload ->> 'request_id' = p_request::text;
  perform private.audit(null, 'team.join_' || p_decision, v_team.id::text, jsonb_build_object('request', p_request));
end $function$
;$bos$, $bos$drop function if exists public.decide_team_join(p_request uuid, p_decision text);$bos$);
