 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_event is null or not (private.is_organizer(p_event) or private.can_command(p_event) or private.can_adjust_queue(p_event)) then
    raise exception 'only event staff can see this' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('match_id', m.id, 'field', coalesce(nullif(btrim(m.field), ''), 'Field 1'), 'state', m.queue_state,
      'a', private.lyst_side_name(m.entry_a), 'b', private.lyst_side_name(m.entry_b),
      'pinged', (select count(*) from jsonb_array_elements_text(private.discord_mentions_for(m.id))),
      'on_way', (select coalesce(jsonb_agg(coalesce(f.display_name, 'Someone') order by a.acked_at), '[]'::jsonb)
                 from public.discord_acks a left join public.fighter_accounts fa on fa.user_id = a.user_id left join public.fighters f on f.id = fa.fighter_id
                 where a.match_id = m.id))
      order by case m.queue_state when 'active' then 0 when 'on_deck' then 1 else 2 end, m.field, m.queue_order nulls last)
    from public.matches m join public.competitions k on k.id = m.competition_id
    where k.event_id = p_event and m.queue_state in ('active', 'on_deck', 'in_the_hole') and m.entry_a is not null and m.entry_b is not null), '[]'::jsonb);
end $function$
