 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid; v_reg public.registrations; v_event public.events; v_arrived boolean; v_in boolean;
begin
  select user_id into v_uid from public.discord_links where discord_user_id = p_discord_id;
  if v_uid is null then return jsonb_build_object('linked', false); end if;
  select r.* into v_reg from public.registrations r join public.events e on e.id = r.event_id
  where r.status = 'accepted' and e.status = 'published' and current_date between e.starts_on and coalesce(e.ends_on, e.starts_on)
    and (r.user_id = v_uid or r.fighter_id in (select fighter_id from public.fighter_accounts where user_id = v_uid))
  order by e.starts_on limit 1;
  if not found then return jsonb_build_object('linked', true, 'registration', false); end if;
  select * into v_event from public.events where id = v_reg.event_id;
  select coalesce(bool_or(passed) filter (where check_name = 'arrived'), false), coalesce(bool_or(passed) filter (where check_name = 'checked_in'), false)
    into v_arrived, v_in from public.registration_checks where registration_id = v_reg.id;
  if v_in then return jsonb_build_object('linked', true, 'registration', true, 'event', v_event.name, 'state', 'checked_in', 'changed', false); end if;
  if v_arrived then return jsonb_build_object('linked', true, 'registration', true, 'event', v_event.name, 'state', 'arrived', 'changed', false); end if;
  insert into public.registration_checks (registration_id, check_name, passed) values (v_reg.id, 'arrived', true)
    on conflict (registration_id, check_name) do update set passed = true, at = now();
  perform private.audit(v_event.id, 'checkin.arrived', v_reg.id::text, jsonb_build_object('from', 'expected', 'via', 'discord'));
  return jsonb_build_object('linked', true, 'registration', true, 'event', v_event.name, 'state', 'arrived', 'changed', true);
end $function$
;$bos$, $bos$drop function if exists public.discord_arrived(p_discord_id text);$bos$);
