 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; v_n integer := 0; v_k integer;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    if r ->> 'outcome' = 'sent' then
      update public.discord_boards b set message_id = coalesce(left(r ->> 'message_id', 40), b.message_id),
        channel_id = case when r ? 'channel_id' then nullif(r ->> 'channel_id', '') else b.channel_id end,
        rendered_at = now(), claimed_at = null, error = null,
        dirty_at = case when b.dirty_at <= b.claimed_dirty_at then null else b.dirty_at end
      where b.event_id = (r ->> 'event_id')::uuid and b.claimed_at is not null;
    elsif r ->> 'outcome' = 'retry' then
      update public.discord_boards b set claimed_at = null, error = left(r ->> 'error', 300) where b.event_id = (r ->> 'event_id')::uuid;
    else
      update public.discord_boards b set claimed_at = null, dirty_at = null, error = left(coalesce(r ->> 'error', 'failed'), 300) where b.event_id = (r ->> 'event_id')::uuid;
    end if;
    get diagnostics v_k = row_count; v_n := v_n + v_k;
  end loop;
  return v_n;
end $function$
