 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb;
begin
  with picked as (
    select c.event_id from public.discord_channels c
    where (c.state = 'wanted')
       or (c.state = 'creating' and c.claimed_at < now() - interval '2 minutes')
       or (c.state = 'failed' and c.attempts < 3 and c.claimed_at < now() - interval '5 minutes')
       or (c.state = 'closing' and (c.claimed_at is null or c.claimed_at < now() - interval '2 minutes'))
    order by c.wanted_at limit 5
    for update skip locked),
  upd as (
    update public.discord_channels c
    set state = case when c.state = 'closing' then 'closing' else 'creating' end,
        attempts = case when c.state = 'closing' then c.attempts else c.attempts + 1 end,
        claimed_at = now()
    from picked where c.event_id = picked.event_id
    returning c.*)
  select coalesce(jsonb_agg(private.discord_event_base(u.event_id) || jsonb_build_object(
           'event_id', u.event_id,
           'action', case when u.state = 'closing' then 'close' else 'create' end,
           'board_channel_id', u.board_channel_id, 'calls_channel_id', u.calls_channel_id,
           'results_channel_id', u.results_channel_id, 'announce_channel_id', u.announce_channel_id,
           'recap', case when u.state = 'closing' then private.discord_event_recap(u.event_id) end,
           'general_board_message_id', (select b.message_id from public.discord_boards b where b.event_id = u.event_id and b.channel_id is null))), '[]'::jsonb)
    into v from upd u;
  return v;
end $function$
