 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; v_n integer := 0; v_k integer; v_event uuid;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    v_event := (r ->> 'event_id')::uuid;
    update public.discord_channels c set
      board_channel_id = coalesce(case when r ->> 'board_channel_id' ~ '^[0-9]{15,22}$' then r ->> 'board_channel_id' end, c.board_channel_id),
      calls_channel_id = coalesce(case when r ->> 'calls_channel_id' ~ '^[0-9]{15,22}$' then r ->> 'calls_channel_id' end, c.calls_channel_id),
      results_channel_id = coalesce(case when r ->> 'results_channel_id' ~ '^[0-9]{15,22}$' then r ->> 'results_channel_id' end, c.results_channel_id),
      announce_channel_id = coalesce(case when r ->> 'announce_channel_id' ~ '^[0-9]{15,22}$' then r ->> 'announce_channel_id' end, c.announce_channel_id)
    where c.event_id = v_event;
    if r ->> 'outcome' = 'ready' then
      update public.discord_channels set state = 'ready', ready_at = now(), claimed_at = null, error = null
      where event_id = v_event and state = 'creating'
        and board_channel_id is not null and calls_channel_id is not null and results_channel_id is not null and announce_channel_id is not null;
      get diagnostics v_k = row_count;
      if v_k > 0 then
        update public.discord_boards set message_id = null, channel_id = null, dirty_at = clock_timestamp(), claimed_at = null where event_id = v_event;
        perform private.discord_board_touch(v_event);
      end if;
    elsif r ->> 'outcome' = 'closed' then
      update public.discord_channels set state = 'closed', closed_at = now(), claimed_at = null, error = null where event_id = v_event and state = 'closing';
      get diagnostics v_k = row_count;
    elsif r ->> 'outcome' = 'retry' then
      update public.discord_channels set state = case when state = 'closing' then 'closing' else 'wanted' end, claimed_at = null,
        attempts = case when state = 'closing' then attempts else greatest(attempts - 1, 0) end, error = left(r ->> 'error', 300)
      where event_id = v_event and state in ('creating', 'closing');
      get diagnostics v_k = row_count;
    elsif r ->> 'outcome' = 'broken' then
      update public.discord_channels set state = 'failed', attempts = 3, error = left(coalesce(r ->> 'error', 'channel unavailable'), 300)
      where event_id = v_event and state in ('ready', 'closing', 'closed');
      get diagnostics v_k = row_count;
      if v_k > 0 then
        update public.discord_boards set message_id = null, channel_id = null where event_id = v_event and channel_id is not null;
        perform private.discord_board_touch(v_event);
      end if;
    else
      update public.discord_channels set state = case when state = 'closing' then 'closed' else 'failed' end,
        error = left(coalesce(r ->> 'error', 'failed'), 300)
      where event_id = v_event and state in ('creating', 'closing');
      get diagnostics v_k = row_count;
    end if;
    v_n := v_n + v_k;
  end loop;
  return v_n;
end $function$
;$bos$, $bos$drop function if exists public.discord_channels_report(p_results jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'discord_claim' and pg_get_function_identity_arguments(p.oid) = $bos$p_limit integer$bos$), $bos$CREATE OR REPLACE FUNCTION public.discord_claim(p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, kind text, payload jsonb, attempts integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.discord_posts p set state = 'failed', error = coalesce(p.error, 'gave up after 5 attempts')
  where p.attempts >= 5 and (p.state = 'retry' or (p.state = 'sending' and p.claimed_at < now() - interval '2 minutes'));
  return query
  with picked as (
    select p.id from public.discord_posts p
    where (p.state = 'pending' or (p.state = 'retry' and p.next_at <= now()) or (p.state = 'sending' and p.claimed_at < now() - interval '2 minutes'))
      and not exists (select 1 from public.discord_channels c where c.event_id = p.event_id and c.state in ('wanted', 'creating') and c.wanted_at > now() - interval '2 minutes')
    order by p.created_at
    limit greatest(1, least(coalesce(p_limit, 20), 50))
    for update skip locked),
  upd as (
    update public.discord_posts p set state = 'sending', claimed_at = now(), attempts = p.attempts + 1
    from picked where p.id = picked.id
    returning p.id, p.kind, p.payload, p.attempts, p.created_at, p.event_id, p.match_id),
  comp as (
    select upd.id, coalesce((upd.payload ->> 'competition_id')::uuid, (select m.competition_id from public.matches m where m.id = upd.match_id)) as competition_id from upd)
  select upd.id, upd.kind,
         upd.payload || jsonb_strip_nulls(jsonb_build_object(
           'route_channel_id', rt.ch,
           'route_event_id', case when rt.ch is not null then upd.event_id end,
           'route_field_key', case when rt.ch is not null and upd.kind in ('now', 'on_deck', 'hole', 'moved') then private.field_key(upd.payload ->> 'field') end,
           'route_thread_id', case when rt.ch is null then null
                                   when upd.kind in ('now', 'on_deck', 'hole', 'moved') then (select c.field_threads ->> private.field_key(upd.payload ->> 'field') from public.discord_channels c where c.event_id = upd.event_id)
                                   when upd.kind in ('result', 'round', 'podium') and th.on and comp.competition_id is not null then (select c.competition_threads ->> comp.competition_id::text from public.discord_channels c where c.event_id = upd.event_id)
                                   end,
           'route_competition_id', case when rt.ch is not null and upd.kind in ('result', 'round', 'podium') and th.on then comp.competition_id end,
           'route_thread_name', case when rt.ch is not null and upd.kind in ('result', 'round', 'podium') and th.on then upd.payload ->> 'competition_name' end)),
         upd.attempts, upd.created_at
  from upd join comp on comp.id = upd.id
  cross join lateral (select private.discord_route(upd.event_id, upd.kind) as ch) rt
  cross join lateral (select coalesce((select f.threads from public.discord_feeds f where f.event_id = upd.event_id), false) as on) th
  order by upd.created_at;
end $function$
;$bos$, $bos$drop function if exists public.discord_claim(p_limit integer);$bos$);
