 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with q as (select btrim(coalesce(p_query, '')) as s),
  found as (
    select f.id, f.display_name, t.name as team, f.inactive_at
    from public.fighters f left join public.teams t on t.id = f.team_id, q
    where length(q.s) >= 2 and f.display_name ilike '%' || replace(replace(q.s, '%', ''), '_', '') || '%' and not private.is_synthetic('fighter', f.id)
    order by (lower(f.display_name) = lower(q.s)) desc, (lower(f.display_name) like lower(q.s) || '%') desc, f.display_name
    limit 3),
  rec as (
    select fo.id,
