    from found fo
    left join public.entries en on en.fighter_id = fo.id
    left join public.matches m on (m.entry_a = en.id or m.entry_b = en.id)
      and not private.is_synthetic('event', (select k.event_id from public.competitions k where k.id = m.competition_id))
    group by fo.id)
  select coalesce(jsonb_agg(jsonb_build_object('id', fo.id, 'name', fo.display_name, 'team', fo.team, 'inactive', fo.inactive_at is not null,
                                               'fights', coalesce(r.fights, 0), 'wins', coalesce(r.wins, 0))), '[]'::jsonb)
  from found fo left join rec r on r.id = fo.id
$function$
