 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid; v jsonb;
begin
  select user_id into v_uid from public.discord_links where discord_user_id = p_discord_id;
  if v_uid is null then return jsonb_build_object('linked', false); end if;
  select jsonb_build_object('linked', true, 'event_name', e.name, 'event_slug', e.slug, 'test_event', private.is_synthetic('event', e.id),
           'competition_name', k.name, 'round_label', nullif(m.round_label, ''), 'field', coalesce(nullif(btrim(m.field), ''), 'Field 1'),
           'state', m.queue_state, 'a', private.lyst_side_name(m.entry_a), 'b', private.lyst_side_name(m.entry_b),
           'ahead', (select count(*) from public.matches x where x.competition_id in (select id from public.competitions where event_id = e.id)
                       and private.field_key(x.field) = private.field_key(m.field) and x.queue_state in ('active', 'on_deck', 'in_the_hole')
                       and coalesce(x.queue_order, 0) < coalesce(m.queue_order, 0)))
    into v
  from public.matches m join public.competitions k on k.id = m.competition_id join public.events e on e.id = k.event_id
  where e.status = 'published' and not private.discord_event_finished(e)
    and m.queue_state in ('active', 'on_deck', 'in_the_hole', 'scheduled') and m.entry_a is not null and m.entry_b is not null
    and (v_uid in (select private.entry_recipient_users(m.entry_a)) or v_uid in (select private.entry_recipient_users(m.entry_b)))
  order by case m.queue_state when 'active' then 0 when 'on_deck' then 1 when 'in_the_hole' then 2 else 3 end, m.queue_order nulls last, m.scheduled_at nulls last
  limit 1;
  return coalesce(v, jsonb_build_object('linked', true, 'none', true));
end $function$
