    from public.matches m join public.competitions k on k.id = m.competition_id join public.events e on e.id = k.event_id
    where e.status = 'published' and not private.discord_event_finished(e) and current_date between e.starts_on - 1 and coalesce(e.ends_on, e.starts_on)
      and m.queue_state <> 'final' and m.entry_a is not null and m.entry_b is not null
      and (v_uid in (select private.entry_recipient_users(m.entry_a)) or v_uid in (select private.entry_recipient_users(m.entry_b)))
