 SET search_path TO ''
AS $function$
declare v_event uuid; v_comp public.competitions;
begin
  v_event := coalesce(private.discord_live_event(),
    (select k.event_id from public.matches m join public.competitions k on k.id = m.competition_id join public.events e on e.id = k.event_id
     where m.queue_state = 'final' and e.status = 'published' order by m.finalized_at desc nulls last limit 1));
  if v_event is null then return jsonb_build_object('found', false); end if;
  select k.* into v_comp from public.competitions k where k.event_id = v_event
    and (coalesce(btrim(p_query), '') = '' or k.name ilike '%' || replace(replace(left(btrim(p_query), 60), '%', ''), '_', '') || '%')
  order by (select max(m.finalized_at) from public.matches m where m.competition_id = k.id) desc nulls last, k.sort limit 1;
  if not found then return jsonb_build_object('found', false, 'event_name', (select name from public.events where id = v_event),
    'competitions', (select coalesce(jsonb_agg(name order by sort), '[]'::jsonb) from public.competitions where event_id = v_event)); end if;
  return private.discord_event_base(v_event) || jsonb_build_object('found', true, 'competition_name', v_comp.name, 'rows', private.discord_standings(v_comp.id));
end $function$
