 SET search_path TO ''
AS $function$
declare v jsonb;
begin
  if p_when not in ('daily', 'morning') then raise exception 'bad request' using errcode = '22023'; end if;
  with due as (
    select e.*, case when e.starts_on = current_date + 7 then 'week' when e.starts_on = current_date + 1 then 'tomorrow' else 'today' end as kind
    from public.events e
    where e.status = 'published' and e.archived_at is null and not private.is_synthetic('event', e.id)
      and ((p_when = 'daily' and e.starts_on in (current_date + 7, current_date + 1)) or (p_when = 'morning' and e.starts_on = current_date))),
  won as (select d.* from due d where private.discord_once('countdown:' || d.id || ':' || d.kind))
  select coalesce(jsonb_agg(jsonb_build_object('kind', w.kind, 'name', w.name, 'slug', w.slug, 'starts_on', w.starts_on, 'ends_on', w.ends_on,
           'venue', nullif(btrim(w.venue), ''), 'city', nullif(concat_ws(', ', nullif(btrim(w.city), ''), nullif(btrim(w.region), '')), ''),
           'time_note', nullif(btrim(w.time_note), ''), 'registration_mode', w.registration_mode, 'closes_at', w.registration_closes_at)
         order by w.starts_on), '[]'::jsonb) into v from won w;
  return v;
end $function$
;$bos$, $bos$drop function if exists public.discord_countdown_claim(p_when text);$bos$);
