 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; n integer := 0; v_first record; v_text text;
begin
  for r in
    select distinct e.id as event_id, e.slug, e.name, e.venue, e.city, e.time_note, reg.user_id, reg.fighter_id
    from public.events e join public.registrations reg on reg.event_id = e.id and reg.status = 'accepted' and reg.user_id is not null
    join public.discord_links l on l.user_id = reg.user_id and l.pings
    where e.status = 'published' and e.archived_at is null and e.closed_at is null and current_date between e.starts_on and coalesce(e.ends_on, e.starts_on)
      and coalesce((select f.dm_fighters from public.discord_feeds f where f.event_id = e.id), true)
  loop
    v_text := 'Check-in is open today for **' || r.name || '**' || coalesce(' at ' || nullif(concat_ws(', ', r.venue, r.city), ''), '') || '.' ||
              coalesce(' 🕘 ' || nullif(r.time_note, ''), '') || ' Come to the desk when you arrive (or type /here in Discord once you are on site).';
    if private.discord_dm_enqueue(r.user_id, r.event_id, 'check_in', 'check_in:' || r.event_id::text || ':' || r.user_id::text || ':' || current_date::text,
         jsonb_build_object('title', '📋 Check-in is open', 'text', v_text, 'path', '/events/' || r.slug)) then n := n + 1; end if;
    select m.id, m.field, m.scheduled_at, m.round_label, k.name as competition,
           private.lyst_side_name(case when en.id = m.entry_a then m.entry_b else m.entry_a end) as opponent
      into v_first
    from public.entries en join public.matches m on (m.entry_a = en.id or m.entry_b = en.id)
    join public.competitions k on k.id = m.competition_id
    where k.event_id = r.event_id and m.queue_state <> 'final' and m.entry_a is not null and m.entry_b is not null
      and (en.fighter_id = r.fighter_id or exists (select 1 from public.entry_fighters ef where ef.entry_id = en.id and ef.fighter_id = r.fighter_id))
    order by m.scheduled_at nulls last, m.plan_order nulls last, m.queue_order nulls last, m.created_at
    limit 1;
    if found then
      v_text := 'Your first fight today: **' || coalesce(v_first.competition, 'competition') || '**' || coalesce(' ' || nullif(v_first.round_label, ''), '') ||
                coalesce(' vs **' || nullif(v_first.opponent, '') || '**', '') || ' on **' || coalesce(nullif(btrim(v_first.field), ''), 'Field 1') || '**' ||
                case when v_first.scheduled_at is not null then ' at about ' || to_char(v_first.scheduled_at at time zone coalesce((select timezone from public.events where id = r.event_id), 'UTC'), 'HH24:MI') else '' end ||
                '. Watch the fight-calls channel for your @ when you are on deck.';
      if private.discord_dm_enqueue(r.user_id, r.event_id, 'first_fight', 'first_fight:' || r.event_id::text || ':' || r.user_id::text || ':' || current_date::text,
           jsonb_build_object('title', '⚔️ Your first fight', 'text', v_text, 'path', '/events/' || r.slug || '#my-next-fight', 'match_id', v_first.id)) then n := n + 1; end if;
    end if;
  end loop;
  return n;
end $function$
;$bos$, $bos$drop function if exists public.discord_dm_morning_claim();$bos$);
