 SET search_path TO ''
AS $function$
declare v jsonb;
begin
  update public.discord_dms d set state = 'failed', error = coalesce(d.error, 'gave up after 5 attempts')
  where d.attempts >= 5 and d.state = 'sending' and d.claimed_at < now() - interval '2 minutes';
  with picked as (
    select d.id from public.discord_dms d
    where d.state = 'pending' or (d.state = 'sending' and d.claimed_at < now() - interval '2 minutes')
    order by d.created_at limit 20 for update skip locked),
  upd as (update public.discord_dms d set state = 'sending', claimed_at = now(), attempts = d.attempts + 1 from picked where d.id = picked.id
          returning d.id, d.discord_user_id, d.kind, d.payload)
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'discord_user_id', discord_user_id, 'kind', kind, 'payload', payload)), '[]'::jsonb) into v from upd;
  return v;
end $function$
