 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; n integer := 0;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    if (r ->> 'id') !~ '^[0-9a-f-]{36}$' then continue; end if;
    update public.discord_dms set
      state = case r ->> 'outcome' when 'sent' then 'sent' when 'retry' then case when attempts >= 5 then 'failed' else 'pending' end else 'failed' end,
      sent_at = case when r ->> 'outcome' = 'sent' then now() end,
      error = case when r ->> 'outcome' = 'sent' then null else left(r ->> 'error', 280) end
    where id = (r ->> 'id')::uuid and state = 'sending';
    n := n + 1;
  end loop;
  return n;
end $function$
