 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with live as (
    select e.id, private.discord_event_spec(e.id) as spec
    from public.events e
    where e.status = 'published' and e.archived_at is null and coalesce(e.ends_on, e.starts_on) >= current_date
      and not private.is_synthetic('event', e.id)
      and coalesce((select f.scheduled_event from public.discord_feeds f where f.event_id = e.id), true)),
  ups as (
    select l.id, l.spec, md5(l.spec::text) as h, k.scheduled_event_id, k.state, k.spec_hash, k.synced_at
    from live l left join public.discord_event_links k on k.event_id = l.id
    where (k.event_id is null and (l.spec ->> 'start')::timestamptz > now() + interval '10 minutes')
       or (k.state = 'active' and k.spec_hash is distinct from md5(l.spec::text))
       or (k.state = 'failed' and k.synced_at < now() - interval '1 hour' and (k.scheduled_event_id is not null or (l.spec ->> 'start')::timestamptz > now() + interval '10 minutes'))),
  cancels as (
    select k.event_id, k.scheduled_event_id from public.discord_event_links k
    where k.state = 'active' and k.scheduled_event_id is not null and not exists (select 1 from live l where l.id = k.event_id)
      and exists (select 1 from public.events e where e.id = k.event_id
                  and (e.status <> 'published' or e.archived_at is not null
                       or not coalesce((select f.scheduled_event from public.discord_feeds f where f.event_id = e.id), true))))
  select coalesce((select jsonb_agg(x) from (
      select jsonb_build_object('event_id', u.id, 'action', 'upsert', 'scheduled_event_id', u.scheduled_event_id, 'spec', u.spec, 'hash', u.h) as x from ups u
      union all
      select jsonb_build_object('event_id', c.event_id, 'action', 'cancel', 'scheduled_event_id', c.scheduled_event_id) from cancels c
      limit 10) q), '[]'::jsonb)
$function$
;$bos$, $bos$drop function if exists public.discord_events_due();$bos$);
