 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; v_n integer := 0;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    insert into public.discord_event_links (event_id, scheduled_event_id, spec_hash, state, synced_at, error)
    values ((r ->> 'event_id')::uuid,
            case when r ->> 'scheduled_event_id' ~ '^[0-9]{15,22}$' then r ->> 'scheduled_event_id' end,
            r ->> 'hash',
            case r ->> 'outcome' when 'synced' then 'active' when 'canceled' then 'canceled' else 'failed' end,
            now(), left(r ->> 'error', 300))
    on conflict (event_id) do update set
      scheduled_event_id = coalesce(excluded.scheduled_event_id, public.discord_event_links.scheduled_event_id),
      spec_hash = case when excluded.state = 'active' then excluded.spec_hash else public.discord_event_links.spec_hash end,
      state = excluded.state, synced_at = now(), error = excluded.error;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $function$
