 SET search_path TO ''
AS $function$
declare v_was boolean; v_new public.discord_feeds; v_fields jsonb; b text;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_event is null or not private.is_organizer(p_event) then raise exception 'only an organizer of this event can change its Discord feed' using errcode = '42501'; end if;
  if jsonb_typeof(coalesce(p_settings, 'null'::jsonb)) <> 'object' then raise exception 'send the settings as an object' using errcode = '22023'; end if;
  foreach b in array array['enabled', 'post_on_deck', 'post_now', 'post_results', 'post_announcements', 'post_board', 'ping_fighters', 'pickem',
                           'staff_alerts', 'threads', 'scheduled_event', 'going_live', 'dm_fighters'] loop
    if p_settings ? b and jsonb_typeof(p_settings -> b) <> 'boolean' then raise exception '% must be true or false', b using errcode = '22023'; end if;
  end loop;
