  insert into public.discord_feeds (event_id) values (p_event) on conflict (event_id) do nothing;
  update public.discord_feeds set
    enabled = coalesce((p_settings ->> 'enabled')::boolean, enabled),
    post_on_deck = coalesce((p_settings ->> 'post_on_deck')::boolean, post_on_deck),
    post_now = coalesce((p_settings ->> 'post_now')::boolean, post_now),
    post_results = coalesce((p_settings ->> 'post_results')::boolean, post_results),
