  where event_id = p_event returning * into v_new;
  perform private.audit(p_event, 'discord.feed', p_event::text, to_jsonb(v_new) - 'updated_by');
  if v_new.enabled and not coalesce(v_was, false) then
    select coalesce(jsonb_agg(jsonb_build_object('field', x.payload ->> 'field', 'side_a', x.payload ->> 'side_a', 'side_b', x.payload ->> 'side_b',
