 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_id text; v_name text;
begin
  if v_uid is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if to_regclass('auth.identities') is null then return public.discord_link_status(); end if;
  execute $q$select i.provider_id, left(coalesce(i.identity_data -> 'custom_claims' ->> 'global_name', i.identity_data ->> 'full_name',
                                                 i.identity_data ->> 'name', i.identity_data ->> 'user_name'), 64)
             from auth.identities i where i.user_id = $1 and i.provider = 'discord' order by i.updated_at desc nulls last limit 1$q$
    into v_id, v_name using v_uid;
  if v_id is null or v_id !~ '^[0-9]{15,22}$' then
    delete from public.discord_links where user_id = v_uid;
  else
    insert into public.discord_links (user_id, discord_user_id, discord_name) values (v_uid, v_id, v_name)
    on conflict (user_id) do update set discord_user_id = excluded.discord_user_id, discord_name = excluded.discord_name, updated_at = now();
  end if;
  return public.discord_link_status();
end $function$
