select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'discord_live_claim' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION public.discord_live_claim()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb;
begin
  with picked as (
    select l.match_id from public.discord_live_edits l
    where not l.done and l.dirty_at is not null and l.dirty_at > coalesce(l.edited_dirty_at, '-infinity'::timestamptz)
      and (l.claimed_at is null or l.claimed_at < now() - interval '30 seconds')
      and (l.edited_at is null or l.edited_at < now() - interval '4 seconds')
    order by l.dirty_at limit 15
    for update skip locked),
  upd as (
    update public.discord_live_edits l set claimed_at = now(), claimed_dirty_at = l.dirty_at
    from picked where l.match_id = picked.match_id returning l.match_id, l.event_id, l.claimed_dirty_at)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'match_id', u.match_id, 'dirty_at', u.claimed_dirty_at, 'message_id', p.message_id,
      'channel_id', coalesce(p.channel_id,
                             (select c.field_threads ->> private.field_key(m.field) from public.discord_channels c where c.event_id = u.event_id and c.state in ('ready', 'closing', 'closed')),
                             private.discord_route(u.event_id, 'now')),
      'channel_guess', case when p.channel_id is null then true end)) || jsonb_build_object(
      'payload', private.discord_match_payload(u.match_id) || jsonb_build_object(
          'state', m.queue_state, 'result', m.result, 'score_a', m.score_a, 'score_b', m.score_b,
          'live_a', ls.score_a, 'live_b', ls.score_b, 'phase', nullif(ls.phase, ''),
          'h2h', p.payload -> 'h2h'))), '[]'::jsonb)
    into v
  from upd u join public.matches m on m.id = u.match_id
  join lateral (select * from public.discord_posts x where x.match_id = u.match_id and x.kind = 'now' and x.state = 'sent' and x.message_id is not null
                order by x.created_at desc limit 1) p on true
  left join public.match_live_scores ls on ls.match_id = u.match_id;
