  update public.discord_live_edits l set done = true, claimed_at = null
  where l.claimed_at = now() and not exists (select 1 from public.discord_posts x where x.match_id = l.match_id and x.kind = 'now' and x.state = 'sent' and x.message_id is not null)
    and not exists (select 1 from public.discord_posts x where x.match_id = l.match_id and x.kind = 'now' and x.state in ('pending', 'sending', 'retry'));
  return v;
end $function$
