      done = (r ->> 'outcome' = 'gone') or (r ->> 'outcome' = 'sent' and exists (select 1 from public.matches m where m.id = l.match_id and m.queue_state = 'final')
                                           and l.dirty_at <= l.claimed_dirty_at),
      error = case when r ->> 'outcome' in ('sent') then null else left(r ->> 'error', 300) end
    where l.match_id = (r ->> 'match_id')::uuid;
    v_n := v_n + 1;
  end loop;
