 SET search_path TO ''
AS $function$
declare r jsonb; v_n integer := 0; v_k integer;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    if r ->> 'outcome' = 'sent' then
      update public.discord_posts set state = 'sent', sent_at = now(), message_id = left(r ->> 'message_id', 40), error = null,
        channel_id = case when coalesce(r ->> 'channel_id', '') ~ '^[0-9]{15,22}$' then r ->> 'channel_id' end
      where id = (r ->> 'id')::uuid and state = 'sending';
    elsif r ->> 'outcome' = 'retry' then
      update public.discord_posts
      set state = 'retry', error = left(r ->> 'error', 300),
          next_at = now() + make_interval(secs => greatest(coalesce((r ->> 'retry_after_ms')::numeric, 0) / 1000, 5 * attempts))
      where id = (r ->> 'id')::uuid and state = 'sending';
    else
      update public.discord_posts set state = 'failed', error = left(coalesce(r ->> 'error', 'failed'), 300)
      where id = (r ->> 'id')::uuid and state = 'sending';
    end if;
    get diagnostics v_k = row_count; v_n := v_n + v_k;
  end loop;
  return v_n;
