 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_note text := nullif(btrim(coalesce(p_note, '')), ''); v_field text := nullif(btrim(coalesce(p_field, '')), ''); v_who text; v_f public.discord_feeds; v_id uuid;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_event is null or not private.has_event_role(p_event, array['organizer', 'head_marshal', 'marshal', 'scorekeeper', 'medic', 'check_in', 'inspector', 'announcer', 'counter', 'temporary_organizer']) then
    raise exception 'only the staff of this event can alert the staff channel' using errcode = '42501'; end if;
  if p_kind is null or p_kind not in ('medic', 'marshal', 'equipment', 'other') then raise exception 'kind is medic, marshal, equipment or other' using errcode = '22023'; end if;
  if char_length(coalesce(v_note, '')) > 200 then raise exception 'keep the note to 200 characters' using errcode = '22023'; end if;
  if char_length(coalesce(v_field, '')) > 40 then raise exception 'keep the field name short' using errcode = '22023'; end if;
  select * into v_f from public.discord_feeds where event_id = p_event;
  if not found or not v_f.enabled or not v_f.staff_alerts then raise exception 'Staff alerts are off for this event' using errcode = 'P0001'; end if;
  if exists (select 1 from public.discord_staff_alerts a where a.created_by = auth.uid() and a.created_at > clock_timestamp() - interval '20 seconds') then
    raise exception 'one alert every 20 seconds; the staff saw the last one' using errcode = 'P0001'; end if;
  v_who := coalesce((select p.display_name from public.profiles p where p.id = auth.uid()),
                    (select c.label from public.event_sessions s join public.event_credentials c on c.id = s.credential_id where s.id = auth.uid()),
                    'event staff');
  insert into public.discord_staff_alerts (event_id, kind, field, note, created_by) values (p_event, p_kind, v_field, v_note, auth.uid()) returning id into v_id;
  perform private.discord_enqueue(p_event, 'staff_alert', null, 'staff_alert:' || v_id::text,
    private.discord_event_base(p_event) || jsonb_build_object('alert', p_kind, 'field', v_field, 'note', v_note, 'by', left(v_who, 80),
      'role_names', case p_kind when 'medic' then jsonb_build_array('Organizer', 'Marshal') when 'marshal' then jsonb_build_array('Marshal') else jsonb_build_array('Organizer') end));
  perform private.audit(p_event, 'discord.staff_alert', v_id::text, jsonb_build_object('kind', p_kind, 'field', v_field));
  return jsonb_build_object('queued', true, 'id', v_id);
end $function$
;$bos$, $bos$drop function if exists public.discord_staff_alert(p_event uuid, p_kind text, p_field text, p_note text);$bos$);
