  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  select * into v from public.discord_volunteers where id = p_id;
  if not found or not private.is_organizer(v.event_id) then raise exception 'only an organizer of this event can decide' using errcode = '42501'; end if;
  if p_accept is null then raise exception 'say yes or no' using errcode = '22023'; end if;
  update public.discord_volunteers set state = case when p_accept then 'accepted' else 'declined' end, decided_by = auth.uid(), decided_at = now() where id = p_id;
  if p_accept and v.user_id is not null and v.role in ('marshal', 'check_in') then
    insert into public.event_staff (event_id, user_id, role) values (v.event_id, v.user_id, v.role) on conflict do nothing;
    v_staff := found;
  end if;
  perform private.audit(v.event_id, 'discord.volunteer_' || case when p_accept then 'accepted' else 'declined' end, p_id::text,
    jsonb_build_object('role', v.role, 'staff_added', v_staff));
  return public.discord_volunteers_list(v.event_id) ;
end $function$
