 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event uuid;
  v_parts text[] := coalesce(p_parts, array['event', 'detail']);
  v_comps uuid[];
  v_ev jsonb; v_list jsonb; v_detail jsonb; v_lyst jsonb; v_scores jsonb;
  v_hashes jsonb := '{}'::jsonb; v_h text;
begin
  if p_event is null or btrim(p_event) = '' then return null; end if;
  if p_event ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select e.id into v_event from public.events e where e.id = p_event::uuid;
  else
    select e.id into v_event from public.events e where e.slug = p_event;
  end if;
  -- the same rule as events_read / competitions_read / entries_read / matches_read: nothing at all for an event the caller may not see
  if v_event is null or not (private.is_event_public(v_event) or private.can_score(v_event)) then return null; end if;

  if 'event' = any (v_parts) then
    select jsonb_build_object(
      'id', e.id, 'slug', e.slug, 'name', e.name, 'description', e.description, 'event_type', e.event_type, 'status', e.status,
      'venue', e.venue, 'address', e.address, 'city', e.city, 'region', e.region, 'country', e.country, 'latitude', e.latitude, 'longitude', e.longitude,
      'starts_on', e.starts_on, 'ends_on', e.ends_on, 'timezone', e.timezone,
      'fee_cents', e.fee_cents, 'fee_province', e.fee_province, 'fee_note', e.fee_note,
      'registration_opens_at', e.registration_opens_at, 'registration_closes_at', e.registration_closes_at, 'registration_mode', e.registration_mode,
      'external_url', e.external_url, 'time_note', e.time_note, 'volunteer_info', e.volunteer_info,
      'organization_id', e.organization_id, 'season_id', e.season_id, 'closed_at', e.closed_at, 'reopened_at', e.reopened_at,
      'archived_at', e.archived_at, 'stats_excluded_at', e.stats_excluded_at, 'stats_excluded_reason', e.stats_excluded_reason, 'field_count', e.field_count,
      'public_contact', e.public_contact,
      'synthetic', private.is_synthetic('event', e.id),
      -- the event's organization is its own, else its season's (the rule fetchEventMetaById and the rankings use)
      'organization', (select jsonb_build_object('id', o.id, 'slug', o.slug, 'name', o.name, 'short_name', o.short_name, 'enabled', o.enabled)
                       from public.organizations o where o.id = coalesce(e.organization_id, (select s.organization_id from public.seasons s where s.id = e.season_id))),
      'season', (select jsonb_build_object('id', s.id, 'slug', s.slug, 'name', s.name) from public.seasons s where s.id = e.season_id),
      'stream', case when private.is_event_public(e.id) or private.is_organizer(e.id) then
                  (select jsonb_build_object('url', b.stream_url, 'title', b.stream_title, 'corners', b.corners) from public.event_broadcast b where b.event_id = e.id and b.stream_url is not null) end)
    into v_ev from public.events e where e.id = v_event;

    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'name', c.name, 'category', c.category, 'gender', c.gender, 'ruleset', c.ruleset, 'status', c.status, 'sort', c.sort,
      'finalized_at', c.finalized_at, 'reopened_at', c.reopened_at, 'structure', c.structure, 'league', rc.league, 'rounds_to_win', c.rounds_to_win,
      'entries', (select count(*) from public.entries x where x.competition_id = c.id and x.status <> 'withdrawn'),
      'matches', (select count(*) from public.matches m where m.competition_id = c.id),
      'finals', (select count(*) from public.matches m where m.competition_id = c.id and m.queue_state = 'final'),
      'rules', (select jsonb_build_object('slug', r.slug, 'name', r.name, 'version', v.version, 'version_id', v.id)
                from public.ruleset_versions v join public.rulesets r on r.id = v.ruleset_id
                where v.id = c.ruleset_version_id and private.rule_version_readable(v.id)))
      order by c.sort, c.name, c.id), '[]'::jsonb)
    into v_list
    from public.competitions c left join public.ref_categories rc on rc.code = c.category
    where c.event_id = v_event;

    -- unchanged since the caller's last read (it sent the hash it holds): say so instead of sending it again
    v_h := left(md5(v_ev::text || v_list::text), 16);
    v_hashes := v_hashes || jsonb_build_object('event', v_h);
    if p_known ->> 'event' = v_h then v_ev := null; v_list := null; end if;
  end if;

  if 'detail' = any (v_parts) then
    v_comps := array(select c.id from public.competitions c where c.event_id = v_event and (p_competitions is null or c.id = any (p_competitions)) order by c.sort, c.id);
    with ent as materialized (
      select e.id, e.competition_id, e.team_id, e.fighter_id, e.pool, e.seed, e.status, e.created_at,
             case when e.team_id is not null then
                    (case when t.status = 'approved' then t.name when private.is_team_captain(t.id) or private.can_admin_team(t.id) then t.name end)
                  else f.display_name end as name
      from public.entries e left join public.teams t on t.id = e.team_id left join public.fighters f on f.id = e.fighter_id
      where e.competition_id = any (v_comps)),
    mat as materialized (select m.* from public.matches m where m.competition_id = any (v_comps)),
    -- competition_standings, exactly: final pool and round-robin matches of each entry
    st as materialized (
      select e.competition_id, e.id as entry_id,
             count(m.id) filter (where m.winner_entry_id = e.id) as wins,
             count(m.id) filter (where m.winner_entry_id is not null and m.winner_entry_id <> e.id) as losses,
             count(m.id) filter (where m.result = 'draw') as draws,
             coalesce(sum(case when m.entry_a = e.id then m.score_a else m.score_b end), 0) as score_for,
             coalesce(sum(case when m.entry_a = e.id then m.score_b else m.score_a end), 0) as score_against
      from ent e
      left join mat m on m.competition_id = e.competition_id and m.queue_state = 'final' and m.stage in ('pool', 'round_robin') and (m.entry_a = e.id or m.entry_b = e.id)
      group by e.competition_id, e.id),
    -- the database ranking pool_standings shows (private.group_ranks), once per competition that has a FINISHED pool or round-robin match
    -- (before the first result there is nothing to rank, and group_ranks answers nothing)
    rk as materialized (
      select c.id as competition_id, g.part, g.ent, g.wrank, g.tied
      from public.competitions c cross join lateral private.group_ranks(c.id) g
      where c.id = any (v_comps) and exists (select 1 from mat x where x.competition_id = c.id and x.stage in ('pool', 'round_robin') and x.queue_state = 'final')),
    per as (
      select c.cid, jsonb_build_object(
        'entries', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', e.id, 'competition_id', e.competition_id, 'team_id', e.team_id, 'fighter_id', e.fighter_id,
                     'pool', e.pool, 'seed', e.seed, 'status', e.status, 'name', e.name)) order by e.created_at, e.id) from ent e where e.competition_id = c.cid), '[]'::jsonb),
        'matches', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                     'id', m.id, 'competition_id', m.competition_id, 'stage', m.stage, 'round_label', m.round_label, 'position', m.position, 'pool', m.pool, 'field', m.field,
                     'scheduled_at', m.scheduled_at, 'queue_state', m.queue_state, 'entry_a', m.entry_a, 'entry_b', m.entry_b, 'next_match_id', m.next_match_id, 'next_slot', m.next_slot,
                     'result', m.result, 'winner_entry_id', m.winner_entry_id, 'score_a', m.score_a, 'score_b', m.score_b, 'detail', nullif(m.detail, '{}'::jsonb), 'version', m.version,
                     'finalized_at', m.finalized_at, 'queue_order', m.queue_order, 'plan_order', m.plan_order, 'plan_hold', nullif(m.plan_hold, false),
                     'name_a', a.name, 'name_b', b.name)) order by m.stage, m.position, m.id)
                   from mat m left join ent a on a.id = m.entry_a left join ent b on b.id = m.entry_b where m.competition_id = c.cid), '[]'::jsonb),
        'standings', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('entry_id', s.entry_id, 'wins', s.wins, 'losses', s.losses, 'draws', s.draws,
                     'score_for', s.score_for, 'score_against', s.score_against, 'rank', r.wrank, 'tied', r.tied)) order by s.entry_id)
                   from st s left join lateral (select k.wrank, k.tied from rk k where k.competition_id = s.competition_id and k.ent = s.entry_id order by k.part desc, k.wrank desc limit 1) r on true
                   where s.competition_id = c.cid), '[]'::jsonb)) as body
      from unnest(v_comps) as c(cid)),
    hashed as (select p.cid, p.body, left(md5(p.body::text), 16) as h from per p)
    select coalesce(jsonb_object_agg(x.cid::text, x.body) filter (where x.h is distinct from (p_known ->> x.cid::text)), '{}'::jsonb),
           v_hashes || coalesce(jsonb_object_agg(x.cid::text, x.h), '{}'::jsonb)
    into v_detail, v_hashes
    from hashed x;
  end if;

  if 'lyst' = any (v_parts) then
    select coalesce(jsonb_agg(to_jsonb(l) - 'server_now' order by l.field_key, l.match_id), '[]'::jsonb) into v_lyst
    from public.lyst_public_state l where l.event_id = v_event;
    select coalesce(jsonb_agg(jsonb_build_object('match_id', s.match_id, 'competition_id', s.competition_id, 'score_a', s.score_a, 'score_b', s.score_b,
             'phase', s.phase, 'detail', s.detail, 'updated_at', s.updated_at) order by s.match_id), '[]'::jsonb) into v_scores
    from public.match_live_scores s join public.competitions k on k.id = s.competition_id where k.event_id = v_event;
  end if;

  -- A part (or a competition's detail) the caller asked for but that is missing from the answer is unchanged: its hash matched p_known.
  return jsonb_build_object('v', 1, 'server_now', clock_timestamp(), 'event_id', v_event, 'parts', to_jsonb(v_parts),
    'event', v_ev, 'competitions', v_list, 'detail_ids', to_jsonb(v_comps), 'detail', v_detail, 'hashes', v_hashes, 'lyst', v_lyst, 'scores', v_scores);
end $function$
;$bos$, $bos$drop function if exists public.event_board(p_event text, p_parts text[], p_competitions uuid[], p_known jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'event_sides' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.event_sides(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_event is null or not (private.is_event_public(p_event) or private.can_score(p_event)) then return null; end if;
  return private.event_sides(p_event);
end $function$
;$bos$, $bos$drop function if exists public.event_sides(p_event uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'fighter_career' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.fighter_career(p_fighter uuid)
 RETURNS TABLE(context text, scope text, season_id uuid, organization_id uuid, kind text, category text, category_name text, gender text, events integer, competitions integer, matches integer, wins integer, losses integer, draws integer, win_pct numeric, golds integer, silvers integer, bronzes integer, podiums integer, points numeric, best_place integer, first_on date, last_on date)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with facts as (
    select case when f.synthetic then 'test' else 'official' end as ctx, f.season_id, f.organization_id, f.kind, f.category, f.category_name, f.gender,
      f.event_id, null::uuid as result_comp, f.match_id, f.outcome, null::int as place, null::numeric as pts, f.event_ends_on
    from private.career_fight_rows(p_fighter) f where not f.stats_excluded
    union all
    select case when r.synthetic then 'test' else 'official' end, r.season_id, r.organization_id, r.kind, r.category, r.category_name, r.gender,
      r.event_id, r.competition_id, null, null, r.final_place, r.points, r.event_ends_on
    from private.career_result_rows(p_fighter) r where not r.stats_excluded
  ), agg as (
    select ctx, season_id, organization_id, kind, category, category_name, gender,
      grouping(season_id) as gs, grouping(organization_id) as go,
      count(distinct event_id) as events, count(distinct result_comp) as competitions,
      count(match_id) as matches, count(match_id) filter (where outcome = 'win') as wins, count(match_id) filter (where outcome = 'loss') as losses,
      count(match_id) filter (where outcome = 'draw') as draws,
      count(place) filter (where place = 1) as golds, count(place) filter (where place = 2) as silvers, count(place) filter (where place = 3) as bronzes,
      coalesce(sum(pts), 0) as points, min(place) as best_place, min(event_ends_on) as first_on, max(event_ends_on) as last_on
    from facts
    group by grouping sets ((ctx), (ctx, season_id), (ctx, organization_id), (ctx, kind, category, category_name, gender),
      (ctx, season_id, kind, category, category_name, gender), (ctx, organization_id, kind, category, category_name, gender))
  )
  select ctx, case when gs = 0 then 'season' when go = 0 then 'organization' else 'career' end, season_id, organization_id, kind, category, category_name, gender,
    events::int, competitions::int, matches::int, wins::int, losses::int, draws::int,
    case when matches = 0 then null else round(wins * 100.0 / matches, 1) end,
    golds::int, silvers::int, bronzes::int, (golds + silvers + bronzes)::int, points, best_place, first_on, last_on
  from agg
  where not (gs = 0 and season_id is null) and not (go = 0 and organization_id is null)
$function$
;$bos$, $bos$drop function if exists public.fighter_career(p_fighter uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'fighter_head_to_head' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.fighter_head_to_head(p_fighter uuid)
 RETURNS TABLE(context text, opponent_fighter_id uuid, opponent_name text, category text, category_name text, gender text, meetings integer, wins integer, losses integer, draws integer, last_on date)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case when f.synthetic then 'test' else 'official' end, f.opponent_fighter_id, max(f.opponent_name), f.category, f.category_name, f.gender,
    count(*)::int, count(*) filter (where f.outcome = 'win')::int, count(*) filter (where f.outcome = 'loss')::int, count(*) filter (where f.outcome = 'draw')::int,
    max(f.event_ends_on)
  from private.career_fight_rows(p_fighter) f
  where f.kind = 'individual' and f.opponent_fighter_id is not null and not f.stats_excluded
  group by grouping sets ((1, f.opponent_fighter_id), (1, f.opponent_fighter_id, f.category, f.category_name, f.gender))
  order by 1, 7 desc, 3
$function$
;$bos$, $bos$drop function if exists public.fighter_head_to_head(p_fighter uuid);$bos$);
