select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'fighter_profile' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.fighter_profile(p_fighter uuid)
 RETURNS TABLE(fighter_id uuid, display_name text, gender text, birth_year integer, age integer, city text, region text, country text, joined_year integer, disciplines text[], fighting_style text, bio text, highlights text[], team_id uuid, team_name text, team_slug text, team_organization_id uuid, team_organization_slug text, team_organization_name text, team_organization_enabled boolean, avatar_path text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select f.id, f.display_name, f.gender, pv.birth_year,
    case when pv.birth_year is null then null else extract(year from current_date)::int - pv.birth_year end,
    f.city, f.region, f.country, f.joined_year, f.disciplines, f.fighting_style, f.bio, f.highlights,
    t.id, t.name, t.slug, o.id, o.slug, o.name, o.enabled, f.avatar_path
  from public.fighters f
  left join private.fighter_private pv on pv.fighter_id = f.id and (private.is_my_fighter(f.id) or private.is_owner())
  left join public.teams t on t.status = 'approved' and t.id = coalesce(f.team_id, (
    select m.team_id from public.team_memberships m where m.fighter_id = f.id and not m.mercenary and (m.to_date is null or m.to_date >= current_date)
    order by m.from_date desc nulls last, m.id limit 1))
  left join lateral (
    select og.* from public.team_affiliations a join public.organizations og on og.id = a.organization_id
    where a.team_id = t.id and a.relation = 'member' and (a.from_date is null or a.from_date <= current_date) and (a.to_date is null or a.to_date >= current_date)
    order by og.enabled desc, a.from_date nulls last, og.id limit 1) o on true
  where f.id = p_fighter
$function$
;$bos$, $bos$drop function if exists public.fighter_profile(p_fighter uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'fighter_published_cards' and pg_get_function_identity_arguments(p.oid) = $bos$p_fighter uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.fighter_published_cards(p_fighter uuid)
