select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'grant_card_maker' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid, p_email text$bos$), $bos$CREATE OR REPLACE FUNCTION public.grant_card_maker(p_team uuid, p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid;
begin
  if not private.can_manage_card_makers(p_team) then
    raise exception 'only a team captain, the president or secretary, or an admin can add card makers' using errcode = '42501'; end if;
  select id into v_user from auth.users where lower(email) = lower(btrim(coalesce(p_email, '')));
  if v_user is null then raise exception 'that person has not signed in to BuhurtOS yet' using errcode = 'P0002'; end if;
  insert into public.card_makers (team_id, user_id, granted_by) values (p_team, v_user, auth.uid())
  on conflict (team_id, user_id) do update set revoked_at = null, revoked_by = null, granted_by = excluded.granted_by, granted_at = now();
  perform private.audit(null, 'card.maker_added', p_team::text, jsonb_build_object('user', v_user));
  return v_user;
end $function$
;$bos$, $bos$drop function if exists public.grant_card_maker(p_team uuid, p_email text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'label_event_session' and pg_get_function_identity_arguments(p.oid) = $bos$p_session uuid, p_label text$bos$), $bos$CREATE OR REPLACE FUNCTION public.label_event_session(p_session uuid, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_s public.event_sessions; v_c public.event_credentials; v_label text := left(nullif(btrim(coalesce(p_label, '')), ''), 40);
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  perform private.assert_session_alive();
  select s.* into v_s from public.event_sessions s where s.id = p_session for update;
  if not found then raise exception 'session not found' using errcode = 'P0002'; end if;
  select * into v_c from public.event_credentials where id = v_s.credential_id;
  if not (private.is_owner() or private.can_command(v_c.event_id)) then raise exception 'only this event''s organizers, head marshal or secretary can name a phone' using errcode = '42501'; end if;
  update public.event_sessions set label = v_label where id = p_session;
  perform private.audit(v_c.event_id, 'device.labelled', p_session::text, jsonb_build_object('label', v_label, 'previous', v_s.label));
  return private.device_session_row((select s from public.event_sessions s where s.id = p_session), v_c);
end $function$
;$bos$, $bos$drop function if exists public.label_event_session(p_session uuid, p_label text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'list_card_makers' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.list_card_makers(p_team uuid)
 RETURNS jsonb
