 RETURNS TABLE(id uuid, kind text, label text, role text, status text, used boolean, expires_at timestamp with time zone, created_at timestamp with time zone, last_signin_at timestamp with time zone, last_seen_at timestamp with time zone, signed_in_elsewhere_at timestamp with time zone, revoked_at timestamp with time zone, replaced boolean, open_sessions integer, training boolean)
