 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_f uuid; v_new integer := 0; v_n integer; k text;
begin
  if v_uid is null then raise exception 'sign in required' using errcode = '28000'; end if;
  insert into public.melee_packs (user_id, source, source_ref, opened_at, contents) values (v_uid, 'starter', 'starter', now(), '[]'::jsonb)
  on conflict do nothing;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    foreach k in array (private.melee_generic_fighters())[1:6] loop perform private.melee_add(v_uid, k, 2); end loop;
    foreach k in array (private.melee_tactics())[1:4] loop perform private.melee_add(v_uid, k, 2); end loop;
    v_new := v_new + 1;
  end if;
  insert into public.melee_packs (user_id, source, source_ref) values (v_uid, 'weekly', to_char(now() at time zone 'America/Edmonton', 'IYYY"-W"IW'))
  on conflict do nothing;
  get diagnostics v_n = row_count; v_new := v_new + v_n;
  select fighter_id into v_f from public.fighter_accounts where user_id = v_uid limit 1;
  if v_f is not null then
    insert into public.melee_packs (user_id, source, source_ref)
    select v_uid, 'event', e.id::text from public.events e
    where e.ends_on <= current_date and e.ends_on >= current_date - 730 and not private.is_synthetic('event', e.id)
      and e.id in (select c.event_id from public.competitions c
                   where c.id in (select ef.competition_id from public.entry_fighters ef where ef.fighter_id = v_f)
                      or c.id in (select en.competition_id from public.entries en where en.fighter_id = v_f))
    on conflict do nothing;
    get diagnostics v_n = row_count; v_new := v_new + v_n;
  end if;
  return jsonb_build_object('new_packs', v_new);
end $function$
;$bos$, $bos$drop function if exists public.melee_claim();$bos$);
