 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_pack public.melee_packs; v_out jsonb := '[]'::jsonb; v_key text; i integer; v_pool uuid[];
begin
  select * into v_pack from public.melee_packs where id = p_id and user_id = v_uid for update;
  if v_pack.id is null then raise exception 'pack not found' using errcode = 'P0002'; end if;
  if v_pack.opened_at is not null then return coalesce(v_pack.contents, '[]'::jsonb); end if;
  select array_agg(id) into v_pool from public.cards where status = 'published' and game_use and game_stats is not null;
  for i in 1..3 loop
    if v_pool is not null and random() < 0.55 then
      v_key := 'c:' || v_pool[1 + floor(random() * array_length(v_pool, 1))::int];
    else
      v_key := (private.melee_generic_fighters())[1 + floor(random() * 10)::int];
    end if;
    perform private.melee_add(v_uid, v_key, 1);
    v_out := v_out || jsonb_build_array(case when v_key like 'c:%' then private.melee_card_json(substr(v_key, 3)::uuid) else jsonb_build_object('key', v_key) end);
  end loop;
  for i in 1..2 loop
    v_key := (private.melee_tactics())[1 + floor(random() * 8)::int];
    perform private.melee_add(v_uid, v_key, 1);
    v_out := v_out || jsonb_build_array(jsonb_build_object('key', v_key));
  end loop;
  update public.melee_packs set opened_at = now(), contents = v_out where id = p_id;
  return v_out;
end $function$
;$bos$, $bos$drop function if exists public.melee_open_pack(p_id uuid);$bos$);
