            order by cr.final_place, cr.entry_id) from public.competition_results cr where cr.competition_id = k.id), '[]'::jsonb),
        'fights', coalesce((select jsonb_agg(jsonb_build_object(
            'id', m.id, 'stage', m.stage, 'round', nullif(m.round_label, ''), 'pool', m.pool, 'field', nullif(btrim(m.field), ''), 'position', m.position,
            'finalized_at', m.finalized_at, 'version', m.version, 'result', m.result, 'winner_entry_id', m.winner_entry_id,
            'a', jsonb_build_object('entry_id', m.entry_a, 'name', private.lyst_side_name(m.entry_a), 'score', m.score_a, 'fighter_id', ea.fighter_id, 'team_id', ea.team_id),
            'b', jsonb_build_object('entry_id', m.entry_b, 'name', private.lyst_side_name(m.entry_b), 'score', m.score_b, 'fighter_id', eb.fighter_id, 'team_id', eb.team_id))
            order by m.stage, m.position, m.finalized_at)
          from public.matches m left join public.entries ea on ea.id = m.entry_a left join public.entries eb on eb.id = m.entry_b
          where m.competition_id = k.id and m.queue_state = 'final' and m.result is not null and m.entry_a is not null and m.entry_b is not null), '[]'::jsonb),
