            order by rv.revision, rv.created_at) from public.result_revisions rv where rv.competition_id = k.id and rv.action <> 'computed'), '[]'::jsonb))
      order by k.sort, k.name) from public.competitions k where k.event_id = e.id and k.status in ('running', 'finished')), '[]'::jsonb));
