 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then raise exception 'only the platform owner can see this' using errcode = '42501'; end if;
  return jsonb_build_object(
    'privacy_open', (select count(*) from public.privacy_requests q where q.closed_at is null),
    'privacy_overdue', (select count(*) from public.privacy_requests q where q.closed_at is null and q.due_at < now()),
    'privacy_due_soon', (select count(*) from public.privacy_requests q where q.closed_at is null and q.due_at >= now() and q.due_at < now() + interval '7 days'),
    'bugs_new', (select count(*) from public.bug_reports b where b.status = 'new'),
    'errors_open', (select count(*) from public.client_error_groups g where g.status = 'open' and g.last_seen > now() - interval '7 days'),
    'errors_new', (select count(*) from public.client_error_groups g where g.first_seen > now() - interval '7 days'),
    'errors_24h', (select coalesce(sum(m.n), 0) from public.client_error_minutes m where m.minute > now() - interval '24 hours'),
    'screenshots_waiting', (select count(*) from public.bug_screenshot_removals q where q.removed_at is null),
    'breaches_open', (select count(*) from public.privacy_breaches b where b.status = 'open'),
    'last_retention_run', (select max(l.ran_at) from public.retention_log l where l.rule = 'run'));
end $function$
;$bos$, $bos$drop function if exists public.platform_attention();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'post_club_notice' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid, p_title text, p_body text, p_pinned boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.post_club_notice(p_team uuid, p_title text, p_body text, p_pinned boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_title text := btrim(coalesce(p_title, '')); v_body text := btrim(coalesce(p_body, ''));
begin
  perform private.club_notice_manage_check(p_team);
  if char_length(v_title) < 3 or char_length(v_title) > 120 then raise exception 'give the notice a short title (3 to 120 characters)' using errcode = '22023'; end if;
  if char_length(v_body) < 1 or char_length(v_body) > 4000 then raise exception 'write the notice (up to 4000 characters)' using errcode = '22023'; end if;
  insert into public.club_notices (team_id, title, body, pinned, posted_by, posted_by_name)
    values (p_team, v_title, v_body, coalesce(p_pinned, false), auth.uid(), coalesce(private.person_name(auth.uid()), 'Executive')) returning id into v_id;
  perform private.audit(null, 'club.notice_posted', v_id::text, jsonb_build_object('team', p_team, 'pinned', coalesce(p_pinned, false)));
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.post_club_notice(p_team uuid, p_title text, p_body text, p_pinned boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'publish_card' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_front text, p_back text$bos$), $bos$CREATE OR REPLACE FUNCTION public.publish_card(p_id uuid, p_front text, p_back text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards; v_code text; v_users uuid[]; v_team text;
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not private.can_make_cards(v_row.team_id) then raise exception 'you cannot publish this card' using errcode = '42501'; end if;
  if v_row.status = 'published' then raise exception 'this card is already published' using errcode = '55000'; end if;
  if v_row.fighter_id is not null and v_row.status <> 'approved' then
    raise exception 'the fighter has to approve this card before it is published' using errcode = '42501'; end if;
  if v_row.fighter_id is null and v_row.kind = 'fighter' then
    raise exception 'link this card to the fighter''s BuhurtOS profile and get their approval first' using errcode = '42501'; end if;
  if v_row.fighter_id is null and v_row.status not in ('draft', 'approved') then raise exception 'this card cannot be published now' using errcode = '55000'; end if;
  if p_front is null or split_part(p_front, '/', 1) <> v_row.team_id::text or split_part(p_front, '/', 2) <> v_row.id::text
     or not exists (select 1 from storage.objects o where o.bucket_id = 'card-published' and o.name = p_front) then
    raise exception 'upload the card front first' using errcode = '22023'; end if;
  if p_back is not null and (split_part(p_back, '/', 2) <> v_row.id::text
     or not exists (select 1 from storage.objects o where o.bucket_id = 'card-published' and o.name = p_back)) then
    raise exception 'upload the card back first' using errcode = '22023'; end if;
  v_code := coalesce(v_row.verify_code, private.card_new_code());
  update public.cards set status = 'published', front_path = p_front, back_path = p_back, verify_code = v_code,
         published_at = now(), updated_by = auth.uid(), updated_at = now() where id = p_id;
  if v_row.fighter_id is not null then
    select name into v_team from public.teams where id = v_row.team_id;
    select array_agg(user_id) into v_users from public.fighter_accounts where fighter_id = v_row.fighter_id;
    if v_users is not null and private.card_notifications_ready() then
      insert into public.notifications (user_id, kind, payload, route, dedupe_key)
      select u, 'card_published', jsonb_build_object('card_id', p_id, 'team_name', v_team, 'code', v_code),
             '/fighters/' || v_row.fighter_id::text, 'card_published:' || p_id::text
      from unnest(v_users) u;
    end if;
  end if;
  perform private.audit(null, 'card.published', v_row.team_id::text, jsonb_build_object('card', p_id, 'code', v_code));
  return jsonb_build_object('status', 'published', 'verify_code', v_code);
end $function$
;$bos$, $bos$drop function if exists public.publish_card(p_id uuid, p_front text, p_back text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'push_report' and pg_get_function_identity_arguments(p.oid) = $bos$p_results jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.push_report(p_results jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; v_n integer := 0; v_state text;
begin
  for r in select (x ->> 'notification_id')::uuid as nid, (x ->> 'subscription_id')::uuid as sid, x ->> 'outcome' as outcome, left(x ->> 'error', 200) as err
           from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) x loop
    v_state := case r.outcome when 'sent' then 'sent' when 'gone' then 'gone' when 'retry' then 'retry' else 'failed' end;
    update public.push_deliveries d set
      state = case when v_state = 'retry' and d.attempts >= 4 then 'failed' else v_state end, last_error = r.err, updated_at = now()
    where d.notification_id = r.nid and d.subscription_id = r.sid;
    if v_state = 'sent' then
      update public.push_subscriptions set last_success_at = now(), failure_count = 0 where id = r.sid;
    elsif v_state = 'gone' then
      perform private.revoke_subscription(r.sid);
    elsif v_state in ('failed', 'retry') then
      update public.push_subscriptions set failure_count = failure_count + 1 where id = r.sid;
      if (select failure_count from public.push_subscriptions where id = r.sid) >= 12 then perform private.revoke_subscription(r.sid); end if;
    end if;
    v_n := v_n + 1;
  end loop;
  update public.notifications n set push_state = 'done'
  where n.push_state = 'pending'
    and exists (select 1 from public.push_deliveries d where d.notification_id = n.id)
    and not exists (select 1 from public.push_deliveries d where d.notification_id = n.id and d.state in ('sending', 'retry'));
  return v_n;
end $function$
;$bos$, $bos$drop function if exists public.push_report(p_results jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'reavers_public_voting_board_rows' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION public.reavers_public_voting_board_rows()
 RETURNS TABLE(full_name text, eligible boolean, reasons text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with mt as (
    select cm.id, cm.team_id, cm.membership_year
    from public.club_meetings cm
    join public.teams t on t.id = cm.team_id
    where t.slug = 'red-deer-reavers'
    order by cm.starts_at desc
    limit 1
  )
  select m.full_name, c.eligible, c.reasons
  from mt
  join public.club_memberships m
    on m.team_id = mt.team_id
   and m.membership_year = mt.membership_year
  cross join lateral private.club_vote_check(m.id, private.club_meeting_day(mt.id)) c
  where m.status = 'active'
  order by lower(m.full_name), m.id;
$function$
;$bos$, $bos$drop function if exists public.reavers_public_voting_board_rows();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'record_age_check' and pg_get_function_identity_arguments(p.oid) = $bos$p_reg uuid, p_checked boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.record_age_check(p_reg uuid, p_checked boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r public.registrations; v_at timestamptz := clock_timestamp(); v_device boolean; v_label text;
begin
  v_r := private.desk_registration(p_reg);
  if not private.can_check_in(v_r.event_id) then raise exception 'only the check-in desk, the head marshal or an organizer of this event can record an age check' using errcode = '42501'; end if;
  if p_checked is null then raise exception 'say whether the age was checked' using errcode = '22023'; end if;
  if v_r.status <> 'accepted' then raise exception 'only an accepted registration can be checked at the desk' using errcode = '22023'; end if;
  if (v_r.age_checked_at is not null) = p_checked then return jsonb_build_object('checked', p_checked, 'changed', false, 'checked_at', v_r.age_checked_at); end if;
  v_device := private.is_device();
  if v_device then select left(coalesce(nullif(btrim(d.label), ''), 'Event device'), 80) into v_label from private.device_ctx() d limit 1; end if;
  insert into public.registration_age_checks (registration_id, event_id, checked, checked_by, device_label, checked_at)
  values (p_reg, v_r.event_id, p_checked, case when v_device then null else auth.uid() end, case when v_device then coalesce(v_label, 'Event device') end, v_at);
  update public.registrations set age_checked_at = case when p_checked then v_at end where id = p_reg;
  perform private.audit(v_r.event_id, case when p_checked then 'checkin.age_checked' else 'checkin.age_check_undone' end, p_reg::text);
  return jsonb_build_object('checked', p_checked, 'changed', true, 'checked_at', case when p_checked then v_at end);
end $function$
;$bos$, $bos$drop function if exists public.record_age_check(p_reg uuid, p_checked boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'record_card_consent_in_person' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_game_use boolean, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.record_card_consent_in_person(p_id uuid, p_game_use boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards; v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not private.can_make_cards(v_row.team_id) then
    raise exception 'only the Card Forge owners can record in-person consent' using errcode = '42501'; end if;
  if v_row.status = 'published' then raise exception 'this card is already published' using errcode = '55000'; end if;
  if v_note is null or char_length(v_note) < 8 then raise exception 'say how consent was given (for example: signed form, 9 Oct 2026)' using errcode = '22023'; end if;
  update public.cards set status = 'approved', game_use = false, updated_by = auth.uid(), updated_at = now() where id = p_id;
  insert into public.card_consents (card_id, fighter_id, decided_by, decision, game_use, note)
  values (p_id, v_row.fighter_id, auth.uid(), 'in_person', false, left(v_note, 300));
  perform private.audit(null, 'card.consent_in_person', v_row.team_id::text, jsonb_build_object('card', p_id));
  return jsonb_build_object('status', 'approved');
end $function$
;$bos$, $bos$drop function if exists public.record_card_consent_in_person(p_id uuid, p_game_use boolean, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'record_client_error' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.record_client_error(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text; v_msg text; v_stack text; v_file text; v_key text; v_release text; v_route text; v_client uuid;
  v_uid uuid := auth.uid(); v_person boolean := false; v_event uuid; v_role text; v_mode text;
  v_minute timestamptz := date_trunc('minute', now()); v_calls int; v_new boolean := false; v_back boolean := false;
  g public.client_error_groups; v_recent int;
begin
  if p is null or jsonb_typeof(p) <> 'object' then return; end if;
  -- flood guard first: count the call, and stop doing anything else once a minute is far past normal
  insert into public.client_error_minutes as m (minute, n) values (v_minute, 1)
  on conflict (minute) do update set n = m.n + 1 returning m.n into v_calls;
  if v_calls > 3000 then return; end if;

  v_kind := case when p ->> 'kind' in ('error', 'unhandledrejection', 'react') then p ->> 'kind' else 'error' end;
  v_msg := coalesce(private.scrub_diag(p ->> 'message', 300), '(no message)');
  v_stack := private.scrub_diag(array_to_string((string_to_array(left(coalesce(p ->> 'stack', ''), 6000), E'\n'))[1:12], E'\n'), 2000);
  v_file := private.scrub_diag(p ->> 'source_file', 200);
  v_release := left(nullif(btrim(coalesce(p ->> 'release', '')), ''), 120);
  v_route := private.scrub_route(p ->> 'route');
  v_client := case when (p ->> 'client_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (p ->> 'client_id')::uuid end;
  -- who is calling: a person (signed in or not) or an event device. Never stored: the account id.
  if v_uid is not null then
    v_person := exists (select 1 from auth.users u where u.id = v_uid);
    if not v_person then select d.event_id, d.role into v_event, v_role from private.device_ctx() d limit 1; end if;
  end if;
  v_mode := case when v_event is not null or (v_uid is not null and not v_person) or p ->> 'device_mode' = 'device' then 'device' else 'person' end;
  if v_client is not null and (select count(*) from public.client_errors e where e.client_id = v_client and e.at > now() - interval '10 minutes') >= 30 then return; end if;

  v_key := private.client_error_key(v_kind, v_msg, v_file);
  insert into public.client_error_groups as cg (group_key, kind, message, source_file, occurrences, first_release, last_release)
  values (v_key, v_kind, v_msg, v_file, 1, v_release, v_release)
  on conflict (group_key) do nothing
  returning * into g;
  if found then
    v_new := true;
  else
    select cg.status = 'resolved' into v_back from public.client_error_groups cg where cg.group_key = v_key for update;
    v_back := coalesce(v_back, false);
    update public.client_error_groups cg set occurrences = cg.occurrences + 1, last_seen = now(), last_release = coalesce(v_release, cg.last_release),
      status = case when v_back then 'open' else cg.status end,
      reopened_at = case when v_back then now() else cg.reopened_at end
    where cg.group_key = v_key;
  end if;

  -- a sample, unless this kind already has plenty this hour or everything has plenty in these 10 minutes
  select count(*) into v_recent from public.client_errors e where e.group_key = v_key and e.at > now() - interval '1 hour';
  if v_recent < 20 and (select count(*) from public.client_errors e where e.at > now() - interval '10 minutes') < 500 then
    insert into public.client_errors (group_key, kind, release, route, device_mode, event_id, device_role, signed_in, message, stack, browser, os, device_class, installed, client_id)
    values (v_key, v_kind, v_release, v_route, v_mode, v_event, left(v_role, 40), v_person, v_msg, v_stack,
            left(nullif(p ->> 'browser', ''), 40), left(nullif(p ->> 'os', ''), 40),
            case when p ->> 'device_class' in ('phone', 'tablet', 'desktop') then p ->> 'device_class' end,
            case when jsonb_typeof(p -> 'installed') = 'boolean' then (p ->> 'installed')::boolean end, v_client);
  end if;

  -- owner alerts, throttled
  if v_new or v_back then
    update public.client_error_alert_state set last_new_at = now() where id = 1 and (last_new_at is null or last_new_at < now() - interval '15 minutes');
    if found then
      perform private.client_error_alert(jsonb_build_object('stage', case when v_back then 'back' else 'new' end, 'group', v_key,
        'message', left(v_msg, 100), 'route', v_route, 'release', v_release, 'device_mode', v_mode));
    end if;
  end if;
  if (select coalesce(sum(m.n), 0) from public.client_error_minutes m where m.minute > now() - interval '10 minutes') >= 50 then
    update public.client_error_alert_state set last_spike_at = now() where id = 1 and (last_spike_at is null or last_spike_at < now() - interval '1 hour');
    if found then
      perform private.client_error_alert(jsonb_build_object('stage', 'spike',
        'count', (select coalesce(sum(m.n), 0) from public.client_error_minutes m where m.minute > now() - interval '10 minutes')));
    end if;
  end if;
end $function$
;$bos$, $bos$drop function if exists public.record_client_error(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'record_privacy_breach' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.record_privacy_breach(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f jsonb; v_id uuid;
begin
  if not private.is_owner() then raise exception 'only the platform owner keeps the breach register' using errcode = '42501'; end if;
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'send the breach as an object' using errcode = '22023'; end if;
  f := private.breach_fields(p);
  if char_length(coalesce(f ->> 'summary', '')) < 10 then raise exception 'describe what happened in at least a sentence' using errcode = '22023'; end if;
  insert into public.privacy_breaches (recorded_by, discovered_at, occurred_at, summary, data_involved, people_affected, risk, risk_reasoning, containment,
                                       oipc_notified_at, opc_notified_at, individuals_notified_at)
  values (auth.uid(), coalesce((f ->> 'discovered_at')::timestamptz, now()), (f ->> 'occurred_at')::timestamptz, f ->> 'summary', f ->> 'data_involved',
          f ->> 'people_affected', coalesce(f ->> 'risk', 'not_assessed'), f ->> 'risk_reasoning', f ->> 'containment',
          (f ->> 'oipc_notified_at')::timestamptz, (f ->> 'opc_notified_at')::timestamptz, (f ->> 'individuals_notified_at')::timestamptz)
  returning id into v_id;
  insert into public.privacy_breach_history (breach_id, actor, change, note) values (v_id, auth.uid(), jsonb_build_object('recorded', f), null);
  perform private.audit(null, 'privacy.breach_recorded', v_id::text);
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.record_privacy_breach(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'register_push_device' and pg_get_function_identity_arguments(p.oid) = $bos$p_endpoint text, p_p256dh text, p_auth text, p_label text$bos$), $bos$CREATE OR REPLACE FUNCTION public.register_push_device(p_endpoint text, p_p256dh text, p_auth text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_label text; v_id uuid; v_n integer;
begin
  if v_uid is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_endpoint is null or p_endpoint !~ '^https://[^[:space:]]+$' or char_length(p_endpoint) > 2048 then raise exception 'that device did not give a usable address' using errcode = '22023'; end if;
  if p_p256dh is null or p_p256dh !~ '^[A-Za-z0-9_-]{60,100}$' or p_auth is null or p_auth !~ '^[A-Za-z0-9_-]{16,32}$' then raise exception 'that device did not give usable keys' using errcode = '22023'; end if;
  v_label := left(btrim(regexp_replace(coalesce(p_label, ''), '[[:cntrl:]]', '', 'g')), 40);
  if v_label = '' then v_label := 'This device'; end if;
  select count(*) into v_n from public.push_subscriptions where user_id = v_uid and revoked_at is null and endpoint <> p_endpoint;
  if v_n >= 10 then raise exception 'you already have 10 devices; remove one in Notification settings first' using errcode = '22023'; end if;
  insert into public.push_subscriptions (user_id, endpoint, endpoint_digest, p256dh, auth, label)
  values (v_uid, p_endpoint, encode(sha256(convert_to(p_endpoint, 'UTF8')), 'hex'), p_p256dh, p_auth, v_label)
  on conflict (endpoint) do update set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth, label = excluded.label,
    last_seen_at = now(), failure_count = 0, revoked_at = null
  returning id into v_id;
  insert into public.notification_preferences (user_id) values (v_uid) on conflict (user_id) do nothing;
  return jsonb_build_object('id', v_id);
end $function$
;$bos$, $bos$drop function if exists public.register_push_device(p_endpoint text, p_p256dh text, p_auth text, p_label text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'report_bug' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.report_bug(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_what text; v_session uuid; v_shot text; v_uid uuid := auth.uid(); v_person uuid;
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'send the report as an object' using errcode = '22023'; end if;
  v_what := btrim(coalesce(p ->> 'what', ''));
  if char_length(v_what) < 5 then raise exception 'say in a few words what went wrong' using errcode = '22023'; end if;
  if char_length(v_what) > 2000 then raise exception 'keep it under 2000 characters' using errcode = '22023'; end if;
  v_session := case when (p ->> 'session_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (p ->> 'session_id')::uuid end;
  -- the account behind the report (never an event device's session id, which is not an account)
  v_person := case when v_uid is not null and exists (select 1 from auth.users u where u.id = v_uid) then v_uid end;
  if (select count(*) from public.bug_reports b where b.created_at > now() - interval '1 hour'
        and ((v_session is not null and b.session_id = v_session) or (v_person is not null and b.user_id = v_person))) >= 10 then
    raise exception 'that is a lot of reports in an hour; thank you! try again a little later' using errcode = 'P0001'; end if;
  -- a ceiling on reports from people who are not signed in, all together (a changing visit id cannot get round it)
  if v_person is null and (select count(*) from public.bug_reports b where b.user_id is null and b.created_at > now() - interval '1 hour') >= 60 then
    raise exception 'a lot of reports are arriving right now; please try again in a little while' using errcode = 'P0001'; end if;
  v_shot := nullif(p ->> 'screenshot_path', '');
  if v_shot is not null and v_shot !~ '^reports/[0-9a-f-]{36}\.(jpg|png)$' then v_shot := null; end if;
  insert into public.bug_reports (user_id, session_id, contact, what, expected, path, app_version, user_agent, screen, screenshot_path)
  values (v_person, v_session, left(nullif(btrim(p ->> 'contact'), ''), 200), v_what, left(nullif(btrim(p ->> 'expected'), ''), 2000),
          left(split_part(split_part(coalesce(p ->> 'path', ''), '?', 1), '#', 1), 200), left(p ->> 'app_version', 120), left(p ->> 'user_agent', 400), left(p ->> 'screen', 40), v_shot)
  returning id into v_id;
  insert into public.notifications (user_id, kind, payload)
  select pr.user_id, 'bug_reported', jsonb_build_object('report_id', v_id, 'what', left(v_what, 120), 'path', left(split_part(split_part(coalesce(p ->> 'path', ''), '?', 1), '#', 1), 200))
  from public.platform_roles pr where pr.role = 'owner';
  -- "Privacy: please delete my data" through the bug button is a privacy request too, with the same 30-day clock
  if v_what ~* '^\W*privacy\M' then
    perform private.open_privacy_request(v_person, 'other', v_what, left(nullif(btrim(p ->> 'contact'), ''), 200), 'bug_report', v_id, v_session, now());
  end if;
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.report_bug(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'report_live_score' and pg_get_function_identity_arguments(p.oid) = $bos$p_match uuid, p_device text, p_seq bigint, p_score_a integer, p_score_b integer, p_phase text, p_detail jsonb, p_expected_version integer$bos$), $bos$CREATE OR REPLACE FUNCTION public.report_live_score(p_match uuid, p_device text, p_seq bigint, p_score_a integer, p_score_b integer, p_phase text DEFAULT ''::text, p_detail jsonb DEFAULT '{}'::jsonb, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_m public.matches; v_event uuid; v_old public.match_live_scores;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  -- FOR SHARE: wait for a finish (or any other change of the match) in progress, then read what it committed. Without it a report racing a
  -- finish re-created the running score the finish had just removed.
  select * into v_m from public.matches where id = p_match for share;
  if not found then raise exception 'match not found' using errcode = 'P0002'; end if;
  v_event := private.event_of_match(p_match);
  if not private.can_score(v_event) or not private.can_score_match(p_match) then raise exception 'you cannot score this event' using errcode = '42501'; end if;
  if v_m.queue_state = 'final' then return jsonb_build_object('status', 'final'); end if;
  if p_expected_version is not null and v_m.version <> p_expected_version then return jsonb_build_object('status', 'stale'); end if;
  if p_score_a is null or p_score_b is null or p_score_a < 0 or p_score_b < 0 then raise exception 'scores must be zero or more' using errcode = '22023'; end if;

  select * into v_old from public.match_live_scores where match_id = p_match for update;
  if found and v_old.device = coalesce(p_device, '') and v_old.seq >= coalesce(p_seq, 0) then return jsonb_build_object('status', 'older'); end if;

  insert into public.match_live_scores (match_id, competition_id, score_a, score_b, phase, detail, seq, device, updated_at)
  values (p_match, v_m.competition_id, p_score_a, p_score_b, left(coalesce(p_phase, ''), 80), coalesce(p_detail, '{}'::jsonb), coalesce(p_seq, 0), left(coalesce(p_device, ''), 64), now())
  on conflict (match_id) do update set
    score_a = excluded.score_a, score_b = excluded.score_b, phase = excluded.phase, detail = excluded.detail, seq = excluded.seq, device = excluded.device, updated_at = now();
  return jsonb_build_object('status', 'ok');
end $function$
;$bos$, $bos$drop function if exists public.report_live_score(p_match uuid, p_device text, p_seq bigint, p_score_a integer, p_score_b integer, p_phase text, p_detail jsonb, p_expected_version integer);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'request_card_approval' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_front text, p_back text$bos$), $bos$CREATE OR REPLACE FUNCTION public.request_card_approval(p_id uuid, p_front text, p_back text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards; v_team text; v_fname text; v_users uuid[]; v_maker text;
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not private.can_make_cards(v_row.team_id) then raise exception 'you cannot send this card' using errcode = '42501'; end if;
  if v_row.fighter_id is null then raise exception 'this card has no fighter to approve it' using errcode = '22023'; end if;
  if v_row.status = 'published' then raise exception 'this card is already published' using errcode = '55000'; end if;
  if p_front is null or split_part(p_front, '/', 1) <> v_row.team_id::text or split_part(p_front, '/', 2) <> v_row.id::text
     or not exists (select 1 from storage.objects o where o.bucket_id = 'card-src' and o.name = p_front) then
    raise exception 'upload the card preview first' using errcode = '22023'; end if;
  if p_back is not null and (split_part(p_back, '/', 2) <> v_row.id::text
     or not exists (select 1 from storage.objects o where o.bucket_id = 'card-src' and o.name = p_back)) then
    raise exception 'upload the card back first' using errcode = '22023'; end if;
  update public.cards set status = 'awaiting_approval', review_front = p_front, review_back = p_back, game_use = false,
         updated_by = auth.uid(), updated_at = now() where id = p_id;
  insert into public.card_consents (card_id, fighter_id, decided_by, decision) values (p_id, v_row.fighter_id, auth.uid(), 'requested');
  select name into v_team from public.teams where id = v_row.team_id;
  select display_name into v_fname from public.fighters where id = v_row.fighter_id;
  select display_name into v_maker from public.profiles where id = auth.uid();
  select array_agg(user_id) into v_users from public.fighter_accounts where fighter_id = v_row.fighter_id;
  if v_users is not null and private.card_notifications_ready() then
    insert into public.notifications (user_id, kind, payload, dedupe_key)
    select u, 'card_review', jsonb_build_object('card_id', p_id, 'team_name', v_team, 'fighter_name', v_fname, 'person_name', coalesce(v_maker, 'Your team')),
           'card_review:' || p_id::text || ':' || extract(epoch from now())::bigint
    from unnest(v_users) u;
  end if;
  perform private.audit(null, 'card.approval_requested', v_row.team_id::text, jsonb_build_object('card', p_id, 'fighter', v_row.fighter_id, 'notified', coalesce(array_length(v_users, 1), 0)));
  return jsonb_build_object('status', 'awaiting_approval', 'notified', coalesce(array_length(v_users, 1), 0), 'under_13', private.card_minor(v_row.fighter_id));
end $function$
;$bos$, $bos$drop function if exists public.request_card_approval(p_id uuid, p_front text, p_back text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'request_new_team' and pg_get_function_identity_arguments(p.oid) = $bos$p_payload jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.request_new_team(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); p jsonb := coalesce(p_payload, '{}'::jsonb);
  v_name text; v_slug text; v_city text; v_region text; v_country text; v_desc text; v_site text; v_year int; v_init text; v_div text;
  v_social jsonb := '{}'::jsonb; v_claims text[] := '{}'; v_colors text[]; v_email text; v_phone text; v_reason text; v_notes text;
  v_k text; v_v jsonb; v_c jsonb; v_id uuid;
  c_url constant text := '^https://[^[:space:]/]+\.[^[:space:]/]+([/?#][^[:space:]]*)?$';
begin
  if v_uid is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if jsonb_typeof(p) <> 'object' then raise exception 'send the form as an object' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_object_keys(p) k where k <> all (array['name','slug','city','region','country','description','website','social_links','founded_year',
     'claimed_organizations','colors','crest_division','initial','contact_email','contact_phone','captain_reason','notes'])) then
    raise exception 'the form has a field this version does not know' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_each(p) e where e.key not in ('social_links','claimed_organizations','colors','founded_year') and e.value <> 'null'::jsonb and jsonb_typeof(e.value) <> 'string') then
    raise exception 'text fields must be text' using errcode = '22023'; end if;

  v_name := btrim(coalesce(p ->> 'name', ''));
  if char_length(v_name) not between 2 and 80 then raise exception 'the team name must be 2 to 80 characters' using errcode = '22023'; end if;
  v_slug := btrim(coalesce(nullif(p ->> 'slug', ''), regexp_replace(regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g')));
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(v_slug) > 60 then raise exception 'the team address must be lowercase letters, numbers and dashes' using errcode = '22023'; end if;
  if exists (select 1 from public.teams where slug = v_slug) then raise exception 'that team address is already taken; add your city or a number' using errcode = '22023'; end if;
  v_city := nullif(btrim(coalesce(p ->> 'city', '')), '');
  v_region := nullif(btrim(coalesce(p ->> 'region', '')), '');
  v_country := nullif(btrim(coalesce(p ->> 'country', '')), '');
  if v_city is null or v_country is null then raise exception 'city and country are required' using errcode = '22023'; end if;
  if char_length(v_city) > 80 or char_length(coalesce(v_region, '')) > 80 or char_length(v_country) > 80 then raise exception 'city, region and country are at most 80 characters' using errcode = '22023'; end if;
  v_desc := btrim(coalesce(p ->> 'description', ''));
  if char_length(v_desc) not between 10 and 500 then raise exception 'describe the team in 10 to 500 characters' using errcode = '22023'; end if;
  v_site := nullif(btrim(coalesce(p ->> 'website', '')), '');
  if v_site is not null and (char_length(v_site) > 300 or v_site !~ c_url) then raise exception 'the website must be a full https:// address' using errcode = '22023'; end if;

  if p ? 'founded_year' and p -> 'founded_year' <> 'null'::jsonb then
    if jsonb_typeof(p -> 'founded_year') <> 'number' or (p ->> 'founded_year') !~ '^[0-9]{4}$' then raise exception 'founded year must be a four digit year' using errcode = '22023'; end if;
    v_year := (p ->> 'founded_year')::int;
    if v_year < 1900 or v_year > extract(year from now())::int then raise exception 'founded year must be between 1900 and this year' using errcode = '22023'; end if;
  end if;

  if p ? 'social_links' and p -> 'social_links' <> 'null'::jsonb then
    if jsonb_typeof(p -> 'social_links') <> 'object' then raise exception 'social links must be a list of name and address' using errcode = '22023'; end if;
    if (select count(*) from jsonb_object_keys(p -> 'social_links')) > 8 then raise exception 'at most 8 social links' using errcode = '22023'; end if;
    for v_k, v_v in select key, value from jsonb_each(p -> 'social_links') loop
      if v_k <> all (array['facebook','instagram','youtube','tiktok','x','discord','twitch','other']) then raise exception 'unknown social link: %', left(v_k, 40) using errcode = '22023'; end if;
      if jsonb_typeof(v_v) <> 'string' or char_length(v_v #>> '{}') > 300 or (v_v #>> '{}') !~ c_url then raise exception 'the % link must be a full https:// address', v_k using errcode = '22023'; end if;
      v_social := v_social || jsonb_build_object(v_k, btrim(v_v #>> '{}'));
    end loop;
  end if;

  if p ? 'claimed_organizations' and p -> 'claimed_organizations' <> 'null'::jsonb then
    if jsonb_typeof(p -> 'claimed_organizations') <> 'array' then raise exception 'organizations must be a list' using errcode = '22023'; end if;
    if jsonb_array_length(p -> 'claimed_organizations') > 5 then raise exception 'name at most 5 organizations' using errcode = '22023'; end if;
    for v_c in select value from jsonb_array_elements(p -> 'claimed_organizations') loop
      if jsonb_typeof(v_c) <> 'string' or char_length(btrim(v_c #>> '{}')) not between 2 and 120 then raise exception 'each organization name must be 2 to 120 characters' using errcode = '22023'; end if;
      v_claims := v_claims || btrim(v_c #>> '{}');
    end loop;
  end if;

  v_colors := array['#2C4A8C', '#E9ECEF'];
  if p ? 'colors' and p -> 'colors' <> 'null'::jsonb then
    if jsonb_typeof(p -> 'colors') <> 'array' or jsonb_array_length(p -> 'colors') <> 2
       or exists (select 1 from jsonb_array_elements(p -> 'colors') e where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^#[0-9A-Fa-f]{6}$') then
      raise exception 'colours must be two hex colours like #2C4A8C' using errcode = '22023'; end if;
    select array_agg(e #>> '{}' order by o) into v_colors from jsonb_array_elements(p -> 'colors') with ordinality as x(e, o);
  end if;
  v_div := coalesce(nullif(p ->> 'crest_division', ''), 'pale');
  if v_div not in ('pale', 'fess', 'bend', 'chevron', 'quarterly', 'saltire') then raise exception 'unknown crest pattern' using errcode = '22023'; end if;
  v_init := upper(coalesce(nullif(btrim(p ->> 'initial'), ''), left(v_name, 1)));
  if char_length(v_init) > 2 then raise exception 'the crest initial is one or two letters' using errcode = '22023'; end if;

  v_email := btrim(coalesce(p ->> 'contact_email', ''));
  if char_length(v_email) > 200 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'give a contact email the reviewers can reach you on' using errcode = '22023'; end if;
  v_phone := nullif(btrim(coalesce(p ->> 'contact_phone', '')), '');
  if char_length(coalesce(v_phone, '')) > 40 then raise exception 'the phone number is at most 40 characters' using errcode = '22023'; end if;
  v_reason := btrim(coalesce(p ->> 'captain_reason', ''));
  if char_length(v_reason) not between 10 and 1000 then raise exception 'say in 10 to 1000 characters why you are the captain' using errcode = '22023'; end if;
  v_notes := nullif(btrim(coalesce(p ->> 'notes', '')), '');
  if char_length(coalesce(v_notes, '')) > 2000 then raise exception 'notes are at most 2000 characters' using errcode = '22023'; end if;

  if (select count(*) from public.team_roles r join public.teams t on t.id = r.team_id where r.user_id = v_uid and t.status = 'pending') >= 3 then
    raise exception 'you already have 3 new teams waiting for review' using errcode = '22023'; end if;

  insert into public.teams (slug, name, city, region, country, colors, crest_division, initial, description, website, social_links, founded_year, claimed_organizations)
  values (v_slug, v_name, v_city, v_region, v_country, v_colors, v_div, v_init, v_desc, v_site, v_social, v_year, v_claims)
  returning id into v_id;
  insert into public.team_roles (team_id, user_id, role) values (v_id, v_uid, 'captain');
  insert into public.team_request_private (team_id, requested_by, contact_email, contact_phone, captain_reason, notes) values (v_id, v_uid, v_email, v_phone, v_reason, v_notes);
  insert into public.notifications (user_id, kind, payload)
  select pr.user_id, 'team_proposed', jsonb_build_object('team_id', v_id, 'team_name', v_name, 'team_slug', v_slug)
  from public.platform_roles pr where pr.role = 'owner';
  perform private.audit(null, 'team.proposed', v_slug, jsonb_build_object('team', v_id));
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.request_new_team(p_payload jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'request_team_join' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid, p_message text$bos$), $bos$CREATE OR REPLACE FUNCTION public.request_team_join(p_team uuid, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_team public.teams; v_msg text := nullif(btrim(coalesce(p_message, '')), ''); v_id uuid; v_name text; v_mgr uuid;
begin
  if v_uid is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if v_msg is not null and char_length(v_msg) > 500 then raise exception 'keep your message to 500 characters' using errcode = '22023'; end if;
  select * into v_team from public.teams where id = p_team and status = 'approved';
  if not found then raise exception 'team not found' using errcode = 'P0002'; end if;
  if private.is_team_member(p_team, v_uid) then raise exception 'you are already part of this team' using errcode = '22023'; end if;
  if exists (select 1 from public.team_join_requests where team_id = p_team and requester_id = v_uid and status = 'pending') then
    raise exception 'you already have a request waiting for this team' using errcode = '22023'; end if;
  if (select count(*) from public.team_join_requests where requester_id = v_uid and status = 'pending') >= 5 then
    raise exception 'you have 5 requests waiting; cancel one or wait for an answer' using errcode = '22023'; end if;
  v_name := private.person_name(v_uid);
  if v_name is null then raise exception 'add your name to your profile first, so the captain knows who is asking' using errcode = '22023'; end if;

  insert into public.team_join_requests (team_id, requester_id, message) values (p_team, v_uid, v_msg) returning id into v_id;
  for v_mgr in select private.team_managers(p_team) loop
    insert into public.notifications (user_id, kind, payload)
    values (v_mgr, 'team_join_requested', jsonb_build_object('request_id', v_id, 'team_id', p_team, 'team_name', v_team.name, 'team_slug', v_team.slug, 'requester_name', v_name));
  end loop;
  perform private.audit(null, 'team.join_requested', p_team::text, jsonb_build_object('request', v_id));
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.request_team_join(p_team uuid, p_message text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'reserve_card_code' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.reserve_card_code(p_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards; v_code text;
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not private.can_make_cards(v_row.team_id) then raise exception 'you cannot change this card' using errcode = '42501'; end if;
  if v_row.verify_code is not null then return v_row.verify_code; end if;
  v_code := private.card_new_code();
  update public.cards set verify_code = v_code, updated_at = now() where id = p_id;
  perform private.audit(null, 'card.code_reserved', v_row.team_id::text, jsonb_build_object('card', p_id, 'code', v_code));
  return v_code;
end $function$
;$bos$, $bos$drop function if exists public.reserve_card_code(p_id uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'resolve_fighter_identity_review' and pg_get_function_identity_arguments(p.oid) = $bos$p_review uuid, p_decision text, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.resolve_fighter_identity_review(p_review uuid, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r public.fighter_identity_reviews;
begin
  if not private.is_owner() then raise exception 'only a platform administrator can review fighter identities' using errcode = '42501'; end if;
  if p_decision is null or p_decision not in ('distinct', 'duplicate') then raise exception 'decision must be distinct or duplicate' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'say how this was decided' using errcode = '22023'; end if;
  select * into v_r from public.fighter_identity_reviews where id = p_review for update;
  if not found then raise exception 'review not found' using errcode = 'P0002'; end if;
  if v_r.status <> 'open' then raise exception 'this review was already decided' using errcode = 'P0001'; end if;
  update public.fighter_identity_reviews set status = p_decision, note = btrim(p_note), resolved_by = auth.uid(), resolved_at = now() where id = p_review;
  perform private.audit(null, 'fighter.identity_review_' || p_decision, v_r.fighter_id::text, jsonb_build_object('candidate', v_r.candidate_id, 'note', btrim(p_note)));
end $function$
;$bos$, $bos$drop function if exists public.resolve_fighter_identity_review(p_review uuid, p_decision text, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'revoke_card_maker' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid, p_user uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.revoke_card_maker(p_team uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (private.can_manage_card_makers(p_team) or p_user = auth.uid()) then
    raise exception 'you cannot remove this card maker' using errcode = '42501'; end if;
  update public.card_makers set revoked_at = now(), revoked_by = auth.uid() where team_id = p_team and user_id = p_user and revoked_at is null;
  perform private.audit(null, 'card.maker_removed', p_team::text, jsonb_build_object('user', p_user));
end $function$
;$bos$, $bos$drop function if exists public.revoke_card_maker(p_team uuid, p_user uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'run_retention_now' and pg_get_function_identity_arguments(p.oid) = $bos$$bos$), $bos$CREATE OR REPLACE FUNCTION public.run_retention_now()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then raise exception 'only the platform owner can run the retention rules' using errcode = '42501'; end if;
  perform private.audit(null, 'privacy.retention_run', null);
  return private.run_retention('owner');
end $function$
;$bos$, $bos$drop function if exists public.run_retention_now();$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'save_card' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.save_card(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_team uuid := nullif(p ->> 'team_id', '')::uuid;
  v_fighter uuid := nullif(p ->> 'fighter_id', '')::uuid;
  v_set uuid := nullif(p ->> 'set_id', '')::uuid;
  v_row public.cards;
  v_stats jsonb := case when jsonb_typeof(p -> 'game_stats') = 'object' then p -> 'game_stats' end;
  v_status text;
begin
  if v_id is not null then
    select * into v_row from public.cards where id = v_id for update;
    if v_row.id is null or v_row.discarded_at is not null then raise exception 'card not found' using errcode = 'P0002'; end if;
    v_team := v_row.team_id;
  end if;
  if not private.can_make_cards(v_team) then raise exception 'you cannot make cards for this team' using errcode = '42501'; end if;
  if v_set is not null and not exists (select 1 from public.card_sets s where s.id = v_set and s.team_id = v_team) then
    raise exception 'that set belongs to another team' using errcode = '22023'; end if;
  if not private.card_game_stats_ok(v_stats) then raise exception 'game stats must be 1 to 5 each and add up to 12' using errcode = '22023'; end if;
  if v_id is null then
    insert into public.cards (team_id, set_id, fighter_id, kind, card_no, parallel, serial, short_print, state, photos, game_stats, created_by, updated_by)
    values (v_team, v_set, v_fighter, coalesce(nullif(p ->> 'kind', ''), 'fighter'), nullif(p ->> 'card_no', '')::int,
            coalesce(nullif(p ->> 'parallel', ''), 'base'), nullif(p ->> 'serial', ''), coalesce((p ->> 'short_print')::boolean, false),
            coalesce(p -> 'state', '{}'::jsonb), coalesce(p -> 'photos', '[]'::jsonb), v_stats, auth.uid(), auth.uid())
    returning * into v_row;
    perform private.audit(null, 'card.created', v_team::text, jsonb_build_object('card', v_row.id, 'fighter', v_fighter));
  else
    if v_row.status = 'published' then raise exception 'published cards are locked. Duplicate the card to make a new version.' using errcode = '55000'; end if;
    v_status := case when v_row.status in ('awaiting_approval', 'approved') then 'draft' else v_row.status end;
    update public.cards set set_id = v_set, fighter_id = v_fighter, kind = coalesce(nullif(p ->> 'kind', ''), kind),
        card_no = nullif(p ->> 'card_no', '')::int, parallel = coalesce(nullif(p ->> 'parallel', ''), parallel),
        serial = nullif(p ->> 'serial', ''), short_print = coalesce((p ->> 'short_print')::boolean, short_print),
        state = coalesce(p -> 'state', state), photos = coalesce(p -> 'photos', photos), game_stats = v_stats,
        status = v_status, review_front = case when v_status = 'draft' then null else review_front end,
        review_back = case when v_status = 'draft' then null else review_back end,
        game_use = case when v_status = 'draft' then false else game_use end,
        updated_by = auth.uid(), updated_at = now()
      where id = v_id returning * into v_row;
    perform private.audit(null, 'card.updated', v_team::text, jsonb_build_object('card', v_row.id, 'status', v_row.status));
  end if;
  return jsonb_build_object('id', v_row.id, 'status', v_row.status);
end $function$
;$bos$, $bos$drop function if exists public.save_card(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'save_card_design' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_team uuid, p_name text, p_design jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.save_card_design(p_id uuid, p_team uuid, p_name text, p_design jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_team uuid;
begin
  if p_id is not null then
    select team_id into v_team from public.card_designs where id = p_id and archived_at is null;
    if v_team is null then raise exception 'kit not found' using errcode = 'P0002'; end if;
    if not private.can_make_cards(v_team) then raise exception 'you cannot change this kit' using errcode = '42501'; end if;
    update public.card_designs set name = left(btrim(coalesce(p_name, name)), 80), design = coalesce(p_design, design),
           version = version + 1, updated_by = auth.uid(), updated_at = now() where id = p_id returning id into v_id;
  else
    if not private.can_make_cards(p_team) then raise exception 'you cannot make cards for this team' using errcode = '42501'; end if;
    insert into public.card_designs (team_id, name, design, updated_by)
    values (p_team, left(btrim(coalesce(nullif(btrim(p_name), ''), 'Team kit')), 80), coalesce(p_design, '{}'::jsonb), auth.uid()) returning id into v_id;
    v_team := p_team;
  end if;
  perform private.audit(null, 'card.kit_saved', v_team::text, jsonb_build_object('kit', v_id));
  return v_id;
end $function$
;$bos$, $bos$drop function if exists public.save_card_design(p_id uuid, p_team uuid, p_name text, p_design jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'save_card_set' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_team uuid, p_name text, p_year integer, p_event uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.save_card_set(p_id uuid, p_team uuid, p_name text, p_year integer, p_event uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_team uuid;
begin
  if p_id is not null then
    select team_id into v_team from public.card_sets where id = p_id;
    if v_team is null then raise exception 'set not found' using errcode = 'P0002'; end if;
    if not private.can_make_cards(v_team) then raise exception 'you cannot change this set' using errcode = '42501'; end if;
    update public.card_sets set name = left(btrim(coalesce(nullif(btrim(p_name), ''), name)), 80), year = p_year, event_id = p_event
     where id = p_id returning id into v_id;
  else
    if not private.can_make_cards(p_team) then raise exception 'you cannot make cards for this team' using errcode = '42501'; end if;
    insert into public.card_sets (team_id, name, year, event_id, created_by)
