 SET search_path TO ''
AS $function$
declare v_k public.competitions;
begin
  if p_on is null then raise exception 'say whether to keep teammates apart (on or off)' using errcode = '22023'; end if;
  select * into v_k from public.competitions where id = p_competition for update;
  if not found then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_k.event_id) then
    raise exception 'only an organizer of this event can change how its draws are made' using errcode = '42501';
  end if;
  if v_k.keep_teammates_apart is distinct from p_on then
    -- the competitions guard still applies (a closed event's competitions are history)
    update public.competitions set keep_teammates_apart = p_on where id = p_competition;
    perform private.audit(v_k.event_id, 'draw.keep_apart', p_competition::text, jsonb_build_object('on', p_on, 'was', v_k.keep_teammates_apart));
  end if;
  return p_on;
end $function$
