select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'submit_match_result' and pg_get_function_identity_arguments(p.oid) = $bos$p_command uuid, p_match uuid, p_result text, p_score_a integer, p_score_b integer, p_detail jsonb, p_expected_version integer, p_schema integer$bos$), $bos$CREATE OR REPLACE FUNCTION public.submit_match_result(p_command uuid, p_match uuid, p_result text, p_score_a integer, p_score_b integer, p_detail jsonb, p_expected_version integer, p_schema integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_m public.matches; v_event uuid; v_prop public.result_proposals; v_status text; v_version integer;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_command is null then raise exception 'a command id is required' using errcode = '22023'; end if;
  if not private.command_schema_ok(p_schema) then raise exception 'this app version (command version %) is not supported by the server; reload the page. Your scoring is saved on this device and nothing was changed.', p_schema using errcode = '22023'; end if;

  perform pg_advisory_xact_lock(hashtextextended('bos:result-command:' || p_command::text, 0));
  select * into v_prop from public.result_proposals where id = p_command;
  if found then
    if v_prop.proposed_by <> auth.uid() then raise exception 'that command id belongs to someone else' using errcode = '42501'; end if;
    return jsonb_build_object('status', v_prop.status, 'version', (select version from public.matches where id = v_prop.match_id), 'repeat', true);
  end if;

  select * into v_m from public.matches where id = p_match for update;
  if not found then raise exception 'match not found' using errcode = 'P0002'; end if;
  v_event := private.event_of_match(p_match);
  if not private.can_score(v_event) or not private.can_score_match(p_match) then raise exception 'you cannot score this event' using errcode = '42501'; end if;
  if p_result is null or p_result not in ('a', 'b', 'draw') then raise exception 'result must be a, b or draw' using errcode = '22023'; end if;
  if p_score_a is null or p_score_b is null or p_score_a < 0 or p_score_b < 0 then raise exception 'scores must be zero or more' using errcode = '22023'; end if;
  if p_expected_version is null then raise exception 'the version you opened is required, reload the match' using errcode = '22023'; end if;

  if v_m.queue_state = 'final' then
    if v_m.result = p_result and v_m.score_a = p_score_a and v_m.score_b = p_score_b then
      v_status := 'duplicate';
    else
      v_status := 'conflict';
    end if;
    insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status, official_before)
    values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), v_status,
            jsonb_build_object('result', v_m.result, 'score_a', v_m.score_a, 'score_b', v_m.score_b, 'detail', v_m.detail, 'version', v_m.version, 'finalized_at', v_m.finalized_at));
    if v_status = 'conflict' then
      perform private.audit(v_event, 'result.conflict', p_match::text, jsonb_build_object('proposal', p_command, 'official', v_m.result, 'proposed', p_result));
    end if;
    return jsonb_build_object('status', v_status, 'version', v_m.version);
  end if;

  if v_m.version <> p_expected_version then
    insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status)
    values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), 'stale');
    return jsonb_build_object('status', 'stale', 'version', v_m.version);
  end if;

  v_version := public.finalize_match(p_match, p_result, p_score_a, p_score_b, p_detail, p_expected_version);
  insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status)
  values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), 'accepted');
  return jsonb_build_object('status', 'accepted', 'version', v_version);
end $function$
;$bos$, $bos$drop function if exists public.submit_match_result(p_command uuid, p_match uuid, p_result text, p_score_a integer, p_score_b integer, p_detail jsonb, p_expected_version integer, p_schema integer);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'submit_privacy_request' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.submit_privacy_request(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_type text; v_details text; v_contact text; v_session uuid; r public.privacy_requests;
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'send the request as an object' using errcode = '22023'; end if;
  -- an event device is not a person and cannot ask on anyone's behalf
  if v_uid is not null and not exists (select 1 from auth.users u where u.id = v_uid) then raise exception 'sign in as yourself to make a privacy request' using errcode = '42501'; end if;
  v_type := coalesce(p ->> 'request_type', '');
  if v_type not in ('access', 'correction', 'deletion', 'other') then raise exception 'choose what you are asking for' using errcode = '22023'; end if;
  v_details := btrim(coalesce(p ->> 'details', ''));
  if char_length(v_details) < 5 then raise exception 'say in a few words what you are asking for' using errcode = '22023'; end if;
  if char_length(v_details) > 2000 then raise exception 'keep it under 2000 characters' using errcode = '22023'; end if;
  v_contact := left(nullif(btrim(coalesce(p ->> 'contact', '')), ''), 200);
  if v_uid is null and (v_contact is null or char_length(v_contact) < 5) then
    raise exception 'add an email address or phone number so the answer can reach you' using errcode = '22023'; end if;
  v_session := case when (p ->> 'session_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (p ->> 'session_id')::uuid end;
  -- limits: a few per visit or account, and a ceiling on anonymous requests overall (a flood cannot bury real ones)
  if (v_session is not null and (select count(*) from public.privacy_requests q where q.session_id = v_session and q.received_at > now() - interval '1 hour') >= 3)
     or (v_uid is not null and (select count(*) from public.privacy_requests q where q.user_id = v_uid and q.received_at > now() - interval '1 day') >= 5)
     or (v_uid is null and (select count(*) from public.privacy_requests q where q.user_id is null and q.source = 'form' and q.received_at > now() - interval '1 hour') >= 30) then
    raise exception 'too many requests right now; please try again later' using errcode = 'P0001'; end if;
  r := private.open_privacy_request(v_uid, v_type, v_details, v_contact, 'form', null, v_session, now());
  return jsonb_build_object('id', r.id, 'received_at', r.received_at, 'due_at', r.due_at);
end $function$
;$bos$, $bos$drop function if exists public.submit_privacy_request(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'submit_registration' and pg_get_function_identity_arguments(p.oid) = $bos$p_event uuid, p_data jsonb, p_adult_confirmed boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.submit_registration(p_event uuid, p_data jsonb, p_adult_confirmed boolean DEFAULT NULL::boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.events;
  v_reg uuid;
  v_waiver public.waiver_versions;
  v_comp jsonb;
  v_volunteer boolean := coalesce((p_data ->> 'is_volunteer')::boolean, false);
  v_priv jsonb := coalesce(p_data -> 'private', '{}'::jsonb);
  v_existing public.registrations;
  v_days text[];
  v_dates date[];
  v_roles text[];
  v_my_fighter uuid;
  v_inv public.event_invitations;
  v_age text;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  select * into v_event from public.events where id = p_event;
  if not found or v_event.status <> 'published' then raise exception 'this event is not open for registration' using errcode = 'P0002'; end if;
  -- Under-18s are not taken until a guardian path exists (owner decision default, Pack 28). Asked first, so nobody fills in more to learn it.
  if p_adult_confirmed is false then
    raise exception 'registration is for people 18 or older for now. If you are under 18, please talk to the organizers: BuhurtOS cannot take a parent or guardian''s consent yet' using errcode = '22023';
  end if;
  select fighter_id into v_my_fighter from public.fighter_accounts where user_id = auth.uid();
  if v_my_fighter is not null then
    select * into v_inv from public.event_invitations where event_id = p_event and fighter_id = v_my_fighter and status = 'invited';
  end if;
  if v_inv.id is null then
    if v_event.registration_opens_at is not null and now() < v_event.registration_opens_at then raise exception 'registration has not opened yet' using errcode = '22023'; end if;
    if v_event.registration_closes_at is not null and now() > v_event.registration_closes_at then raise exception 'registration is closed' using errcode = '22023'; end if;
  end if;

  if coalesce((p_data ->> 'waiver_agree')::boolean, false) is not true then raise exception 'the waiver must be accepted to take part' using errcode = '22023'; end if;
  select * into v_waiver from public.waiver_versions where id = (p_data ->> 'waiver_version_id')::uuid and event_id = p_event;
  if not found then raise exception 'unknown waiver version' using errcode = '22023'; end if;
  if v_waiver.version <> (select max(version) from public.waiver_versions where event_id = p_event) then raise exception 'the waiver was updated, please read and accept the new version' using errcode = '22023'; end if;
  if char_length(coalesce(p_data ->> 'waiver_signed_name', '')) < 2 then raise exception 'type your full name to sign the waiver' using errcode = '22023'; end if;

  if (p_data ->> 'insurance') is null or (p_data ->> 'insurance') not in ('hacsa_member', 'mcc_member', 'proof_received', 'proof_pending', 'needs_cover') then
    raise exception 'choose an insurance option' using errcode = '22023'; end if;
  if coalesce((v_priv ->> 'medically_fit')::boolean, false) is not true then raise exception 'you must declare that you are medically fit to take part' using errcode = '22023'; end if;
  if char_length(coalesce(v_priv ->> 'emergency_name', '')) < 2 or char_length(coalesce(v_priv ->> 'emergency_phone', '')) < 7 then raise exception 'emergency contact name and phone are required' using errcode = '22023'; end if;
  if not v_volunteer and jsonb_array_length(coalesce(p_data -> 'competitions', '[]'::jsonb)) = 0 then raise exception 'choose at least one category, or sign up as a volunteer' using errcode = '22023'; end if;

  select * into v_existing from public.registrations where event_id = p_event and user_id = auth.uid();
  if found and v_existing.status not in ('pending', 'declined', 'withdrawn') then raise exception 'your registration was already accepted; ask an organizer to change it' using errcode = '22023'; end if;

  v_days := coalesce(array(select jsonb_array_elements_text(p_data -> 'days')), '{}');
  -- Attendance days are the event's own calendar days; anything outside the event is dropped rather than refused.
  v_dates := coalesce(array(select d::date from jsonb_array_elements_text(p_data -> 'attend_dates') d
                            where d ~ '^\d{4}-\d{2}-\d{2}$' and d::date between v_event.starts_on and v_event.ends_on), '{}');
  v_roles := coalesce(array(select jsonb_array_elements_text(p_data -> 'volunteer_roles')), '{}');

  insert into public.registrations as r (event_id, user_id, status, full_name, gender, organization, province, team_id, team_name, shares_equipment, days, attend_dates, availability_notes,
      bi_profile, insurance, is_volunteer, volunteer_roles, mercenary, notes, fee_due_cents, waiver_version_id, waiver_signed_name, waiver_signed_at, age_status, age_confirmed_at)
  values (p_event, auth.uid(), 'pending', p_data ->> 'full_name', p_data ->> 'gender', p_data ->> 'organization', nullif(p_data ->> 'province', ''),
      nullif(p_data ->> 'team_id', '')::uuid, nullif(p_data ->> 'team_name', ''), coalesce((p_data ->> 'shares_equipment')::boolean, false), v_days, v_dates, nullif(p_data ->> 'availability_notes', ''),
      nullif(p_data ->> 'bi_profile', ''), p_data ->> 'insurance', v_volunteer, v_roles, coalesce((p_data ->> 'mercenary')::boolean, false), nullif(p_data ->> 'notes', ''),
      private.compute_fee(p_event, p_data ->> 'province', v_volunteer), v_waiver.id, p_data ->> 'waiver_signed_name', now(),
      case when p_adult_confirmed then 'confirmed' else 'not_confirmed' end, case when p_adult_confirmed then now() end)
  on conflict (event_id, user_id) do update set status = 'pending', full_name = excluded.full_name, gender = excluded.gender, organization = excluded.organization, province = excluded.province,
      team_id = excluded.team_id, team_name = excluded.team_name, shares_equipment = excluded.shares_equipment, days = excluded.days, attend_dates = excluded.attend_dates, availability_notes = excluded.availability_notes,
      bi_profile = excluded.bi_profile, insurance = excluded.insurance, is_volunteer = excluded.is_volunteer, volunteer_roles = excluded.volunteer_roles, mercenary = excluded.mercenary,
      notes = excluded.notes, fee_due_cents = excluded.fee_due_cents, waiver_version_id = excluded.waiver_version_id, waiver_signed_name = excluded.waiver_signed_name, waiver_signed_at = now(),
      age_status = case when p_adult_confirmed then 'confirmed' else r.age_status end,
      age_confirmed_at = case when p_adult_confirmed then coalesce(r.age_confirmed_at, now()) else r.age_confirmed_at end
  returning r.id, r.age_status into v_reg, v_age;

  insert into public.registration_private as p (registration_id, email, emergency_name, emergency_relationship, emergency_phone, medically_fit, medical_note)
  values (v_reg, coalesce(v_priv ->> 'email', ''), v_priv ->> 'emergency_name', coalesce(v_priv ->> 'emergency_relationship', ''), v_priv ->> 'emergency_phone', true, nullif(v_priv ->> 'medical_note', ''))
  on conflict (registration_id) do update set email = excluded.email, emergency_name = excluded.emergency_name, emergency_relationship = excluded.emergency_relationship,
      emergency_phone = excluded.emergency_phone, medically_fit = true, medical_note = excluded.medical_note;

  delete from public.registration_competitions where registration_id = v_reg;
  for v_comp in select * from jsonb_array_elements(coalesce(p_data -> 'competitions', '[]'::jsonb)) loop
    if not exists (select 1 from public.competitions where id = (v_comp ->> 'competition_id')::uuid and event_id = p_event) then
      raise exception 'a chosen category does not belong to this event' using errcode = '22023'; end if;
    insert into public.registration_competitions (registration_id, competition_id, team_id, details)
    values (v_reg, (v_comp ->> 'competition_id')::uuid, nullif(v_comp ->> 'team_id', '')::uuid, coalesce(v_comp -> 'details', '{}'::jsonb));
  end loop;

  perform private.audit(p_event, 'registration.submitted', v_reg::text,
    jsonb_build_object('age', v_age, 'age_answer', case when p_adult_confirmed then 'yes' else 'not asked' end));

  if v_inv.id is not null then
    update public.event_invitations set status = 'registered', registration_id = v_reg, decided_at = now() where id = v_inv.id;
    update public.notifications set read_at = coalesce(read_at, now()) where kind = 'event_invited' and payload ->> 'invitation_id' = v_inv.id::text;
    perform private.accept_registration_core(v_reg);
    perform private.audit(p_event, 'registration.accepted', v_reg::text, jsonb_build_object('via', 'invitation', 'invitation', v_inv.id));
  else
    -- The receipt (in-app; Pack 15's system). Event name and slug only: no fee, contact, health or account data.
    begin
      update public.notifications set read_at = coalesce(read_at, now())
       where user_id = auth.uid() and kind = 'registration_received' and read_at is null and payload ->> 'registration_id' = v_reg::text;
      insert into public.notifications (user_id, kind, payload)
      values (auth.uid(), 'registration_received', jsonb_build_object('registration_id', v_reg, 'event_name', v_event.name, 'event_slug', v_event.slug, 'again', v_existing.id is not null));
    exception when others then
      raise warning 'registration % was saved; its receipt notification was not: %', v_reg, sqlerrm;
    end;
  end if;
  return v_reg;
end $function$
;$bos$, $bos$drop function if exists public.submit_registration(p_event uuid, p_data jsonb, p_adult_confirmed boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'team_career' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.team_career(p_team uuid)
 RETURNS TABLE(context text, scope text, season_id uuid, organization_id uuid, category text, category_name text, gender text, events integer, competitions integer, matches integer, wins integer, losses integer, draws integer, win_pct numeric, golds integer, silvers integer, bronzes integer, podiums integer, points numeric, best_place integer, first_on date, last_on date)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with facts as (
    select case when f.synthetic then 'test' else 'official' end as ctx, f.season_id, f.organization_id, f.category, f.category_name, f.gender,
      f.event_id, null::uuid as result_comp, f.match_id, f.outcome, null::int as place, null::numeric as pts, f.event_ends_on
    from private.team_fight_rows(p_team) f where not f.stats_excluded
    union all
    select case when r.synthetic then 'test' else 'official' end, r.season_id, r.organization_id, r.category, coalesce(rc.name, r.category), r.gender,
      r.event_id, r.competition_id, null, null, r.final_place, r.points, r.event_ends_on
    from private.team_result_rows(p_team) r left join public.ref_categories rc on rc.code = r.category where not r.stats_excluded
  ), agg as (
    select ctx, season_id, organization_id, category, category_name, gender,
      grouping(season_id) as gs, grouping(organization_id) as go,
      count(distinct event_id) as events, count(distinct result_comp) as competitions,
      count(match_id) as matches, count(match_id) filter (where outcome = 'win') as wins, count(match_id) filter (where outcome = 'loss') as losses,
      count(match_id) filter (where outcome = 'draw') as draws,
      count(place) filter (where place = 1) as golds, count(place) filter (where place = 2) as silvers, count(place) filter (where place = 3) as bronzes,
      coalesce(sum(pts), 0) as points, min(place) as best_place, min(event_ends_on) as first_on, max(event_ends_on) as last_on
    from facts
    group by grouping sets ((ctx), (ctx, season_id), (ctx, organization_id), (ctx, category, category_name, gender),
      (ctx, season_id, category, category_name, gender), (ctx, organization_id, category, category_name, gender))
  )
  select ctx, case when gs = 0 then 'season' when go = 0 then 'organization' else 'career' end, season_id, organization_id, category, category_name, gender,
    events::int, competitions::int, matches::int, wins::int, losses::int, draws::int,
    case when matches = 0 then null else round(wins * 100.0 / matches, 1) end,
    golds::int, silvers::int, bronzes::int, (golds + silvers + bronzes)::int, points, best_place, first_on, last_on
  from agg
  where not (gs = 0 and season_id is null) and not (go = 0 and organization_id is null)
$function$
;$bos$, $bos$drop function if exists public.team_career(p_team uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'team_fighters_represented' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.team_fighters_represented(p_team uuid)
 RETURNS TABLE(context text, fighter_id uuid, display_name text, active boolean, individual_results integer, individual_fights integer, team_fights integer, first_on date, last_on date)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with facts as (
    select case when r.synthetic then 'test' else 'official' end as ctx, r.fighter_id, r.competition_id as result_comp, null::uuid as match_id, 'individual' as kind, r.event_ends_on
    from private.career_result_rows(null, p_team) r where r.team_id = p_team and r.kind = 'individual' and not r.stats_excluded
    union all
    select case when f.synthetic then 'test' else 'official' end, f.fighter_id, null, f.match_id, f.kind, f.event_ends_on
    from private.career_fight_rows(null, p_team) f where f.team_id = p_team and not f.stats_excluded
  )
  select x.ctx, x.fighter_id, fi.display_name, fi.inactive_at is null,
    count(distinct x.result_comp)::int, count(x.match_id) filter (where x.kind = 'individual')::int, count(x.match_id) filter (where x.kind = 'team')::int,
    min(x.event_ends_on), max(x.event_ends_on)
  from facts x join public.fighters fi on fi.id = x.fighter_id
  group by x.ctx, x.fighter_id, fi.display_name, fi.inactive_at
  order by 1, 9 desc, 3
$function$
;$bos$, $bos$drop function if exists public.team_fighters_represented(p_team uuid);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'team_head_to_head' and pg_get_function_identity_arguments(p.oid) = $bos$p_team uuid$bos$), $bos$CREATE OR REPLACE FUNCTION public.team_head_to_head(p_team uuid)
