select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'update_club_notice' and pg_get_function_identity_arguments(p.oid) = $bos$p_notice uuid, p_title text, p_body text, p_pinned boolean$bos$), $bos$CREATE OR REPLACE FUNCTION public.update_club_notice(p_notice uuid, p_title text, p_body text, p_pinned boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.club_notices; v_title text := btrim(coalesce(p_title, '')); v_body text := btrim(coalesce(p_body, ''));
begin
  select * into n from public.club_notices where id = p_notice;
  if not found then raise exception 'notice not found' using errcode = 'P0002'; end if;
  perform private.club_notice_manage_check(n.team_id);
  if char_length(v_title) < 3 or char_length(v_title) > 120 then raise exception 'give the notice a short title (3 to 120 characters)' using errcode = '22023'; end if;
  if char_length(v_body) < 1 or char_length(v_body) > 4000 then raise exception 'write the notice (up to 4000 characters)' using errcode = '22023'; end if;
  update public.club_notices set title = v_title, body = v_body, pinned = coalesce(p_pinned, n.pinned), updated_at = now() where id = p_notice;
  perform private.audit(null, 'club.notice_updated', p_notice::text, jsonb_build_object('team', n.team_id));
end $function$
;$bos$, $bos$drop function if exists public.update_club_notice(p_notice uuid, p_title text, p_body text, p_pinned boolean);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'update_my_fighter_profile' and pg_get_function_identity_arguments(p.oid) = $bos$p jsonb$bos$), $bos$CREATE OR REPLACE FUNCTION public.update_my_fighter_profile(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_f uuid; k text; v jsonb; v_txt text; v_year int; v_arr text[]; v_max int;
  t_text constant text[] := array['gender','city','region','country','fighting_style','bio'];
  t_int constant text[] := array['birth_year','joined_year'];
  t_arr constant text[] := array['disciplines','highlights'];
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  select fighter_id into v_f from public.fighter_accounts where user_id = auth.uid();
  if v_f is null then raise exception 'you have no fighter profile yet' using errcode = '42501'; end if;
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'send the profile as an object' using errcode = '22023'; end if;
  for k, v in select key, value from jsonb_each(p) loop
    if k = any (t_text) then
      if jsonb_typeof(v) not in ('string', 'null') then raise exception '% must be text', k using errcode = '22023'; end if;
      v_txt := nullif(btrim(v #>> '{}'), '');
      v_max := case k when 'bio' then 1500 when 'fighting_style' then 120 else 80 end;
      if char_length(coalesce(v_txt, '')) > v_max then raise exception '% is too long', k using errcode = '22023'; end if;
      if k = 'gender' and v_txt is not null and v_txt not in ('male', 'female', 'other') then raise exception 'gender must be male, female or other' using errcode = '22023'; end if;
      execute format('update public.fighters set %I = $1 where id = $2', k) using v_txt, v_f;
    elsif k = any (t_int) then
      if jsonb_typeof(v) = 'null' then v_year := null;
      elsif jsonb_typeof(v) <> 'number' or (v #>> '{}') !~ '^[0-9]{4}$' then raise exception '% must be a four digit year', k using errcode = '22023';
      else v_year := (v #>> '{}')::int; end if;
      if v_year is not null and k = 'birth_year' and v_year not between 1900 and extract(year from current_date)::int then raise exception 'birth year is out of range' using errcode = '22023'; end if;
      if v_year is not null and k = 'joined_year' and v_year not between 1990 and extract(year from current_date)::int then raise exception 'joined year is out of range' using errcode = '22023'; end if;
      if k = 'birth_year' then perform private.set_fighter_private(v_f, 'birth_year', v_year::text);
      else execute format('update public.fighters set %I = $1 where id = $2', k) using v_year, v_f; end if;
    elsif k = any (t_arr) then
      if jsonb_typeof(v) = 'null' then v_arr := '{}';
      elsif jsonb_typeof(v) <> 'array' then raise exception '% must be a list', k using errcode = '22023';
      else
        if exists (select 1 from jsonb_array_elements(v) e where jsonb_typeof(e) <> 'string') then raise exception 'every item in % must be text', k using errcode = '22023'; end if;
        select coalesce(array_agg(btrim(e #>> '{}') order by o), '{}') into v_arr from jsonb_array_elements(v) with ordinality x(e, o);
      end if;
      v_max := case k when 'disciplines' then 12 else 10 end;
      if cardinality(v_arr) > v_max then raise exception 'too many items in %', k using errcode = '22023'; end if;
      execute format('update public.fighters set %I = $1 where id = $2', k) using v_arr, v_f;
    elsif k = 'social_links' then
      update public.fighters set social_links = private.clean_social_links(v) where id = v_f;
    else
      raise exception 'the profile has a field this version does not know: %', left(k, 40) using errcode = '22023';
    end if;
  end loop;
  perform private.audit(null, 'fighter.profile_updated', v_f::text, jsonb_build_object('fields', (select coalesce(jsonb_agg(key), '[]'::jsonb) from jsonb_object_keys(p) key)));
end $function$
;$bos$, $bos$drop function if exists public.update_my_fighter_profile(p jsonb);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'update_privacy_breach' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p jsonb, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.update_privacy_breach(p_id uuid, p jsonb, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f jsonb; b public.privacy_breaches; v_old jsonb; v_changed jsonb := '{}'::jsonb; k text;
begin
  if not private.is_owner() then raise exception 'only the platform owner keeps the breach register' using errcode = '42501'; end if;
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'send the changes as an object' using errcode = '22023'; end if;
  select * into b from public.privacy_breaches where id = p_id for update;
  if not found then raise exception 'that breach is not in the register' using errcode = 'P0002'; end if;
  f := private.breach_fields(p);
  if f ? 'summary' and char_length(coalesce(f ->> 'summary', '')) < 10 then raise exception 'describe what happened in at least a sentence' using errcode = '22023'; end if;
  if f ? 'status' and coalesce(f ->> 'status', '') not in ('open', 'closed') then raise exception 'unknown status' using errcode = '22023'; end if;
  if f ? 'risk' and coalesce(f ->> 'risk', '') not in ('not_assessed', 'no_real_risk', 'real_risk') then raise exception 'unknown risk assessment' using errcode = '22023'; end if;
  if f ? 'discovered_at' and f ->> 'discovered_at' is null then raise exception 'the discovery date cannot be emptied' using errcode = '22023'; end if;
  v_old := to_jsonb(b);
  for k in select jsonb_object_keys(f) loop
    if (v_old -> k) is distinct from (f -> k) and not (k like '%\_at' and (v_old ->> k)::timestamptz is not distinct from (f ->> k)::timestamptz) then
      v_changed := v_changed || jsonb_build_object(k, jsonb_build_object('from', v_old -> k, 'to', f -> k));
    end if;
  end loop;
  if v_changed = '{}'::jsonb and nullif(btrim(coalesce(p_note, '')), '') is null then return; end if;
  update public.privacy_breaches set
    discovered_at = case when f ? 'discovered_at' then (f ->> 'discovered_at')::timestamptz else discovered_at end,
    occurred_at = case when f ? 'occurred_at' then (f ->> 'occurred_at')::timestamptz else occurred_at end,
    summary = case when f ? 'summary' then f ->> 'summary' else summary end,
    data_involved = case when f ? 'data_involved' then f ->> 'data_involved' else data_involved end,
    people_affected = case when f ? 'people_affected' then f ->> 'people_affected' else people_affected end,
    risk = case when f ? 'risk' then f ->> 'risk' else risk end,
    risk_reasoning = case when f ? 'risk_reasoning' then f ->> 'risk_reasoning' else risk_reasoning end,
    containment = case when f ? 'containment' then f ->> 'containment' else containment end,
    oipc_notified_at = case when f ? 'oipc_notified_at' then (f ->> 'oipc_notified_at')::timestamptz else oipc_notified_at end,
    opc_notified_at = case when f ? 'opc_notified_at' then (f ->> 'opc_notified_at')::timestamptz else opc_notified_at end,
    individuals_notified_at = case when f ? 'individuals_notified_at' then (f ->> 'individuals_notified_at')::timestamptz else individuals_notified_at end,
    status = case when f ? 'status' then f ->> 'status' else status end,
    closed_at = case when f ? 'status' then case when f ->> 'status' = 'closed' then coalesce(closed_at, now()) end else closed_at end
  where id = p_id;
  insert into public.privacy_breach_history (breach_id, actor, change, note) values (p_id, auth.uid(), v_changed, nullif(btrim(coalesce(p_note, '')), ''));
  perform private.audit(null, 'privacy.breach_updated', p_id::text, jsonb_build_object('fields', (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_object_keys(v_changed) x)));
end $function$
;$bos$, $bos$drop function if exists public.update_privacy_breach(p_id uuid, p jsonb, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'update_privacy_request' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_status text, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.update_privacy_request(p_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.privacy_requests; v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not private.is_owner() then raise exception 'only the platform owner can change privacy requests' using errcode = '42501'; end if;
  if p_status not in ('in_progress', 'extended', 'completed', 'declined') then raise exception 'unknown status' using errcode = '22023'; end if;
  select * into r from public.privacy_requests where id = p_id for update;
  if not found then raise exception 'that request does not exist' using errcode = 'P0002'; end if;
  if v_note is not null and char_length(v_note) > 1000 then raise exception 'keep the note under 1000 characters' using errcode = '22023'; end if;
  if r.status = p_status then raise exception 'the request already has that status' using errcode = '22023'; end if;
  if p_status in ('extended', 'completed', 'declined') and (v_note is null or char_length(v_note) < 3) then
    raise exception 'add a note: what was done, or why' using errcode = '22023'; end if;
  if r.closed_at is not null and p_status <> 'in_progress' then raise exception 'reopen the request first' using errcode = '22023'; end if;
  if r.closed_at is not null and (v_note is null or char_length(v_note) < 3) then raise exception 'add a note saying why it is reopened' using errcode = '22023'; end if;
  if p_status = 'extended' then
    if r.extended_at is not null then raise exception 'a request can be extended once' using errcode = '22023'; end if;
    if now() > r.due_at then raise exception 'an extension has to be given before the first 30 days end' using errcode = '22023'; end if;
  end if;
  update public.privacy_requests set
    status = p_status,
    extended_at = case when p_status = 'extended' then now() else extended_at end,
    due_at = case when p_status = 'extended' then received_at + interval '60 days' else due_at end,
    closed_at = case when p_status in ('completed', 'declined') then now() else null end
  where id = p_id;
  insert into public.privacy_request_events (request_id, actor, from_status, to_status, note) values (p_id, auth.uid(), r.status, p_status, v_note);
  perform private.audit(null, 'privacy.request_' || p_status, p_id::text, jsonb_build_object('from', r.status));
end $function$
;$bos$, $bos$drop function if exists public.update_privacy_request(p_id uuid, p_status text, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'withdraw_card' and pg_get_function_identity_arguments(p.oid) = $bos$p_id uuid, p_note text$bos$), $bos$CREATE OR REPLACE FUNCTION public.withdraw_card(p_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.cards;
begin
  select * into v_row from public.cards where id = p_id and discarded_at is null for update;
  if v_row.id is null then raise exception 'card not found' using errcode = 'P0002'; end if;
  if not (private.is_my_fighter(v_row.fighter_id) or private.can_make_cards(v_row.team_id)) then
    raise exception 'you cannot withdraw this card' using errcode = '42501'; end if;
  update public.cards set status = 'withdrawn', game_use = false, updated_at = now() where id = p_id;
  insert into public.card_consents (card_id, fighter_id, decided_by, decision, note)
  values (p_id, v_row.fighter_id, auth.uid(), 'withdrawn', left(nullif(btrim(coalesce(p_note, '')), ''), 300));
  perform private.audit(null, 'card.withdrawn', v_row.team_id::text, jsonb_build_object('card', p_id));
  return jsonb_build_object('status', 'withdrawn', 'front_path', v_row.front_path, 'back_path', v_row.back_path);
end $function$
;$bos$, $bos$drop function if exists public.withdraw_card(p_id uuid, p_note text);$bos$);
select pg_temp.bos_apply((select pg_get_functiondef(p.oid) || ';' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'withdraw_past_medal' and pg_get_function_identity_arguments(p.oid) = $bos$p_result uuid, p_reason text$bos$), $bos$CREATE OR REPLACE FUNCTION public.withdraw_past_medal(p_result uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_src constant uuid := '5c2d7e1a-3f64-4b8e-9a0c-7d1e2f3a4b5c';
  v_r public.results; v_entry public.entries; v_event uuid; v_rs public.record_sources; v_reason text;
begin
  if auth.uid() is null then raise exception 'sign in first' using errcode = '42501'; end if;
  select * into v_r from public.results r where r.id = p_result for update;
  if not found then raise exception 'that medal is not recorded' using errcode = 'P0002'; end if;
  select * into v_rs from public.record_sources rs where rs.source_id = v_src and rs.entity_type = 'result' and rs.entity_id = v_r.id;
  if not found then raise exception 'this placing is an official result, not a report; an organizer corrects it' using errcode = '22023'; end if;
  if v_rs.status <> 'unverified' then raise exception 'this medal has been verified; ask the owner to change it' using errcode = '22023'; end if;
  select * into v_entry from public.entries e where e.id = v_r.entry_id;
  v_event := private.event_of_competition(v_r.competition_id);
  if not (exists (select 1 from public.fighter_accounts fa where fa.user_id = auth.uid() and fa.fighter_id = v_entry.fighter_id) or private.is_platform_organizer()) then
    raise exception 'you can withdraw your own reported medals only' using errcode = '42501';
  end if;
  v_reason := coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'withdrawn by the fighter');
  perform set_config('bos.unlock', 'on', true);
  perform private.log_result_revision(v_r.competition_id, v_r.entry_id, 'voided', v_r.final_place, v_r.points, null, null, v_reason);
  perform private.discard_past_medal_report(v_rs.id, v_r.id, v_entry.id);
  perform private.audit(v_event, 'result.report_withdrawn', v_r.competition_id::text, jsonb_build_object('entry', v_entry.id, 'fighter', v_entry.fighter_id, 'place', v_r.final_place, 'reason', v_reason));
  perform set_config('bos.unlock', '', true);
  return jsonb_build_object('status', 'withdrawn');
end $function$
;$bos$, $bos$drop function if exists public.withdraw_past_medal(p_result uuid, p_reason text);$bos$);
