select pg_temp.bos_apply((select format('create or replace view %I.%I%s as %s', 'private', 'ranking_fighters_live', case when c.reloptions is not null then ' with (' || array_to_string(c.reloptions, ', ') || ')' else '' end, pg_get_viewdef(c.oid)) from pg_class c where c.oid = to_regclass('private.ranking_fighters_live')), $bos$create or replace view private.ranking_fighters_live with (security_invoker=true) as  WITH org_rows AS (
         SELECT fr.fighter_id,
            fr.organization_id,
            fr.season_id,
            fr.category,
            fr.gender,
            k.weight_class,
            fr.final_place,
            fr.points
           FROM (fighter_results_all fr
             JOIN competitions k ON ((k.id = fr.competition_id)))
          WHERE ((NOT fr.stats_excluded) AND ((NOT fr.synthetic) OR private.is_synthetic('organization'::text, fr.organization_id)))
        ), agg AS (
         SELECT 'season'::text AS scope,
            org_rows.organization_id,
            org_rows.season_id,
            org_rows.category,
            org_rows.gender,
            org_rows.weight_class,
            org_rows.fighter_id,
            count(*) AS competitions,
            count(*) FILTER (WHERE (org_rows.final_place = 1)) AS golds,
            count(*) FILTER (WHERE (org_rows.final_place = 2)) AS silvers,
            count(*) FILTER (WHERE (org_rows.final_place = 3)) AS bronzes,
            COALESCE(sum(org_rows.points), (0)::numeric) AS points
           FROM org_rows
          WHERE (org_rows.season_id IS NOT NULL)
          GROUP BY org_rows.organization_id, org_rows.season_id, org_rows.category, org_rows.gender, org_rows.weight_class, org_rows.fighter_id
        UNION ALL
         SELECT 'org_career'::text,
            org_rows.organization_id,
            NULL::uuid AS uuid,
            org_rows.category,
            org_rows.gender,
            org_rows.weight_class,
            org_rows.fighter_id,
            count(*) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 1)) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 2)) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 3)) AS count,
            COALESCE(sum(org_rows.points), (0)::numeric) AS "coalesce"
           FROM org_rows
          WHERE (org_rows.organization_id IS NOT NULL)
          GROUP BY org_rows.organization_id, org_rows.category, org_rows.gender, org_rows.weight_class, org_rows.fighter_id
        UNION ALL
         SELECT 'org_all'::text,
            org_rows.organization_id,
            NULL::uuid AS uuid,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            org_rows.fighter_id,
            count(*) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 1)) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 2)) AS count,
            count(*) FILTER (WHERE (org_rows.final_place = 3)) AS count,
            COALESCE(sum(org_rows.points), (0)::numeric) AS "coalesce"
           FROM org_rows
          WHERE (org_rows.organization_id IS NOT NULL)
          GROUP BY org_rows.organization_id, org_rows.fighter_id
        UNION ALL
         SELECT 'career'::text,
            NULL::uuid AS uuid,
            NULL::uuid AS uuid,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            fr.fighter_id,
            count(*) AS count,
            count(*) FILTER (WHERE (fr.final_place = 1)) AS count,
            count(*) FILTER (WHERE (fr.final_place = 2)) AS count,
            count(*) FILTER (WHERE (fr.final_place = 3)) AS count,
            COALESCE(sum(fr.points), (0)::numeric) AS "coalesce"
           FROM fighter_results fr
          GROUP BY fr.fighter_id
        )
 SELECT a.scope,
    a.organization_id,
    a.season_id,
    a.category,
    a.gender,
    a.fighter_id,
    f.display_name,
    a.competitions,
    a.golds,
    a.silvers,
    a.bronzes,
    a.points,
    rank() OVER (PARTITION BY a.scope, a.organization_id, a.season_id, a.category, a.gender, a.weight_class ORDER BY a.points DESC) AS rank,
    a.weight_class
   FROM (agg a
